window.ANSWER_TERMS = {"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"keratine":{"title":"Keratine","short":"Vezelig structuureiwit (intermediair filament) dat opperhuid, haren en nagels stevigheid en waterbestendigheid geeft.","definition":"<p><b>Keratine</b> is een taai, onoplosbaar structuureiwit uit de groep intermediaire filamenten. Keratinocyten maken het aan terwijl ze naar de oppervlakte schuiven.</p><p>In het stratum corneum vormen dode, met keratine gevulde cellen een waterafstotende barrière. Keratine is ook het hoofdbestanddeel van haar en nagels.</p>","image_url":"","wiki_title":"Keratin","match":"keratine"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycolipide":{"title":"Glycolipide","short":"Lipide met een suikergroep aan de buitenkant van de celmembraan; betrokken bij herkenning en bescherming.","definition":"<p>Een <b>glycolipide</b> is een membraanlipide waaraan aan de buitenzijde een suikerketen hangt.</p><p>Samen met glycoproteïnen vormt het de glycocalyx, die een rol speelt bij celherkenning en bescherming van het celoppervlak.</p>","image_url":"","wiki_title":"Glycolipid","match":"glycolipide|glycolipiden"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"fagocytose":{"title":"Fagocytose","short":"Het 'opeten' van grote deeltjes of hele cellen (zoals bacteriën) door een cel via insluiting in een fagosoom.","definition":"<p><b>Fagocytose</b> is een vorm van endocytose waarbij een cel grote deeltjes omsluit, zoals bacteriën, celresten of stofdeeltjes.</p><p>Het gevormde fagosoom versmelt met een lysosoom, waarna de inhoud wordt verteerd. Neutrofielen en macrofagen zijn de belangrijkste fagocyten.</p>","image_url":"","wiki_title":"Phagocytosis","match":"fagocytose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"dermis|de dermis|papillaire dermis|reticulaire dermis"},"melanocyt":{"title":"Melanocyt","short":"Pigmentcel in het stratum basale die melanine maakt en dit aan omliggende keratinocyten afgeeft.","definition":"<p>De <b>melanocyt</b> ligt in het stratum basale en produceert in melanosomen het pigment melanine.</p><p>Via uitlopers geeft hij melanine af aan naburige keratinocyten, die er hun kern mee tegen UV-schade beschermen. Verschillen in huidskleur berusten op de activiteit, niet het aantal, van melanocyten.</p>","image_url":"","wiki_title":"Melanocyte","match":"melanocyt|melanocyten"},"mestcel":{"title":"Mestcel","short":"Weefselcel vol histaminekorrels die bij allergie en ontsteking degranuleert.","definition":"<p>De <b>mestcel</b> (mastcel) zit in de dermis en andere weefsels en is volgepakt met korrels vol histamine en andere ontstekingsmediatoren.</p><p>Bij binding van allergenen aan IgE op zijn oppervlak stort hij zijn korrels uit (degranulatie), wat jeuk, roodheid en zwelling geeft.</p>","image_url":"","wiki_title":"Mast cell","match":"mestcel|mestcellen|mastcel"},"filaggrine":{"title":"Filaggrine","short":"Eiwit dat keratinefilamenten bundelt en afbraakproducten levert die de huid vocht vasthouden.","definition":"<p><b>Filaggrine</b> bundelt in de bovenste epidermislagen de keratinefilamenten tot stevige bundels.</p><p>De afbraakproducten vormen de 'natural moisturizing factor' die vocht vasthoudt. Een filaggrine-gendefect is een belangrijke oorzaak van constitutioneel eczeem (atopische dermatitis).</p>","image_url":"","wiki_title":"Filaggrin","match":"filaggrine|filagrine"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"pustula":{"title":"Pustula","short":"Met pus gevuld blaasje in de huid (een 'puistje').","definition":"<p>Een <b>pustula</b> (pustel) is een verheven blaasje gevuld met pus (dode neutrofielen).</p><p>Pustels kunnen steriel zijn (psoriasis pustulosa) of door bacteriën ontstaan; ze zijn kenmerkend voor acne.</p>","image_url":"","wiki_title":"Pustule","match":"pustula|pustel|pustels|pustula|pustulae"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"crusta":{"title":"Crusta","short":"Korstje van ingedroogd wondvocht, bloed of pus op het huidoppervlak.","definition":"<p>Een <b>crusta</b> (korst) is opgedroogd exsudaat — wondvocht, bloed of pus — op de huid.</p><p>Het is een secundaire efflorescentie die ontstaat nadat een blaasje of wondje is opengegaan.</p>","image_url":"","wiki_title":"Crust (dermatology)","match":"crusta|crustae|korst"},"squama":{"title":"Squama","short":"Zichtbare hoornschilfer door versnelde of gestoorde verhoorning van de opperhuid.","definition":"<p>Een <b>squama</b> (schilfer) is een loskomend plaatje hoorncellen van het stratum corneum.</p><p>Overmatige schilfering is typerend voor psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Desquamation","match":"squama|squamae|schilfer|schilfering"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"fissuur":{"title":"Fissuur","short":"Pijnlijke, spleetvormige scheur in de huid, vaak op handen of hielen (kloof/rhagade).","definition":"<p>Een <b>fissuur</b> (rhagade, kloof) is een smalle, spleetvormige scheur in de huid die tot in de dermis kan reiken.</p><p>Ze ontstaat vooral in droge, verdikte huid op belaste plaatsen zoals vingers, handen en hielen, en kan pijnlijk zijn.</p>","image_url":"","wiki_title":"Fissure","match":"fissuur|rhagade|rhagaden|kloof"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"constitutioneel eczeem":{"title":"Constitutioneel eczeem","short":"Chronisch, jeukend, atopisch eczeem met een gestoorde huidbarrière; begint meestal op de kinderleeftijd.","definition":"<p><b>Constitutioneel eczeem</b> (atopische dermatitis) is een chronische, jeukende huidontsteking die vaak al bij baby's begint.</p><p>Een gestoorde huidbarrière (o.a. door filaggrine-defect) en atopische aanleg spelen een rol. Bij kinderen zit het typisch in de elleboog- en knieplooien.</p>","image_url":"","wiki_title":"Atopic dermatitis","match":"constitutioneel eczeem|atopisch eczeem|atopische dermatitis"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"mrna":{"title":"mRNA","short":"Boodschapper-RNA dat de genetische code van het DNA naar de ribosomen brengt voor eiwitsynthese.","definition":"<p><b>mRNA</b> (messenger RNA) is de kopie van een gen die tijdens transcriptie in de kern wordt gemaakt.</p><p>Het reist naar het cytoplasma, waar ribosomen de codons aflezen om er een eiwit van te maken (translatie).</p>","image_url":"","wiki_title":"Messenger RNA","match":"mrna|messenger rna|boodschapper-rna"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"escherichia coli":{"title":"Escherichia coli","short":"E. coli is een gramnegatieve staafbacterie die normaal in de darm leeft en de belangrijkste verwekker is van urineweginfecties.","definition":"<p><strong><em>Escherichia coli</em></strong> is een gramnegatieve, facultatief anaerobe staaf uit de familie van de <em>Enterobacteriaceae</em>. Het is een normaal onderdeel van de darmflora.</p><p>Buiten de darm is E. coli de belangrijkste verwekker van urineweginfecties (cystitis, pyelonefritis) en een belangrijke oorzaak van sepsis en neonatale meningitis. Sommige stammen (zoals EHEC en ETEC) veroorzaken diarree; EHEC kan via shigatoxine het hemolytisch-uremisch syndroom veroorzaken.</p>","image_url":"","wiki_title":"Escherichia coli","match":"escherichia coli|e. coli|e.coli","option_only":true},"streptococcus pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae|s. pneumoniae|pneumokok|pneumokokken|streptococcus pneumoniae (pneumokok)","option_only":true},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"staphylococcus epidermidis":{"title":"Staphylococcus epidermidis","short":"S. epidermidis is een coagulasenegatieve stafylokok van de normale huidflora; berucht om infecties van lijnen en prothesen.","definition":"<p><strong><em>Staphylococcus epidermidis</em></strong> is een grampositieve, <em>coagulase-negatieve</em> stafylokok die normaal op de huid leeft.</p><p>Hij is weinig virulent, maar kan een <em>biofilm</em> vormen op kunstmateriaal. Daardoor is hij een belangrijke verwekker van infecties van intravasculaire katheters, kunstkleppen en gewrichtsprothesen. In een bloedkweek is hij ook vaak een verontreiniging vanuit de huid.</p>","image_url":"","wiki_title":"Staphylococcus epidermidis","match":"staphylococcus epidermidis|s. epidermidis","option_only":true},"pseudomonas aeruginosa":{"title":"Pseudomonas aeruginosa","short":"P. aeruginosa is een gramnegatieve, aerobe staaf die van vochtige omgevingen houdt en vooral bij verzwakte patiënten ziekenhuisinfecties veroorzaakt.","definition":"<p><strong><em>Pseudomonas aeruginosa</em></strong> is een gramnegatieve, strikt aerobe staaf die leeft in water en vochtige omgevingen. Hij is van nature resistent tegen veel antibiotica.</p><p>Hij veroorzaakt vooral opportunistische infecties: ziekenhuispneumonie (o.a. bij beademing), infecties van brandwonden, urineweginfecties bij katheters, otitis externa en chronische luchtweginfecties bij cystische fibrose. Kolonies hebben vaak een groenblauw pigment en een zoete geur.</p>","image_url":"","wiki_title":"Pseudomonas aeruginosa","match":"pseudomonas aeruginosa|p. aeruginosa|pseudomonas","option_only":true},"klebsiella pneumoniae":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella pneumoniae|k. pneumoniae|klebsiella","option_only":true},"haemophilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenzae|h. influenzae|haemophilus|haemofilus influenzae type b|haemophilus influenzae type b|hib","option_only":true},"mycobacterium tuberculosis":{"title":"Mycobacterium tuberculosis","short":"M. tuberculosis is de zuurvaste, langzaam groeiende staafbacterie die tuberculose veroorzaakt.","definition":"<p><strong><em>Mycobacterium tuberculosis</em></strong> is een aerobe staafbacterie met een wasachtige, mycolzuurrijke celwand. Daardoor kleurt hij niet goed met de gramkleuring maar wel met de Ziehl-Neelsenkleuring (<em>zuurvast</em>).</p><p>Hij wordt aerogeen overgedragen, groeit zeer langzaam (weken in kweek) en overleeft in macrofagen. De afweer is vooral cellulair (T-cellen) en leidt tot granulomen met centrale verkazing. Hij veroorzaakt tuberculose.</p>","image_url":"","wiki_title":"Mycobacterium tuberculosis","match":"mycobacterium tuberculosis|m. tuberculosis|tuberkelbacil","option_only":true},"candida albicans":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida albicans|c. albicans|candida","option_only":true},"adenovirus":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirus|adenovirussen","option_only":true},"mazelenvirus":{"title":"Mazelen(virus)","short":"Mazelen is een zeer besmettelijke virale kinderziekte met hoge koorts, hoesten, conjunctivitis en een vlekkerige huiduitslag; het virus is een omhuld RNA-virus.","definition":"<p><strong>Mazelen</strong> (morbilli) wordt veroorzaakt door het mazelenvirus, een omhuld enkelstrengs RNA-virus (paramyxovirus). Het is een van de meest besmettelijke ziekten en verspreidt zich via aerosolen.</p><p>Na een prodromale fase met koorts, hoesten, rhinitis en conjunctivitis verschijnen <em>Koplikvlekjes</em> op het wangslijmvlies en daarna een grofvlekkige rode huiduitslag die achter de oren begint. Complicaties zijn otitis, pneumonie en zeldzaam encefalitis (ook SSPE jaren later). Mazelen onderdrukt tijdelijk het immuunsysteem. Er is een vaccin (BMR).</p>","image_url":"","wiki_title":"Measles","match":"mazelenvirus|mazelen|morbilli|morbillivirus","option_only":true},"influenzavirus":{"title":"Influenza(virus)","short":"Influenza (griep) wordt veroorzaakt door het influenzavirus, een omhuld RNA-virus met hoge koorts, spierpijn en hoesten; jaarlijks seizoensgebonden.","definition":"<p><strong>Influenza</strong> wordt veroorzaakt door influenzavirussen (type A, B en C), omhulde RNA-virussen met een gesegmenteerd genoom. Op het oppervlak zitten hemagglutinine (H) en neuraminidase (N).</p><p>Kleine mutaties in H en N (<em>antigene drift</em>) veroorzaken de jaarlijkse griepepidemie; uitwisseling van gensegmenten (<em>antigene shift</em>, alleen type A) kan pandemieën geven. Klachten: plotselinge hoge koorts, spierpijn, hoofdpijn, droge hoest. Complicatie is o.a. een secundaire bacteriële pneumonie. Jaarlijks vaccin voor risicogroepen.</p>","image_url":"","wiki_title":"Influenza","match":"influenzavirus|influenza|griep|influenza a|influenzavirussen","option_only":true},"kinkhoest":{"title":"Kinkhoest (pertussis)","short":"Kinkhoest is een luchtweginfectie door Bordetella pertussis met langdurige hoestbuien en een gierende inademing; gevaarlijk voor zuigelingen.","definition":"<p><strong>Kinkhoest</strong> (pertussis) wordt veroorzaakt door de gramnegatieve bacterie <em>Bordetella pertussis</em>, die zich hecht aan het trilhaarepitheel en toxines produceert.</p><p>Na een verkoudheidsfase volgen weken met heftige hoestbuien, vaak eindigend in een gierende inademing (‘kink’) of braken. Bij jonge zuigelingen kan kinkhoest apneus en overlijden veroorzaken; daarom wordt gevaccineerd (ook zwangeren, om de baby te beschermen).</p>","image_url":"","wiki_title":"Whooping cough","match":"kinkhoest|pertussis|bordetella pertussis","option_only":true},"difterie":{"title":"Difterie","short":"Difterie is een infectie door Corynebacterium diphtheriae waarbij een toxine een grijs pseudomembraan in de keel en schade aan hart en zenuwen veroorzaakt.","definition":"<p><strong>Difterie</strong> wordt veroorzaakt door toxineproducerende stammen van <em>Corynebacterium diphtheriae</em>, een grampositieve staaf. Het difterietoxine remt de eiwitsynthese van gastheercellen.</p><p>Lokaal ontstaat een grijswit, vastzittend <em>pseudomembraan</em> in keel en neus, met risico op luchtwegobstructie. Het toxine kan systemisch myocarditis en neuropathie geven. Door vaccinatie (DKTP) is het in Nederland zeldzaam.</p>","image_url":"","wiki_title":"Diphtheria","match":"difterie|corynebacterium diphtheriae","option_only":true},"tetanus":{"title":"Tetanus","short":"Tetanus is een vergiftiging door het toxine van Clostridium tetani uit een wond, met pijnlijke spierkrampen en kaakklem.","definition":"<p><strong>Tetanus</strong> wordt veroorzaakt door <em>Clostridium tetani</em>, een anaerobe, sporenvormende grampositieve staaf die in de bodem voorkomt en via wonden binnenkomt.</p><p>Het toxine tetanospasmine blokkeert in het ruggenmerg de afgifte van remmende neurotransmitters (glycine, GABA). Daardoor ontstaan aanhoudende spiercontracties: kaakklem (trismus), risus sardonicus, opisthotonus en ademhalingsproblemen. Preventie: vaccinatie en wondverzorging.</p>","image_url":"","wiki_title":"Tetanus","match":"tetanus|clostridium tetani","option_only":true},"poliomyelitis":{"title":"Poliomyelitis","short":"Polio is een virale infectie (poliovirus, enterovirus) die bij een klein deel van de patiënten motorische voorhoorncellen beschadigt en slappe verlamming geeft.","definition":"<p><strong>Poliomyelitis</strong> wordt veroorzaakt door het poliovirus, een niet-omhuld RNA-enterovirus dat fecaal-oraal wordt overgedragen.</p><p>De meeste infecties verlopen zonder of met milde klachten. Bij een klein deel infecteert het virus de motorische <em>voorhoorncellen</em> van het ruggenmerg, met asymmetrische slappe verlamming zonder gevoelsverlies. Door vaccinatie (DKTP) is polio in Nederland vrijwel verdwenen.</p>","image_url":"","wiki_title":"Polio","match":"poliomyelitis|polio|poliovirus","option_only":true},"rode hond":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rode hond|rubella|rubellavirus","option_only":true},"cytomegalovirus":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirus|cmv","option_only":true},"norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"norovirus|noro","option_only":true},"hepatitis a":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a|hav|hepatitis a-virus","option_only":true},"hepatitis b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b|hbv|hepatitis b-virus","option_only":true},"covid-19":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"covid-19|covid|sars-cov-2|corona","option_only":true},"malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria|plasmodium|plasmodium falciparum","option_only":true},"meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"meningitis|hersenvliesontsteking|bacteriële meningitis","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"endocarditis":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis|infectieuze endocarditis|bacteriële endocarditis","option_only":true},"bètahemolytische streptokokken groep b":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt voor in darm en vagina en is een belangrijke verwekker van sepsis en meningitis bij pasgeborenen.","definition":"<p><strong>Groep B-streptokokken</strong> (<em>Streptococcus agalactiae</em>) zijn grampositieve, bètahemolytische ketenkokken. Ze komen bij een deel van de vrouwen voor in darm en vagina zonder klachten.</p><p>Tijdens de bevalling kan de baby besmet raken, met risico op neonatale sepsis, pneumonie en meningitis (vooral in de eerste levensdagen). Bij risicofactoren krijgt de moeder antibiotica tijdens de bevalling.</p>","image_url":"","wiki_title":"Group B streptococcal infection","match":"bètahemolytische streptokokken groep b|groep b streptokokken|groep b-streptokokken|gbs|streptococcus agalactiae","option_only":true},"teichoïnezuur":{"title":"Teichoïnezuur","short":"Teichoïnezuren zijn polymeren in de dikke peptidoglycaanlaag van grampositieve bacteriën; ze dragen bij aan hechting en ontstekingsactivatie.","definition":"<p><strong>Teichoïnezuren</strong> zijn polymeren van glycerol- of ribitolfosfaat die verankerd zijn in de peptidoglycaanlaag (wandteichoïnezuur) of in de celmembraan (lipoteichoïnezuur) van <em>grampositieve</em> bacteriën.</p><p>Ze geven de celwand een negatieve lading, helpen bij hechting aan gastheercellen en worden door Toll-like receptoren (TLR2) herkend, waardoor ze een ontstekingsreactie uitlokken. Gramnegatieve bacteriën hebben ze niet.</p>","image_url":"","wiki_title":"Teichoic acid","match":"teichoïnezuur|teichoinezuur|lipoteichoïnezuur|teichoïnezuren","option_only":true},"periplasmatische ruimte":{"title":"Periplasmatische ruimte","short":"De periplasmatische ruimte is de ruimte tussen de binnenmembraan en de buitenmembraan van gramnegatieve bacteriën, met daarin de dunne peptidoglycaanlaag.","definition":"<p>De <strong>periplasmatische ruimte</strong> ligt bij <em>gramnegatieve</em> bacteriën tussen de cytoplasmamembraan (binnenmembraan) en de buitenmembraan. Hierin bevindt zich de dunne peptidoglycaanlaag.</p><p>Het periplasma bevat allerlei eiwitten, zoals transport- en bindingseiwitten en enzymen; ook bèta-lactamasen kunnen hier antibiotica afbreken voordat ze hun doelwit bereiken.</p>","image_url":"","wiki_title":"Periplasm","match":"periplasmatische ruimte|periplasma","option_only":true},"recombinatie":{"title":"Recombinatie","short":"Recombinatie is het uitwisselen en opnieuw combineren van stukken DNA tussen twee DNA-moleculen, zoals bij crossing-over of na opname van vreemd DNA.","definition":"<p>Bij <strong>(genetische) recombinatie</strong> worden stukken DNA tussen twee DNA-moleculen uitgewisseld, waardoor nieuwe combinaties van genen ontstaan. Bij homologe recombinatie gebeurt dit tussen sterk gelijkende sequenties.</p><p>Bij eukaryoten treedt recombinatie op tijdens de meiose (crossing-over). Bij bacteriën is recombinatie de stap waarmee via transformatie, transductie of conjugatie binnengekomen DNA in het eigen chromosoom wordt ingebouwd.</p>","image_url":"","wiki_title":"","match":"recombinatie|genetische recombinatie|homologe recombinatie","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"glucose":{"title":"Glucose","short":"Glucose is een monosacharide (C₆H₁₂O₆) en de belangrijkste brandstof van het lichaam; de bloedspiegel wordt strak geregeld door insuline en glucagon.","definition":"<p><strong>Glucose</strong> is een hexose en de centrale brandstof van het metabolisme. Cellen breken het af via de glycolyse en daarna (aeroob) via de citroenzuurcyclus en oxidatieve fosforylering tot CO<sub>2</sub> en water, met vorming van ATP.</p><p>Het lichaam slaat glucose op als <em>glycogeen</em> in lever en spier. De bloedglucose (normaal nuchter ±4–6 mmol/L) wordt verlaagd door insuline en verhoogd door glucagon, adrenaline en cortisol. Het brein is sterk afhankelijk van glucose.</p>","image_url":"","wiki_title":"Glucose","match":"glucose|druivensuiker|bloedglucose","option_only":true},"foliumzuur":{"title":"Foliumzuur","short":"Foliumzuur (vitamine B11/B9) is nodig voor DNA-synthese; tekort geeft megaloblastaire anemie en verhoogt het risico op een neuralebuisdefect.","definition":"<p><strong>Foliumzuur</strong> (folaat) is als tetrahydrofolaat een drager van één-koolstofgroepen, nodig voor de synthese van purines en thymidine en dus voor <em>DNA-synthese</em> en celdeling.</p><p>Tekort geeft een <em>megaloblastaire (macrocytaire) anemie</em>. Een tekort rond de conceptie verhoogt het risico op neuralebuisdefecten (spina bifida); daarom wordt vrouwen met kinderwens aangeraden vanaf 4 weken voor de conceptie tot 10 weken zwangerschap foliumzuur te slikken.</p>","image_url":"","wiki_title":"Folate","match":"foliumzuur|folaat|vitamine b11|vitamine b9","option_only":true},"vitamine b1":{"title":"Vitamine B1 (thiamine)","short":"Thiamine is een cofactor voor o.a. pyruvaatdehydrogenase; tekort (vaak bij alcoholisme) geeft beriberi en Wernicke-encefalopathie.","definition":"<p><strong>Thiamine</strong> (vitamine B1) is als thiaminepyrofosfaat cofactor van enzymen in het koolhydraatmetabolisme, zoals <em>pyruvaatdehydrogenase</em>, α-ketoglutaraatdehydrogenase en transketolase.</p><p>Tekort komt vooral voor bij alcoholmisbruik en ondervoeding. Het geeft <em>beriberi</em> (neuropathie, hartfalen) en de <em>Wernicke-encefalopathie</em> (verwardheid, ataxie, oogbewegingsstoornissen), eventueel gevolgd door het syndroom van Korsakov. Geef thiamine vóór glucose bij een risicopatiënt.</p>","image_url":"","wiki_title":"Thiamine","match":"vitamine b1|thiamine|thiamine (vitamine b1)","option_only":true},"complement factoren":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"complement factoren|complementfactoren|complement|complementsysteem","option_only":true},"pneumothorax":{"title":"Pneumothorax","short":"Een pneumothorax is lucht in de pleuraholte, waardoor de long (deels) inklapt; acuut kortademig met pijn, bij spanningspneumothorax levensbedreigend.","definition":"<p>Bij een <strong>pneumothorax</strong> komt lucht tussen de pleurabladen, waardoor de negatieve intrapleurale druk verdwijnt en de long door zijn elastische terugslag inklapt.</p><p>Hij kan spontaan ontstaan (primair bij lange, slanke jonge mannen door blebs; secundair bij longziekte zoals COPD) of na trauma. Klachten: plotselinge pijn op de borst en kortademigheid; verminderd ademgeruis en hypersonore percussie. Bij een <em>spanningspneumothorax</em> hoopt lucht zich op als een ventiel, met verschuiving van het mediastinum en circulatoire shock: direct ontlasten.</p>","image_url":"","wiki_title":"Pneumothorax","match":"pneumothorax|klaplong","option_only":true},"longfibrose":{"title":"Longfibrose","short":"Bij longfibrose wordt het longinterstitium vervangen door bindweefsel; de long wordt stug, met een restrictief beeld en verminderde diffusie.","definition":"<p>Bij <strong>longfibrose</strong> leidt beschadiging en abnormaal herstel van het longinterstitium tot verlittekening. Oorzaken zijn idiopathisch (IPF), stofblootstelling (asbest, silica), auto-immuunziekten, medicatie, bestraling of chronische extrinsieke allergische alveolitis.</p><p>De long wordt stijver (lagere compliantie): een <em>restrictieve</em> longfunctiestoornis (lage TLC en VC, normale of verhoogde FEV1/FVC) met verlaagde diffusiecapaciteit. Klachten: progressieve kortademigheid en droge hoest; bij auscultatie fijne ‘knisper’crepitaties; vaak trommelstokvingers.</p>","image_url":"","wiki_title":"Pulmonary fibrosis","match":"longfibrose|pulmonale fibrose|idiopathische pulmonale fibrose|ipf","option_only":true},"neurogenese":{"title":"Neurogenese","short":"Neurogenese is het ontstaan van nieuwe neuronen uit neurale stam- en voorlopercellen; vooral in de embryonale periode.","definition":"<p><strong>Neurogenese</strong> is de vorming van neuronen uit neurale stamcellen en voorlopercellen. Het overgrote deel vindt prenataal plaats in de ventriculaire zone van de neurale buis, waarna de jonge neuronen naar hun eindpositie migreren.</p><p>Bij volwassenen is neurogenese zeer beperkt en vindt ze vooral nog plaats in de gyrus dentatus van de hippocampus (en bij dieren in de subventriculaire zone).</p>","image_url":"","wiki_title":"Neurogenesis","match":"neurogenese|neurogenesis","option_only":true},"proliferatie":{"title":"Proliferatie","short":"Proliferatie is de toename van het aantal cellen door celdeling.","definition":"<p><strong>Proliferatie</strong> is vermeerdering van cellen door celdeling (mitose). Het is een basisproces bij groei en ontwikkeling, weefselherstel en vernieuwing van bijvoorbeeld huid, darmepitheel en bloedcellen.</p><p>Proliferatie wordt gereguleerd door groeifactoren en de celcyclus-controlepunten. Ongecontroleerde proliferatie is een kenmerk van kanker.</p>","image_url":"","wiki_title":"","match":"proliferatie|celproliferatie","option_only":true},"differentiatie":{"title":"Differentiatie","short":"Differentiatie is het proces waarbij een minder gespecialiseerde cel een gespecialiseerde vorm en functie krijgt.","definition":"<p>Bij <strong>(cel)differentiatie</strong> zet een cel bepaalde genen aan en andere uit, waardoor ze een specifieke structuur en functie krijgt — bijvoorbeeld een stamcel die een neuron, spiercel of rode bloedcel wordt.</p><p>Differentiatie wordt gestuurd door signalen uit de omgeving (groeifactoren, cel-celcontact) en transcriptiefactoren. In tumoren geeft de mate van differentiatie (goed tot slecht gedifferentieerd) informatie over agressiviteit.</p>","image_url":"","wiki_title":"","match":"differentiatie|celdifferentiatie","option_only":true},"maturatie":{"title":"Maturatie","short":"Maturatie is rijping: het proces waarin een cel, weefsel of organisme zijn uiteindelijke, volwassen vorm en functie bereikt.","definition":"<p><strong>Maturatie</strong> betekent rijping. In de embryologie en voortplanting gaat het bijvoorbeeld om de rijping van geslachtscellen (oöcyt- en spermatozoönmaturatie), waarbij de meiose wordt voltooid en de cel bevruchtingsklaar wordt.</p><p>In bredere zin gebruikt men het voor de rijping van organen (bijv. longrijping, rijping van het zenuwstelsel) en van cellen van het immuunsysteem (bijv. T-celmaturatie in de thymus).</p>","image_url":"","wiki_title":"","match":"maturatie|rijping","option_only":true},"plasmamembraan":{"title":"Plasmamembraan","short":"De plasmamembraan is de fosfolipide-dubbellaag met eiwitten die de cel omgeeft en regelt wat de cel in- en uitgaat.","definition":"<p>De <strong>plasmamembraan</strong> is een dubbele laag fosfolipiden met een hydrofobe kern, waarin cholesterol en eiwitten (integraal en perifeer) zitten. Het vloeibaar-mozaïekmodel beschrijft hoe deze componenten zijdelings kunnen bewegen.</p><p>De membraan is selectief permeabel: kleine apolaire moleculen diffunderen erdoorheen, ionen en grote polaire moleculen hebben kanalen of transporters nodig. Membraaneiwitten werken daarnaast als receptoren, enzymen en hechtingsmoleculen.</p>","image_url":"","wiki_title":"Cell membrane","match":"plasmamembraan|celmembraan|cytoplasmamembraan","option_only":true},"mitralisklepstenose":{"title":"Mitralisklepstenose","short":"Bij mitralisstenose is de klep tussen linkeratrium en linkerventrikel vernauwd, meestal door reuma; het linkeratrium raakt overbelast, met boezemfibrilleren en longstuwing.","definition":"<p>Bij een <strong>mitralisklepstenose</strong> opent de mitralisklep onvoldoende. De belangrijkste oorzaak wereldwijd is <em>acuut reuma</em> in het verleden; bij ouderen ook verkalking.</p><p>De druk in het linkeratrium stijgt, het atrium verwijdt (risico op <em>boezemfibrilleren</em> en trombo-embolie) en de druk wordt doorgegeven naar de longvenen: longstuwing, kortademigheid en uiteindelijk pulmonale hypertensie. Bij auscultatie: een luide eerste toon, openingssnap en een laagfrequent diastolisch geruis.</p>","image_url":"","wiki_title":"Mitral valve stenosis","match":"mitralisklepstenose|mitralisstenose","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"anafylaxie":{"title":"Anafylaxie","short":"Anafylaxie is een acute, levensbedreigende systemische allergische reactie (meestal IgE-gemedieerd) met huidreactie, luchtwegobstructie en/of shock.","definition":"<p><strong>Anafylaxie</strong> ontstaat meestal doordat een allergeen (bijv. pinda, wespengif, penicilline) kruisverbindingen maakt met IgE op mestcellen en basofielen. Die geven massaal histamine en andere mediatoren af.</p><p>Gevolg binnen minuten: urticaria en angio-oedeem, bronchospasme en larynxoedeem, vaatverwijding en capillaire lekkage met bloeddrukdaling (anafylactische shock), en maag-darmklachten. Eerste behandeling is direct <em>adrenaline intramusculair</em>.</p>","image_url":"","wiki_title":"Anaphylaxis","match":"anafylaxie|anafylactische shock|anafylactische reactie","option_only":true},"allergie":{"title":"Allergie","short":"Een allergie is een overdreven immuunreactie op een onschuldige stof (allergeen), klassiek IgE-gemedieerd: een type I-overgevoeligheidsreactie.","definition":"<p>Bij een <strong>allergie</strong> reageert het immuunsysteem op een onschadelijk antigeen, zoals pollen, huisstofmijt of voedsel. Bij de eerste blootstelling ontstaat <em>sensibilisatie</em>: B-cellen maken onder invloed van Th2-cellen IgE, dat zich aan mestcellen bindt.</p><p>Bij herblootstelling binden allergenen dat IgE, waardoor mestcellen histamine, leukotriënen en prostaglandinen afgeven (type I-reactie): niezen, jeuk, urticaria, astma of anafylaxie. Een late fase met eosinofielen kan volgen.</p>","image_url":"","wiki_title":"Allergy","match":"allergie|allergische reactie|type i-overgevoeligheid","option_only":true},"overgevoeligheid":{"title":"Overgevoeligheid","short":"Een overgevoeligheidsreactie is een immuunreactie die schade aan het eigen lichaam veroorzaakt; ingedeeld in type I t/m IV (Gell en Coombs).","definition":"<p>Bij <strong>overgevoeligheid</strong> veroorzaakt een immuunreactie weefselschade. Volgens Gell en Coombs onderscheidt men vier typen:</p><p><em>Type I</em> (IgE, mestcellen; snel: allergie, anafylaxie), <em>type II</em> (IgG/IgM tegen celgebonden antigenen: bijv. auto-immuun hemolytische anemie), <em>type III</em> (immuuncomplexen die neerslaan: bijv. SLE, serumziekte) en <em>type IV</em> (vertraagd, T-cel-gemedieerd: bijv. contacteczeem, tuberculinereactie).</p>","image_url":"","wiki_title":"Hypersensitivity","match":"overgevoeligheid|overgevoeligheidsreactie|hypersensitiviteit","option_only":true},"epilepsie":{"title":"Epilepsie","short":"Epilepsie is een hersenaandoening met herhaalde, niet-uitgelokte epileptische aanvallen door abnormale, synchrone ontladingen van neuronen.","definition":"<p>Bij <strong>epilepsie</strong> heeft iemand de neiging tot herhaalde epileptische aanvallen. Een aanval ontstaat door een plotselinge, overmatige en gesynchroniseerde ontlading van groepen neuronen.</p><p>Aanvallen kunnen focaal beginnen (in één hersengebied; met of zonder bewustzijnsdaling) of gegeneraliseerd (beide hemisferen; bijv. tonisch-klonische aanvallen of absences). Oorzaken: genetisch, structureel (litteken, tumor, ontwikkelingsstoornis), infectieus, metabool of onbekend. Diagnostiek met anamnese/heteroanamnese, EEG en MRI.</p>","image_url":"","wiki_title":"Epilepsy","match":"epilepsie","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"angiogenese":{"title":"Angiogenese","short":"Angiogenese is de vorming van nieuwe bloedvaten uit bestaande vaten, gestimuleerd door o.a. VEGF; belangrijk bij wondgenezing en tumorgroei.","definition":"<p>Bij <strong>angiogenese</strong> spruiten nieuwe capillairen uit bestaande vaten. Endotheelcellen breken de basaalmembraan af, migreren, prolifereren en vormen nieuwe buisjes, gevolgd door rekrutering van pericyten.</p><p>Het belangrijkste stimulerende signaal is <em>VEGF</em>, dat o.a. bij hypoxie wordt gemaakt. Angiogenese is essentieel bij embryonale ontwikkeling, wondgenezing (granulatieweefsel) en de menstruele cyclus, maar ook bij tumorgroei en diabetische retinopathie; VEGF-remmers worden daarom bij kanker en maculadegeneratie gebruikt.</p>","image_url":"","wiki_title":"Angiogenesis","match":"angiogenese|neovascularisatie|angiogenesis","option_only":true},"b-cellen":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b-cellen|b cellen|b-lymfocyten|b-cel|b-lymfocyt|b cel","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"neutrofielen":{"title":"Neutrofiele granulocyten","short":"Neutrofielen zijn de meest voorkomende witte bloedcellen; ze zijn als eerste ter plekke bij een acute bacteriële ontsteking en fagocyteren bacteriën.","definition":"<p><strong>Neutrofiele granulocyten</strong> hebben een gesegmenteerde kern en korrels met afbrekende enzymen. Ze leven maar kort (uren tot dagen) en worden in grote aantallen in het beenmerg gemaakt.</p><p>Bij een acute ontsteking verlaten ze als eerste de bloedbaan (marginatie, rollen, adhesie, diapedese) en volgen ze chemotactische signalen (o.a. IL-8, C5a). Ze fagocyteren en doden bacteriën met een oxidatieve burst en enzymen en kunnen ‘NETs’ uitwerpen. Pus bestaat grotendeels uit dode neutrofielen.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofielen|neutrofiele granulocyten|neutrofiel|neutrofiele granulocyt","option_only":true},"gezondheidsvoorlichting":{"title":"Gezondheidsvoorlichting","short":"Gezondheidsvoorlichting is het planmatig geven van informatie om kennis, houding en gedrag rond gezondheid te beïnvloeden.","definition":"<p><strong>Gezondheidsvoorlichting</strong> is een methode binnen gezondheidsbevordering. Het richt zich op het overdragen van kennis en het beïnvloeden van attitudes, zodat mensen gezondere keuzes maken — bijvoorbeeld campagnes over roken, alcohol of veilig vrijen.</p><p>Voorlichting alleen verandert gedrag vaak beperkt; het werkt beter in combinatie met maatregelen in de omgeving en regelgeving.</p>","image_url":"","wiki_title":"","match":"gezondheidsvoorlichting|voorlichting","option_only":true},"depressieve stoornis":{"title":"Depressieve stoornis","short":"Een depressieve stoornis kenmerkt zich door minstens twee weken een sombere stemming en/of verlies van interesse en plezier, met o.a. slaap-, eetlust- en concentratieproblemen.","definition":"<p>Voor een <strong>depressieve stoornis</strong> (DSM-5) moeten gedurende minstens twee weken vijf of meer symptomen aanwezig zijn, waaronder ten minste één kernsymptoom: <em>depressieve stemming</em> of <em>verlies van interesse of plezier</em> (anhedonie).</p><p>Andere symptomen: veranderde eetlust of gewicht, slapeloosheid of juist veel slapen, psychomotorische remming of agitatie, vermoeidheid, schuldgevoelens of waardeloosheid, concentratieproblemen en gedachten aan de dood. Behandeling met psychotherapie en/of antidepressiva.</p>","image_url":"","wiki_title":"Major depressive disorder","match":"depressieve stoornis|depressie|depressieve episode|majeure depressie","option_only":true},"crp":{"title":"CRP (C-reactief proteïne)","short":"CRP is een acutefase-eiwit uit de lever dat binnen een dag sterk stijgt bij ontsteking of infectie, vooral bacterieel.","definition":"<p><strong>C-reactief proteïne</strong> wordt door de lever gemaakt onder invloed van vooral <em>IL-6</em>. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen en activeert zo complement (opsonisatie).</p><p>Het CRP stijgt binnen 6–12 uur na het begin van een ontsteking en daalt snel bij herstel, waardoor het een nuttige maat is voor ontstekingsactiviteit. Bacteriële infecties geven vaak een hoger CRP dan virale, maar de waarde is niet specifiek.</p>","image_url":"","wiki_title":"C-reactive protein","match":"crp|c-reactief proteïne|c-reactief proteine","option_only":true},"bof":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bof|parotitis epidemica|bofvirus","option_only":true},"astma":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma|asthma|astma bronchiale","option_only":true},"vitamine b12":{"title":"Vitamine B12 (cobalamine)","short":"Vitamine B12 is nodig voor DNA-synthese en de myelinevorming; opname vereist intrinsieke factor uit de maag en een gezond terminaal ileum.","definition":"<p><strong>Vitamine B12</strong> komt alleen uit dierlijke producten. In de maag bindt het aan intrinsieke factor (van pariëtale cellen); het complex wordt in het terminale ileum opgenomen. B12 is cofactor van methioninesynthase (koppeling met foliumzuur) en methylmalonyl-CoA-mutase. Tekort ontstaat door bijv. auto-immuungastritis (pernicieuze anemie), maag- of ileumresectie, metformine of veganisme, en geeft macrocytaire anemie en neurologische schade.</p>","image_url":"","wiki_title":"Vitamin B12","match":"vitamine b12|cobalamine|b12","option_only":true},"vitamine a":{"title":"Vitamine A (retinol)","short":"Vitamine A is een in vet oplosbare vitamine die nodig is voor het zien in het donker, de opbouw van epitheel en de afweer.","definition":"<p><strong>Vitamine A</strong> komt als retinol uit dierlijke producten en als bètacaroteen uit groenten. In de retina vormt retinal samen met opsine het lichtgevoelige rodopsine. Retinoïnezuur reguleert de groei en differentiatie van epitheel. Tekort geeft nachtblindheid, droge ogen (xeroftalmie) en meer infecties; overmaat is teratogeen en levertoxisch.</p>","image_url":"","wiki_title":"Vitamin A","match":"vitamine a|retinol|retinoïnezuur","option_only":true},"vitamine c":{"title":"Vitamine C (ascorbinezuur)","short":"Vitamine C is een in water oplosbare vitamine die nodig is voor de collageensynthese en werkt als antioxidant.","definition":"<p><strong>Vitamine C</strong> is cofactor van prolyl- en lysylhydroxylase, die collageen stabiliseren. Het bevordert ook de opname van non-heemijzer en werkt als antioxidant. Tekort geeft <em>scheurbuik</em>: tandvleesbloedingen, perifolliculaire bloedinkjes, slechte wondgenezing en loszittende tanden.</p>","image_url":"","wiki_title":"Vitamin C","match":"vitamine c|ascorbinezuur","option_only":true},"vitamine d":{"title":"Vitamine D","short":"Vitamine D bevordert de opname van calcium en fosfaat uit de darm en is nodig voor sterke botten.","definition":"<p><strong>Vitamine D</strong> wordt in de huid onder invloed van UVB-licht gemaakt of via de voeding opgenomen. De lever zet het om in 25-OH-vitamine D en de nier (onder invloed van PTH) in het actieve 1,25-(OH)₂-vitamine D (calcitriol). Calcitriol verhoogt de opname van calcium en fosfaat in de darm. Tekort geeft rachitis bij kinderen en osteomalacie bij volwassenen.</p>","image_url":"","wiki_title":"Vitamin D","match":"vitamine d|calcitriol|colecalciferol|vitamine d3","option_only":true},"vitamine e":{"title":"Vitamine E (tocoferol)","short":"Vitamine E is een in vet oplosbare antioxidant die celmembranen beschermt tegen oxidatieve schade.","definition":"<p><strong>Vitamine E</strong> (tocoferol) beschermt meervoudig onverzadigde vetzuren in membranen tegen lipideperoxidatie. Tekort is zeldzaam en komt vooral voor bij vetmalabsorptie (bijv. cystische fibrose, cholestase); het geeft neurologische klachten zoals ataxie en neuropathie, en hemolytische anemie bij prematuren.</p>","image_url":"","wiki_title":"Vitamin E","match":"vitamine e|tocoferol","option_only":true},"vitamine k":{"title":"Vitamine K","short":"Vitamine K is nodig voor de activatie van stollingsfactoren II, VII, IX en X en eiwit C en S in de lever.","definition":"<p><strong>Vitamine K</strong> is cofactor van het enzym γ-glutamylcarboxylase, dat glutamaatresten van stollingsfactoren carboxyleert zodat ze calcium kunnen binden. Cumarines (zoals acenocoumarol en fenprocoumon) remmen de recycling van vitamine K. Pasgeborenen krijgen vitamine K om bloedingen te voorkomen, omdat ze weinig voorraad en nog geen darmflora hebben.</p>","image_url":"","wiki_title":"Vitamin K","match":"vitamine k|fytomenadion|vitamine k1","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"natrium":{"title":"Natrium","short":"Natrium is het belangrijkste kation buiten de cel; het bepaalt grotendeels het extracellulaire volume en de osmolaliteit.","definition":"<p><strong>Natrium</strong> wordt door de Na⁺/K⁺-ATPase buiten de cel gehouden, waardoor een gradiënt ontstaat die nodig is voor actiepotentialen en secundair actief transport. De hoeveelheid natrium in het lichaam bepaalt het extracellulaire volume (via RAAS en natriuretische peptiden); de natriumconcentratie weerspiegelt vooral de waterbalans (via ADH en dorst).</p>","image_url":"","wiki_title":"Sodium in biology","match":"natrium|na+|natriumion","option_only":true},"kalium":{"title":"Kalium","short":"Kalium is het belangrijkste kation in de cel; de spiegel in het bloed is cruciaal voor de membraanpotentiaal van hart en spieren.","definition":"<p>Ongeveer 98% van het <strong>kalium</strong> zit intracellulair. De extracellulaire concentratie (3,5–5 mmol/L) bepaalt de rustmembraanpotentiaal. Insuline, bèta-2-agonisten en alkalose verschuiven kalium de cel in; aldosteron bevordert de uitscheiding in de nier. Zowel te hoge als te lage waarden kunnen gevaarlijke hartritmestoornissen geven.</p>","image_url":"","wiki_title":"Potassium in biology","match":"kalium|k+|kaliumion","option_only":true},"ijzer":{"title":"IJzer","short":"IJzer is nodig voor hemoglobine, myoglobine en enzymen; het lichaam regelt de ijzervoorraad vooral via de opname in de darm.","definition":"<p><strong>IJzer</strong> wordt vooral in het duodenum opgenomen, als heemijzer of als Fe²⁺. In het bloed wordt het vervoerd door transferrine en opgeslagen als ferritine. Het hormoon hepcidine uit de lever remt de opname en afgifte. Het lichaam heeft geen actieve uitscheidingsroute, dus verlies gaat vooral via bloedverlies.</p>","image_url":"","wiki_title":"Iron in biology","match":"ijzer|fe|ijzersuppletie","option_only":true},"albumine":{"title":"Albumine","short":"Albumine is het meest voorkomende plasma-eiwit; het houdt vocht in de bloedbaan (colloïd-osmotische druk) en vervoert veel stoffen.","definition":"<p><strong>Albumine</strong> wordt in de lever gemaakt. Het zorgt voor het grootste deel van de colloïd-osmotische druk en bindt o.a. calcium, bilirubine, vrije vetzuren, hormonen en geneesmiddelen. Een laag albumine komt voor bij leverziekte, nefrotisch syndroom, ondervoeding en ontsteking (negatief acutefase-eiwit) en kan oedeem geven.</p>","image_url":"","wiki_title":"Human serum albumin","match":"albumine|serumalbumine","option_only":true},"creatinine":{"title":"Creatinine","short":"Creatinine is een afbraakproduct van creatinefosfaat uit spieren; de bloedwaarde wordt gebruikt om de nierfunctie te schatten.","definition":"<p><strong>Creatinine</strong> ontstaat in een vrij constant tempo uit creatine in spieren en wordt vooral door glomerulaire filtratie uitgescheiden. Daarom stijgt de serumwaarde als de nierfunctie (GFR) daalt; op basis van creatinine, leeftijd en geslacht wordt de eGFR berekend. Spiermassa beïnvloedt de waarde: bij weinig spiermassa kan een normaal creatinine een verminderde nierfunctie maskeren.</p>","image_url":"","wiki_title":"Creatinine","match":"creatinine|kreatinine|serumcreatinine","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"cerebellum":{"title":"Cerebellum (kleine hersenen)","short":"Het cerebellum coördineert beweging, evenwicht en houding en speelt een rol bij motorisch leren.","definition":"<p>Het <strong>cerebellum</strong> ligt in de achterste schedelgroeve achter de hersenstam, verbonden via drie paar pedunculi. Het vergelijkt bedoelde met uitgevoerde bewegingen en stuurt bij. Uitval geeft ataxie, intentietremor, dysmetrie, dysdiadochokinese, nystagmus en dysartrie aan dezelfde kant als de laesie.</p>","image_url":"","wiki_title":"Cerebellum","match":"cerebellum|kleine hersenen","option_only":true},"synaptogenese":{"title":"Synaptogenese","short":"Synaptogenese is de vorming van nieuwe synapsen tussen neuronen; het piekt in de eerste levensjaren.","definition":"<p>Bij <strong>synaptogenese</strong> maken axonen en dendrieten contact en ontstaan functionele synapsen. Na de geboorte vindt een explosieve toename van synapsen plaats; daarna worden weinig gebruikte synapsen weer opgeruimd (pruning), een proces dat in de prefrontale cortex tot in de adolescentie doorgaat.</p>","image_url":"","wiki_title":"Synaptogenesis","match":"synaptogenese|synapsvorming","option_only":true},"autismespectrumstoornis":{"title":"Autismespectrumstoornis","short":"Autismespectrumstoornis is een neurologische ontwikkelingsstoornis met beperkingen in sociale communicatie en beperkte, repetitieve gedragspatronen en interesses.","definition":"<p>Bij een <strong>autismespectrumstoornis</strong> zijn er vanaf de vroege ontwikkeling problemen met sociaal-emotionele wederkerigheid, non-verbale communicatie en het aangaan van relaties, gecombineerd met stereotiep gedrag, star vasthouden aan routines, beperkte interesses en afwijkende reacties op zintuiglijke prikkels. Het verloop en de ernst variëren sterk; er is een grote erfelijke component.</p>","image_url":"","wiki_title":"Autism spectrum","match":"autismespectrumstoornis|autisme|ass","option_only":true},"adhd":{"title":"ADHD","short":"ADHD is een ontwikkelingsstoornis met aandachtsproblemen en/of hyperactiviteit en impulsiviteit die in meerdere situaties optreden.","definition":"<p>Bij <strong>ADHD</strong> beginnen de klachten vóór het twaalfde jaar en zijn ze aanwezig in meerdere omgevingen (thuis, school). Er is een overwegend onoplettend, een overwegend hyperactief-impulsief en een gecombineerd beeld. Er is een sterke erfelijke component. Behandeling bestaat uit psycho-educatie, gedragsmatige interventies en zo nodig medicatie zoals methylfenidaat.</p>","image_url":"","wiki_title":"Attention deficit hyperactivity disorder","match":"adhd|aandachtstekortstoornis","option_only":true},"epileptische aanval":{"title":"Epileptische aanval","short":"Een epileptische aanval is een kortdurende verandering in gedrag, bewustzijn of waarneming door een abnormale, overmatige ontlading van neuronen.","definition":"<p>Een <strong>epileptische aanval</strong> kan focaal beginnen (in één hersengebied, met of zonder bewustzijnsdaling) of gegeneraliseerd zijn (bijv. tonisch-klonisch of absence). Een aanval kan uitgelokt worden (bijv. door hypoglykemie, alcoholonthouding of koorts bij jonge kinderen) of passen bij epilepsie. Een aanval die langer dan 5 minuten duurt wordt behandeld als status epilepticus.</p>","image_url":"","wiki_title":"Epileptic seizure","match":"epileptische aanval|insult|epileptisch insult","option_only":true},"streptococcus pyogenes":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"streptococcus pyogenes|s. pyogenes|groep a-streptokok|groep a streptokok|groep-a-streptokokken","option_only":true},"enterokokken":{"title":"Enterokokken","short":"Enterokokken zijn grampositieve kokken uit de darmflora die van nature resistent zijn tegen cefalosporines.","definition":"<p><strong>Enterokokken</strong> (vooral <em>E. faecalis</em> en <em>E. faecium</em>) zijn grampositieve kokken in paren of korte ketens. Ze veroorzaken urineweginfecties, wondinfecties, intra-abdominale infecties en endocarditis, vaak in het ziekenhuis. Ze zijn intrinsiek ongevoelig voor cefalosporines; amoxicilline werkt meestal tegen <em>E. faecalis</em>. Vancomycineresistente stammen (VRE) zijn een ziekenhuishygiëneprobleem.</p>","image_url":"","wiki_title":"Enterococcus","match":"enterokokken|enterococcus|enterococcus faecalis|enterococcus faecium","option_only":true},"neisseria meningitidis":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"neisseria meningitidis|meningokok|meningokokken","option_only":true},"listeria monocytogenes":{"title":"Listeria monocytogenes","short":"Listeria is een grampositieve staaf die via voedsel wordt opgelopen en vooral bij zwangeren, pasgeborenen, ouderen en afweergestoorden infecties geeft.","definition":"<p><strong><em>Listeria monocytogenes</em></strong> kan groeien bij koelkasttemperatuur en komt voor in rauwmelkse kaas, paté en gerookte vis. Hij groeit intracellulair en verspreidt zich van cel tot cel via actinestaarten. Infecties: meningitis en sepsis, en bij zwangeren risico op miskraam of neonatale infectie. Cefalosporines werken niet; amoxicilline wel.</p>","image_url":"","wiki_title":"Listeria monocytogenes","match":"listeria monocytogenes|listeria","option_only":true},"mycoplasma pneumoniae":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasma pneumoniae|mycoplasma","option_only":true},"chlamydia pneumoniae":{"title":"Chlamydia pneumoniae","short":"Chlamydia pneumoniae is een obligaat intracellulaire bacterie die milde luchtweginfecties en atypische pneumonie veroorzaakt.","definition":"<p><strong><em>Chlamydia pneumoniae</em></strong> wordt via druppels overgedragen en veroorzaakt faryngitis, sinusitis, bronchitis en een meestal milde atypische pneumonie. Omdat de bacterie intracellulair leeft, werken bètalactamantibiotica niet; doxycycline of macroliden wel.</p>","image_url":"","wiki_title":"Chlamydia pneumoniae","match":"chlamydia pneumoniae|chlamydophila pneumoniae","option_only":true},"salmonella enteritidis":{"title":"Salmonella enteritidis","short":"Salmonella enteritidis is een gramnegatieve staaf die via besmette eieren en kip een voedselinfectie met diarree en koorts veroorzaakt.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> zoals <em>S. enteritidis</em> komen via onvoldoende verhitte eieren, kip of besmet voedsel binnen. Na 6–72 uur ontstaan koorts, buikkrampen en diarree, meestal zelflimiterend. Bij zuigelingen, ouderen, afweergestoorden en mensen met vaatprothesen kan bacteriëmie optreden. Antibiotica zijn meestal niet nodig.</p>","image_url":"","wiki_title":"Salmonella enterica","match":"salmonella enteritidis|salmonella|salmonellose","option_only":true},"campylobacter jejuni":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter jejuni|campylobacter","option_only":true},"lactobacillus spp":{"title":"Lactobacillus","short":"Lactobacillen zijn grampositieve staafjes die melkzuur maken; ze domineren de gezonde vaginale flora en komen voor in darm en gefermenteerd voedsel.","definition":"<p><strong>Lactobacillen</strong> fermenteren suikers tot melkzuur. In de vagina houden ze (onder invloed van oestrogeen en glycogeen) de pH laag, wat beschermt tegen ziekteverwekkers; afname ervan leidt tot bacteriële vaginose. Ze worden ook gebruikt in yoghurt en probiotica en zijn zelden ziekteverwekkend.</p>","image_url":"","wiki_title":"Lactobacillus","match":"lactobacillus spp|lactobacillus|lactobacillen|melkzuurbacteriën","option_only":true},"syfilis":{"title":"Syfilis (lues)","short":"Syfilis is een seksueel overdraagbare infectie door Treponema pallidum, die in stadia verloopt.","definition":"<p><strong>Syfilis</strong> begint (primair) met een pijnloos ulcus (sjanker) op de plek van besmetting. Weken later volgt het secundaire stadium met huiduitslag (ook op handpalmen en voetzolen), condylomata lata en algemene klachten. Na een latente fase kan na jaren tertiaire syfilis ontstaan (gummata, cardiovasculaire en neurosyfilis). Congenitale syfilis wordt voorkomen door screening in de zwangerschap.</p>","image_url":"","wiki_title":"Syphilis","match":"syfilis|lues|syphilis","option_only":true},"aspergillus fumigatus":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus fumigatus|aspergillus|aspergillose","option_only":true},"epstein-barrvirus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"epstein-barrvirus|epstein-barrvirus (ebv)|ebv|epstein-barr virus","option_only":true},"varicella-zostervirus":{"title":"Varicella-zostervirus (VZV)","short":"Het varicella-zostervirus veroorzaakt waterpokken en blijft daarna latent in sensibele ganglia, van waaruit het als gordelroos kan reactiveren.","definition":"<p>Het <strong>varicella-zostervirus</strong> (HHV-3) is zeer besmettelijk via aerosolen en blaasjesvocht. De primaire infectie, <em>waterpokken</em>, geeft koorts en jeukende blaasjes in verschillende stadia tegelijk. Het virus nestelt zich in sensibele ganglia; reactivatie geeft <em>herpes zoster</em>. Gevaarlijk is infectie bij zwangeren, pasgeborenen en afweergestoorden (pneumonie, encefalitis).</p>","image_url":"","wiki_title":"Varicella zoster virus","match":"varicella-zostervirus|varicella zoster|varicella zostervirus (vzv)|vzv|waterpokken|varicella","option_only":true},"herpes simplexvirus":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirus|herpes simplex|hsv|hsv-1|hsv-2","option_only":true},"herpes genitalis":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes genitalis|genitale herpes","option_only":true},"humaan papillomavirus (hpv)":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus (hpv)|hpv|humaan papillomavirus","option_only":true},"rotavirus":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirus","option_only":true},"rhinovirus":{"title":"Rhinovirus","short":"Rhinovirussen zijn de belangrijkste verwekkers van de gewone verkoudheid.","definition":"<p><strong>Rhinovirussen</strong> zijn kleine, niet-omhulde RNA-virussen (picornavirussen) met meer dan 100 serotypes, waardoor je er steeds opnieuw verkouden van kunt worden. Ze vermenigvuldigen zich het best bij de iets lagere temperatuur in de neus. Ze kunnen ook astma- en COPD-exacerbaties uitlokken.</p>","image_url":"","wiki_title":"Rhinovirus","match":"rhinovirus|rhinovirussen","option_only":true},"enterovirus":{"title":"Enterovirussen","short":"Enterovirussen zijn niet-omhulde RNA-virussen die via de darm binnenkomen en o.a. hand-voet-mondziekte, virale meningitis en polio kunnen veroorzaken.","definition":"<p>Tot de <strong>enterovirussen</strong> horen o.a. poliovirus, coxsackievirussen, echovirussen en enterovirus D68 en A71. Ze worden fecaal-oraal en via druppels overgedragen, met een piek in zomer en najaar. Infecties zijn vaak mild, maar kunnen meningitis, myocarditis, hand-voet-mondziekte en (zelden) verlammingen geven.</p>","image_url":"","wiki_title":"Enterovirus","match":"enterovirus|enterovirussen","option_only":true},"virale meningitis":{"title":"Virale meningitis","short":"Virale meningitis is een ontsteking van de hersenvliezen door een virus; meestal milder dan bacteriële meningitis.","definition":"<p><strong>Virale meningitis</strong> wordt vaak veroorzaakt door enterovirussen, daarnaast o.a. door HSV-2 en VZV. Er zijn hoofdpijn, koorts, nekstijfheid en lichtschuwheid, meestal zonder verlaagd bewustzijn. Liquor toont een lymfocytaire pleiocytose met normaal glucose en licht verhoogd eiwit. Het beloop is meestal goedaardig.</p>","image_url":"","wiki_title":"Viral meningitis","match":"virale meningitis|aseptische meningitis","option_only":true},"toxoplasmose":{"title":"Toxoplasmose","short":"Toxoplasmose is een infectie met de parasiet Toxoplasma gondii, opgelopen via kattenpoep of onvoldoende verhit vlees.","definition":"<p><strong><em>Toxoplasma gondii</em></strong> heeft de kat als eindgastheer. Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleose-achtig beeld. Bij een eerste infectie in de zwangerschap kan de parasiet de foetus infecteren (chorioretinitis, hydrocephalus, intracraniële verkalkingen). Bij afweergestoorden kan reactivatie toxoplasma-encefalitis geven.</p>","image_url":"","wiki_title":"Toxoplasmosis","match":"toxoplasmose|toxoplasma gondii|toxoplasma","option_only":true},"giardiasis":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardiasis|giardia lamblia|giardia","option_only":true},"dengue":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"dengue|knokkelkoorts|denguevirus","option_only":true},"ebola":{"title":"Ebola","short":"Ebola is een zeer ernstige virale hemorragische koorts, overgedragen via lichaamsvloeistoffen van besmette mensen of dieren.","definition":"<p>Het <strong>ebolavirus</strong> is een filovirus. Na 2–21 dagen ontstaan koorts, zwakte, spierpijn, braken en diarree; in een deel van de gevallen volgen bloedingen en multi-orgaanfalen. De sterfte is hoog. Overdracht gebeurt via direct contact met bloed en lichaamsvloeistoffen, ook van overledenen; strikte isolatie is nodig. Er is inmiddels een vaccin tegen het Zaïre-type.</p>","image_url":"","wiki_title":"Ebola","match":"ebola|ebolavirus|ebolakoorts","option_only":true},"pediculosis":{"title":"Pediculosis (luizen)","short":"Pediculosis is besmetting met luizen, zoals hoofdluis, met jeuk en neten aan de haren.","definition":"<p>Bij <strong>pediculosis capitis</strong> leven hoofdluizen op de hoofdhuid en zuigen ze bloed; de eitjes (neten) worden vlak bij de hoofdhuid aan de haren vastgeplakt. De jeuk komt door een overgevoeligheidsreactie op het speeksel. Overdracht gaat via direct hoofd-hoofdcontact. Behandeling: kammen met een netenkam, eventueel met dimeticon. Kleerluizen kunnen ziekten zoals vlektyfus overbrengen.</p>","image_url":"","wiki_title":"Head louse","match":"pediculosis|hoofdluis|luizen|pediculosis capitis","option_only":true},"lipopolysaccharide":{"title":"Lipopolysaccharide (LPS, endotoxine)","short":"Lipopolysaccharide is een bestanddeel van de buitenmembraan van gramnegatieve bacteriën dat als endotoxine een sterke ontstekingsreactie uitlokt.","definition":"<p><strong>LPS</strong> bestaat uit lipide A (het toxische deel, verankerd in de buitenmembraan), een kernpolysacharide en een O-antigeen. Het wordt herkend door TLR4 op macrofagen, die daarop massaal TNF, IL-1 en IL-6 afgeven. In grote hoeveelheden kan dat leiden tot koorts, verwijde vaten, stollingsactivatie (DIS) en septische shock.</p>","image_url":"","wiki_title":"Lipopolysaccharide","match":"lipopolysaccharide|lps|endotoxine","option_only":true},"peptidoglycaanlaag":{"title":"Peptidoglycaan","short":"Peptidoglycaan is het netwerk van suikers en peptiden dat de bacteriële celwand stevigheid geeft.","definition":"<p><strong>Peptidoglycaan</strong> bestaat uit ketens van afwisselend N-acetylglucosamine en N-acetylmuraminezuur, onderling verbonden via korte peptidebruggen. Grampositieve bacteriën hebben een dikke laag (houdt het kristalviolet vast), gramnegatieve een dunne laag tussen twee membranen. Bètalactamantibiotica remmen de verknoping, vancomycine de opbouw en lysozym breekt het af.</p>","image_url":"","wiki_title":"Peptidoglycan","match":"peptidoglycaanlaag|peptidoglycaan|mureïne","option_only":true},"antibiotica":{"title":"Antibiotica","short":"Antibiotica zijn middelen die bacteriën doden of hun groei remmen; ze werken niet tegen virussen.","definition":"<p><strong>Antibiotica</strong> grijpen aan op structuren die bacteriën wel en menselijke cellen niet (of anders) hebben: de celwand (bètalactams, vancomycine), het ribosoom (o.a. macroliden, tetracyclines, aminoglycosiden), DNA-synthese (chinolonen, metronidazol) of foliumzuursynthese (trimethoprim, sulfonamiden). Bacteriostatisch betekent groeiremmend, bactericide dodend. Onnodig gebruik bevordert resistentie.</p>","image_url":"","wiki_title":"Antibiotic","match":"antibiotica|antibioticum","option_only":true},"ciprofloxacine":{"title":"Ciprofloxacine","short":"Ciprofloxacine is een fluorochinolon dat het bacteriële DNA-gyrase remt; werkzaam tegen veel gramnegatieve bacteriën.","definition":"<p><strong>Ciprofloxacine</strong> remt DNA-gyrase en topo-isomerase IV, waardoor de bacterie haar DNA niet kan repliceren (bactericide). Het werkt goed tegen gramnegatieve staven, inclusief <em>Pseudomonas</em>, en wordt o.a. gebruikt bij gecompliceerde urineweginfecties en prostatitis. Bijwerkingen: peesruptuur, QT-verlenging, verwardheid en <em>C. difficile</em>-infectie.</p>","image_url":"","wiki_title":"Ciprofloxacin","match":"ciprofloxacine|ciprofloxacin|fluorochinolon","option_only":true},"tobramycine":{"title":"Tobramycine","short":"Tobramycine is een aminoglycoside dat de bacteriële eiwitsynthese remt (30S) en goed werkt tegen Pseudomonas.","definition":"<p><strong>Tobramycine</strong> bindt aan de 30S-subeenheid van het ribosoom, wat tot foutieve eiwitten en celdood leidt (bactericide, concentratieafhankelijk). Het werkt tegen gramnegatieve aerobe bacteriën en wordt o.a. per inhalatie gebruikt bij cystische fibrose. Belangrijke bijwerkingen zijn nefrotoxiciteit en ototoxiciteit; spiegels worden gecontroleerd.</p>","image_url":"","wiki_title":"Tobramycin","match":"tobramycine|aminoglycoside","option_only":true},"acute bronchitis":{"title":"Acute bronchitis","short":"Acute bronchitis is een (meestal virale) ontsteking van de grote luchtwegen met hoesten, al dan niet met sputum.","definition":"<p>Bij <strong>acute bronchitis</strong> raakt het slijmvlies van de bronchi ontstoken, vaak na een verkoudheid. De hoest kan enkele weken aanhouden. Er zijn geen tekenen van een pneumonie (zoals lokale crepitaties of hoge koorts met ernstig ziek-zijn). Bij gezonde mensen zijn antibiotica niet nodig, ook niet bij gekleurd sputum.</p>","image_url":"","wiki_title":"Acute bronchitis","match":"acute bronchitis|bronchitis","option_only":true},"sinusitis":{"title":"Sinusitis (bijholteontsteking)","short":"Sinusitis is een ontsteking van het slijmvlies van neus en bijholten, met verstopte neus, pijn in het gezicht en afscheiding.","definition":"<p>Acute <strong>rhinosinusitis</strong> ontstaat meestal na een virale verkoudheid; soms volgt een bacteriële infectie (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Klachten zijn een verstopte neus, (purulente) afscheiding, pijn of drukgevoel boven de bijholten en verminderde reuk. Meestal herstelt het binnen enkele weken zonder antibiotica. Chronische sinusitis duurt langer dan 12 weken.</p>","image_url":"","wiki_title":"Sinusitis","match":"sinusitis|bijholteontsteking|rhinosinusitis","option_only":true},"longembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"longembolie|pulmonale embolie|longembolieën","option_only":true},"ct-thorax":{"title":"CT-thorax","short":"Een CT-thorax is een röntgenscan in dwarsdoorsneden van de borstkas, gedetailleerder dan een X-thorax.","definition":"<p>Een <strong>CT-thorax</strong> geeft een driedimensionaal beeld van longen, mediastinum, pleura en thoraxwand. Met intraveneus contrast (CT-angiografie) is het het standaardonderzoek bij verdenking op longembolie. Een hoge-resolutie-CT (HRCT) is geschikt voor interstitiële longziekten; een lage-dosis-CT wordt gebruikt voor screening en follow-up van longnodules.</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax|ct thorax|ct van de thorax","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"ventrikelfibrilleren":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren|ventrikelfibrillatie|vf","option_only":true},"aortaklepstenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortaklepstenose|aortastenose","option_only":true},"aortaklepinsufficiëntie":{"title":"Aortaklepinsufficiëntie","short":"Bij aortaklepinsufficiëntie sluit de aortaklep niet goed, waardoor bloed in de diastole terugstroomt naar de linkerventrikel.","definition":"<p>Bij <strong>aortaklepinsufficiëntie</strong> ontstaat volumebelasting van de linkerventrikel, die verwijdt. Oorzaken zijn o.a. een bicuspide klep, endocarditis, verwijding van de aortawortel (hypertensie, Marfan, dissectie). Kenmerkend zijn een diastolisch decrescendo-geruis langs de linker sternumrand en een grote polsdruk (snel stijgende en dalende pols).</p>","image_url":"","wiki_title":"Aortic insufficiency","match":"aortaklepinsufficiëntie|aorta-insufficiëntie|aortaklepinsufficientie","option_only":true},"mitralisinsufficiëntie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralisinsufficiëntie|mitralisklepinsufficiëntie|mitralisinsufficientie","option_only":true},"pericarditis":{"title":"Pericarditis","short":"Pericarditis is een ontsteking van het hartzakje, met scherpe, houdingsafhankelijke pijn op de borst.","definition":"<p><strong>Pericarditis</strong> wordt meestal veroorzaakt door een virus, maar ook door bacteriën, auto-immuunziekten, nierfalen, tumoren of na een hartinfarct of hartoperatie. Typisch zijn scherpe pijn die verergert bij plat liggen en diep inademen, een pericardwrijven en diffuse ST-elevatie op het ECG. Bij veel vocht in het hartzakje kan een harttamponnade ontstaan.</p>","image_url":"","wiki_title":"Pericarditis","match":"pericarditis|hartzakontsteking","option_only":true},"glomerulonefritis":{"title":"Glomerulonefritis","short":"Glomerulonefritis is een (meestal immunologische) ontsteking van de glomeruli, met hematurie, proteïnurie, hypertensie en/of nierfunctieverlies.","definition":"<p>Bij een <strong>nefritisch syndroom</strong> zijn er erytrocytencilinders, hematurie, hypertensie, oedeem en een dalende nierfunctie. Oorzaken zijn o.a. IgA-nefropathie, poststreptokokken-glomerulonefritis, ANCA-vasculitis, lupusnefritis en anti-GBM-ziekte. Een snel progressieve vorm met halvemaanvorming kan binnen weken tot nierfalen leiden en vereist snelle diagnostiek met nierbiopt.</p>","image_url":"","wiki_title":"Glomerulonephritis","match":"glomerulonefritis","option_only":true},"dehydratie":{"title":"Dehydratie","short":"Dehydratie is een tekort aan lichaamsvocht, door te weinig inname of te veel verlies (braken, diarree, zweten, polyurie).","definition":"<p>Bij <strong>dehydratie</strong> daalt het circulerend volume, met dorst, droge slijmvliezen, verminderde huidturgor, tachycardie, orthostatische hypotensie en weinig plassen. Kinderen en ouderen zijn extra kwetsbaar. Afhankelijk van verlies van water ten opzichte van zout kan de natriumconcentratie normaal, verhoogd of verlaagd zijn. Behandeling met orale rehydratie of infuus.</p>","image_url":"","wiki_title":"Dehydration","match":"dehydratie|uitdroging|ondervulling","option_only":true},"hypoglycemie":{"title":"Hypoglykemie","short":"Hypoglykemie is een te lage bloedglucose, met klachten zoals trillen, zweten, honger en bij ernstige vormen verwardheid en bewustzijnsverlies.","definition":"<p>Een <strong>hypoglykemie</strong> (meestal &lt;4 mmol/L bij diabetes) komt vooral voor bij gebruik van insuline of sulfonylureumderivaten, bij te weinig eten, inspanning of alcohol. Eerst ontstaan adrenerge klachten (trillen, zweten, hartkloppingen, honger), daarna neuroglycopene klachten (verwardheid, gedragsverandering, insulten, coma). Behandeling: snelle suikers of glucose intraveneus, of glucagon.</p>","image_url":"","wiki_title":"Hypoglycemia","match":"hypoglycemie|hypoglykemie","option_only":true},"polydipsie":{"title":"Polydipsie","short":"Polydipsie is overmatige dorst en vochtinname.","definition":"<p><strong>Polydipsie</strong> gaat vaak samen met polyurie. Oorzaken zijn o.a. diabetes mellitus (osmotische diurese), diabetes insipidus (centraal of nefrogeen), hypercalciëmie, diuretica en primaire (psychogene) polydipsie. Een dorstproef kan helpen deze oorzaken te onderscheiden.</p>","image_url":"","wiki_title":"Polydipsia","match":"polydipsie","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"obstipatie":{"title":"Obstipatie","short":"Obstipatie is een te harde en/of te weinig frequente ontlasting, vaak met moeizaam persen.","definition":"<p>Van <strong>obstipatie</strong> spreekt men bij minder dan drie keer per week ontlasting, harde ontlasting, persen of een gevoel van onvolledige lediging. Oorzaken zijn o.a. weinig vezels en vocht, weinig beweging, medicatie (opioïden, ijzer, anticholinergica, calciumantagonisten), hypothyreoïdie, hypercalciëmie, neurologische ziekten en obstructie door een tumor. Behandeling met leefstijladviezen en laxantia zoals macrogol.</p>","image_url":"","wiki_title":"Constipation","match":"obstipatie|verstopping|constipatie","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"maagperforatie":{"title":"Maagperforatie","short":"Bij een maagperforatie ontstaat een gat in de maagwand, meestal door een ulcus, waardoor maaginhoud in de buikholte lekt.","definition":"<p>Een <strong>perforatie</strong> van maag of duodenum geeft plotselinge, hevige bovenbuikpijn die zich snel over de hele buik uitbreidt, met een plankharde buik (chemische peritonitis). Op een staande X-thorax of CT is vrij lucht onder het diafragma te zien. Risicofactoren zijn NSAID-gebruik, <em>H. pylori</em> en roken. Behandeling is meestal chirurgisch sluiten.</p>","image_url":"","wiki_title":"Gastrointestinal perforation","match":"maagperforatie|perforatie van de maag|ulcusperforatie","option_only":true},"refluxklachten":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxklachten|reflux|gastro-oesofageale reflux|zuurbranden|refluxziekte","option_only":true},"x-boz":{"title":"X-buikoverzicht (X-BOZ)","short":"Een X-buikoverzicht is een röntgenfoto van de buik, vooral gebruikt om darmafsluiting of vrij lucht aan te tonen.","definition":"<p>Een <strong>X-BOZ</strong> toont darmgaspatronen, verwijde darmlissen met vloeistofspiegels (ileus), vrij lucht (perforatie, beter te zien op een staande X-thorax), stenen en vreemde voorwerpen. Door de beperkte informatie is het in veel situaties vervangen door een echo of CT.</p>","image_url":"","wiki_title":"Abdominal x-ray","match":"x-boz|buikoverzichtsfoto|x-buikoverzicht","option_only":true},"leukocyten":{"title":"Leukocyten (witte bloedcellen)","short":"Leukocyten zijn de witte bloedcellen van het afweersysteem: granulocyten, monocyten en lymfocyten.","definition":"<p><strong>Leukocyten</strong> worden in het beenmerg gemaakt (lymfocyten rijpen deels in thymus en lymfoïde organen). Normaal zijn er ongeveer 4–10 × 10⁹/L in het bloed. De differentiatie onderscheidt neutrofielen, lymfocyten, monocyten, eosinofielen en basofielen; de verhouding geeft aanwijzingen voor bijv. bacteriële infectie, virale infectie, allergie of leukemie.</p>","image_url":"","wiki_title":"White blood cell","match":"leukocyten|witte bloedcellen|leukocyt","option_only":true},"leukocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leukocytose","option_only":true},"igg":{"title":"IgG","short":"IgG is de meest voorkomende antistofklasse in het bloed; het is belangrijk bij de secundaire immuunrespons en passeert de placenta.","definition":"<p><strong>IgG</strong> is een monomeer en heeft vier subklassen. Het werkt via neutralisatie, opsonisatie (via Fcγ-receptoren op fagocyten) en complementactivatie. Het is de belangrijkste antistof bij een herhaalde blootstelling en de enige klasse die actief via de placenta naar de foetus gaat, wat pasgeborenen maandenlang beschermt.</p>","image_url":"","wiki_title":"Immunoglobulin G","match":"igg|immunoglobuline g","option_only":true},"ifn-α":{"title":"Interferon-alfa","short":"Interferon-alfa is een type I-interferon dat door geïnfecteerde cellen wordt gemaakt en naburige cellen in een antivirale toestand brengt.","definition":"<p><strong>Type I-interferonen</strong> (IFN-α en IFN-β) worden vooral door plasmacytoïde dendritische cellen en geïnfecteerde cellen afgegeven. Ze remmen virale replicatie in omliggende cellen, verhogen de MHC-I-expressie en activeren NK-cellen. Als geneesmiddel werd interferon-alfa gebruikt bij chronische hepatitis B en C en sommige maligniteiten; bijwerkingen zijn griepachtige klachten en depressie.</p>","image_url":"","wiki_title":"Interferon type I","match":"ifn-α|ifn-alfa|interferon-alfa|interferon alfa|type i interferon","option_only":true},"artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"artritis|arthritis|gewrichtsontsteking","option_only":true},"ziekte van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"ziekte van kawasaki|kawasaki|mucocutaan lymfekliersyndroom","option_only":true},"conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"conjunctivitis|bindvliesontsteking","option_only":true},"speekselvloed":{"title":"Speekselvloed (sialorroe)","short":"Speekselvloed is overmatig speeksel in de mond of kwijlen, door teveel productie of slecht slikken.","definition":"<p><strong>Sialorroe</strong> kan ontstaan door verhoogde productie (bijv. door clozapine, cholinerge middelen, misselijkheid, tandproblemen) of, vaker, door verminderd slikken of slechte mondsluiting, zoals bij de ziekte van Parkinson, ALS, een beroerte of cerebrale parese.</p>","image_url":"","wiki_title":"Drooling","match":"speekselvloed|sialorroe|hypersalivatie|kwijlen","option_only":true},"oxazepam":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"oxazepam|benzodiazepine|benzodiazepinen","option_only":true},"cocaïne":{"title":"Cocaïne","short":"Cocaïne is een stimulerende drug die de heropname van dopamine, noradrenaline en serotonine remt en ook lokaal verdovend werkt.","definition":"<p><strong>Cocaïne</strong> geeft euforie, energie en een sterk verslavend effect. Door sympathische activatie ontstaan tachycardie, hypertensie, vasoconstrictie en hyperthermie. Complicaties zijn myocardinfarct (ook bij jonge mensen), aritmieën, herseninfarct en -bloeding, en bij snuiven een perforatie van het neustussenschot. Lokaal werkt het als natriumkanaalblokker (anestheticum).</p>","image_url":"","wiki_title":"Cocaine","match":"cocaïne|cocaine","option_only":true},"hyaluronzuur":{"title":"Hyaluronzuur","short":"Hyaluronzuur is een groot, niet-gesulfateerd glycosaminoglycaan dat veel water bindt en de grondsubstantie en gewrichtsvloeistof stroperig maakt.","definition":"<p><strong>Hyaluronzuur</strong> is anders dan de andere glycosaminoglycanen niet aan een eiwitkern gebonden en wordt aan het celmembraan gemaakt. Het vormt de ruggengraat waaraan proteoglycanen (zoals aggrecan in kraakbeen) binden. Het komt veel voor in synoviaal vocht, glasvocht, huid en losmazig bindweefsel.</p>","image_url":"","wiki_title":"Hyaluronic acid","match":"hyaluronzuur|hyaluronan","option_only":true},"mutatie":{"title":"Mutatie","short":"Een mutatie is een blijvende verandering in de DNA-volgorde.","definition":"<p>Een <strong>mutatie</strong> kan één nucleotide betreffen (puntmutatie: silent, missense of nonsense), een kleine insertie of deletie (soms met frameshift), of grote stukken DNA en chromosomen. Mutaties in kiemcellen kunnen worden doorgegeven aan nakomelingen; somatische mutaties niet, maar die liggen wel ten grondslag aan kanker. Tegenwoordig spreekt men liever neutraal van een ‘variant’.</p>","image_url":"","wiki_title":"Mutation","match":"mutatie|mutaties|genmutatie","option_only":true},"syndroom van turner":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"syndroom van turner|turnersyndroom|45,x","option_only":true},"syndroom van marfan":{"title":"Syndroom van Marfan","short":"Het syndroom van Marfan is een autosomaal dominante bindweefselziekte door mutaties in het fibrilline-1-gen.","definition":"<p>Bij het <strong>syndroom van Marfan</strong> zijn de microfibrillen van elastische vezels afwijkend en is TGF-β-signalering verhoogd. Kenmerken: lange, slanke gestalte met lange ledematen en vingers, hypermobiele gewrichten, borstkasafwijkingen, lensluxatie (meestal naar boven) en verwijding van de aortawortel met risico op dissectie. Behandeling o.a. met bètablokkers of ARB's en tijdige aortachirurgie.</p>","image_url":"","wiki_title":"Marfan syndrome","match":"syndroom van marfan|marfansyndroom|marfan syndroom","option_only":true},"achondroplasie":{"title":"Achondroplasie","short":"Achondroplasie is de meest voorkomende vorm van disproportionele dwerggroei, door een activerende mutatie in FGFR3.","definition":"<p>Bij <strong>achondroplasie</strong> remt het overactieve FGFR3 de enchondrale verbening in de groeischijven. Kenmerken: korte ledematen (vooral bovenarmen en bovenbenen), een relatief normale romp, een groot hoofd met een prominent voorhoofd en een normale intelligentie. Het erft autosomaal dominant over, maar ontstaat meestal de novo (vaak bij oudere vaders).</p>","image_url":"","wiki_title":"Achondroplasia","match":"achondroplasie","option_only":true},"agenesie van beide nieren":{"title":"Bilaterale nieragenesie","short":"Bij bilaterale nieragenesie zijn beide nieren niet aangelegd, met ernstig tekort aan vruchtwater en longhypoplasie als gevolg.","definition":"<p>Bij <strong>bilaterale nieragenesie</strong> ontstaan de nieren niet, doordat de ureterknop niet of verkeerd met het metanefrogene mesoderm in contact komt. Er wordt geen foetale urine gemaakt, met oligo- of anhydramnion. Dat leidt tot de Potter-sequentie: longhypoplasie, een afgeplat gezicht en standsafwijkingen van de ledematen; het is niet met het leven verenigbaar.</p>","image_url":"","wiki_title":"Renal agenesis","match":"agenesie van beide nieren|bilaterale nieragenesie|nieragenesie","option_only":true},"hernia inguinalis":{"title":"Liesbreuk (hernia inguinalis)","short":"Een liesbreuk is een uitstulping van buikvlies (met eventueel darm) via het lieskanaal of de achterwand ervan.","definition":"<p>Een <strong>indirecte</strong> liesbreuk volgt het lieskanaal vanaf de inwendige liesring, lateraal van de vasa epigastrica inferiora (vaak door een open processus vaginalis). Een <strong>directe</strong> liesbreuk puilt mediaal van deze vaten uit door een zwakke achterwand. Liesbreuken komen vooral bij mannen voor; beklemming is een spoedgeval.</p>","image_url":"","wiki_title":"Inguinal hernia","match":"hernia inguinalis|liesbreuk","option_only":true},"polycysteus ovariumsyndroom":{"title":"Polycysteus ovariumsyndroom (PCOS)","short":"PCOS is een hormonale stoornis met onregelmatige of uitblijvende ovulatie, verhoogde androgenen en/of veel kleine follikels in de ovaria.","definition":"<p>Volgens de Rotterdam-criteria spreekt men van <strong>PCOS</strong> bij twee van drie kenmerken: oligo- of anovulatie, klinische of biochemische hyperandrogenisme (acne, hirsutisme) en polycysteuze ovaria op de echo. Het gaat vaak samen met insulineresistentie en overgewicht. Het is een veelvoorkomende oorzaak van subfertiliteit.</p>","image_url":"","wiki_title":"Polycystic ovary syndrome","match":"polycysteus ovariumsyndroom|pcos|polycysteus ovarium syndroom","option_only":true},"mammacarcinoom":{"title":"Mammacarcinoom (borstkanker)","short":"Het mammacarcinoom is een kwaadaardige tumor van de borstklier, de meest voorkomende kanker bij vrouwen.","definition":"<p>Het <strong>mammacarcinoom</strong> is meestal een invasief carcinoom uitgaande van de afvoergangen (ductaal) of lobjes (lobulair). Risicofactoren zijn leeftijd, familiaire belasting (BRCA1/2), lange oestrogeenblootstelling en alcohol. Behandeling hangt af van stadium en receptorstatus (oestrogeen, progesteron, HER2): chirurgie, radiotherapie, hormonale therapie, chemotherapie en doelgerichte therapie. Er is een bevolkingsonderzoek met mammografie.</p>","image_url":"","wiki_title":"Breast cancer","match":"mammacarcinoom|borstkanker","option_only":true},"hypotonie":{"title":"Hypotonie (spierslapte)","short":"Hypotonie is een verlaagde spierspanning; bij zuigelingen spreekt men van een ‘floppy infant’.","definition":"<p>Bij <strong>hypotonie</strong> is de weerstand bij passief bewegen verlaagd. Bij pasgeborenen kan de oorzaak centraal liggen (bijv. hersenschade, syndroom van Down, Prader-Willi) of perifeer (bijv. spinale musculaire atrofie, myopathieën). Centrale oorzaken gaan meestal gepaard met relatief behouden kracht, perifere met duidelijke zwakte.</p>","image_url":"","wiki_title":"Hypotonia","match":"hypotonie|spierhypotonie|floppy infant","option_only":true},"hyperreactiviteit":{"title":"Bronchiale hyperreactiviteit","short":"Bronchiale hyperreactiviteit is een overgevoeligheid van de luchtwegen, die al op geringe prikkels vernauwen.","definition":"<p>Bij <strong>bronchiale hyperreactiviteit</strong> reageren de luchtwegen met bronchoconstrictie op prikkels zoals koude lucht, rook, inspanning of mist. Het is een kenmerk van astma, maar kan ook tijdelijk na een virale luchtweginfectie en bij COPD voorkomen. Het kan gemeten worden met een provocatietest (histamine of metacholine).</p>","image_url":"","wiki_title":"Bronchial hyperresponsiveness","match":"hyperreactiviteit|bronchiale hyperreactiviteit|hyperreactieve luchtwegen","option_only":true},"anorexia nervosa":{"title":"Anorexia nervosa","short":"Anorexia nervosa is een eetstoornis met een te laag lichaamsgewicht door het beperken van voeding, angst om aan te komen en een verstoord lichaamsbeeld.","definition":"<p>Bij <strong>anorexia nervosa</strong> houdt iemand het gewicht bewust laag, met een intense angst om dik te worden. Lichamelijke gevolgen zijn o.a. amenorroe, bradycardie, hypotensie, hypothermie, lanugobeharing, osteoporose en elektrolytstoornissen (vooral bij braken of laxeren). Het heeft de hoogste sterfte van de psychiatrische stoornissen. Bij het hervatten van voeding dreigt het refeedingsyndroom.</p>","image_url":"","wiki_title":"Anorexia nervosa","match":"anorexia nervosa","option_only":true},"trombosebeen":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"trombosebeen|diepveneuze trombose|dvt|been-trombose","option_only":true},"sikkelcelziekte":{"title":"Sikkelcelziekte","short":"Sikkelcelziekte is een erfelijke hemoglobinopathie waarbij afwijkend hemoglobine (HbS) bij zuurstoftekort polymeriseert en rode bloedcellen sikkelvormig maakt.","definition":"<p>Bij <strong>sikkelcelziekte</strong> (homozygoot HbS, autosomaal recessief) verstoppen sikkelcellen kleine vaatjes en worden ze snel afgebroken. Gevolgen: pijncrises, hemolytische anemie, acute chest syndrome, herseninfarcten, miltinfarcten (functionele asplenie, infecties met gekapselde bacteriën) en priapisme. Dragerschap beschermt deels tegen malaria. Behandeling o.a. met hydroxycarbamide en transfusies.</p>","image_url":"","wiki_title":"Sickle cell disease","match":"sikkelcelziekte|sikkelcelanemie","option_only":true},"tachycardie":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie|sinustachycardie","option_only":true},"atriumseptum defect":{"title":"Atriumseptumdefect (ASD)","short":"Een ASD is een aangeboren opening in het septum tussen de boezems, met een links-rechtsshunt.","definition":"<p>Bij een <strong>atriumseptumdefect</strong> (meestal type secundum) stroomt bloed van het linker- naar het rechteratrium, met volumebelasting van het rechterhart en de longcirculatie. Het geeft vaak pas op volwassen leeftijd klachten (vermoeidheid, kortademigheid, boezemfibrilleren). Kenmerkend is een vaste splijting van de tweede harttoon. Sluiting kan meestal via een katheter.</p>","image_url":"","wiki_title":"Atrial septal defect","match":"atriumseptum defect|atriumseptumdefect|asd","option_only":true},"myocarditis":{"title":"Myocarditis","short":"Myocarditis is een ontsteking van de hartspier, meestal door een virus, met pijn op de borst, ritmestoornissen of hartfalen.","definition":"<p><strong>Myocarditis</strong> wordt vaak veroorzaakt door virussen (o.a. enterovirussen, parvovirus B19, SARS-CoV-2), maar ook door auto-immuunziekten, medicatie of vaccins. Klachten variëren van milde pijn op de borst met troponinestijging tot acuut hartfalen en plotse dood. Diagnose met cardiale MRI. Sporten wordt na myocarditis maanden afgeraden.</p>","image_url":"","wiki_title":"Myocarditis","match":"myocarditis|hartspierontsteking","option_only":true},"hypothermie":{"title":"Hypothermie","short":"Hypothermie is een te lage lichaamstemperatuur, onder 35 °C.","definition":"<p>Bij <strong>hypothermie</strong> vertragen stofwisseling, hartritme en ademhaling. Eerst ontstaan rillen en verwardheid; bij verdere daling verdwijnt het rillen, met bradycardie, ritmestoornissen (Osborn-golven op het ECG) en bewustzijnsdaling. Pasgeborenen, ouderen en mensen onder invloed van alcohol zijn kwetsbaar. Therapeutische hypothermie wordt gebruikt na reanimatie en bij perinatale asfyxie.</p>","image_url":"","wiki_title":"Hypothermia","match":"hypothermie|onderkoeling","option_only":true},"testiscarcinoom":{"title":"Testiscarcinoom","short":"Testiscarcinoom is een kwaadaardige kiemceltumor van de zaadbal, vooral bij jonge mannen.","definition":"<p><strong>Testistumoren</strong> zijn meestal kiemceltumoren: seminomen en non-seminomen. Ze presenteren zich als een pijnloze, harde zwelling van de testis. Een niet-ingedaalde testis is een belangrijke risicofactor. Tumormarkers zijn AFP, β-hCG en LDH. De behandeling start met een orchidectomie via de lies; de genezingskans is zeer hoog, ook bij uitzaaiingen.</p>","image_url":"","wiki_title":"Testicular cancer","match":"testiscarcinoom|zaadbalkanker|testistumor","option_only":true},"stereotypie":{"title":"Stereotypie","short":"Een stereotypie is een herhaalde, doelloze beweging of handeling, zoals wiegen of handfladderen.","definition":"<p><strong>Stereotypieën</strong> zijn ritmisch en patroonmatig en worden niet als ongewenst ervaren, anders dan tics. Ze komen voor bij autismespectrumstoornis, verstandelijke beperking, ernstige sensorische deprivatie, katatonie en als bijwerking (bijv. van stimulantia).</p>","image_url":"","wiki_title":"Stereotypy","match":"stereotypie|stereotypieën|stereotiep gedrag","option_only":true},"meningokokkenmeningitis":{"title":"Meningokokkenmeningitis","short":"Meningokokkenmeningitis is een hersenvliesontsteking door Neisseria meningitidis, vaak met een snel verlopende sepsis en petechiën.","definition":"<p>Bij een <strong>invasieve meningokokkeninfectie</strong> kunnen binnen uren koorts, hoofdpijn, nekstijfheid, sufheid en niet-wegdrukbare petechiën ontstaan, soms met shock en diffuse intravasale stolling. Bij verdenking (zeker met petechiën) wordt zo snel mogelijk een antibioticum gegeven. Nauwe contacten krijgen profylaxe; er is vaccinatie tegen serogroepen ACWY en B.</p>","image_url":"","wiki_title":"Meningococcal disease","match":"meningokokkenmeningitis|meningokokkensepsis","option_only":true},"tonsillitis":{"title":"Tonsillitis","short":"Tonsillitis is een ontsteking van de keelamandelen, meestal viraal, soms door groep A-streptokokken.","definition":"<p>Bij <strong>tonsillitis</strong> zijn de amandelen rood en gezwollen, soms met beslag, en zijn er keelpijn, slikklachten en koorts. Meestal gaat het om een virus (ook EBV). Bij een bacteriële oorzaak gaat het vaak om groep A-streptokokken. Complicaties zijn een peritonsillair abces (met trismus en uitpuilen van het gehemelte) en zelden acuut reuma.</p>","image_url":"","wiki_title":"Tonsillitis","match":"tonsillitis|amandelontsteking|angina tonsillaris","option_only":true},"trichomonas":{"title":"Trichomonas vaginalis","short":"Trichomonas vaginalis is een seksueel overdraagbare protozo die vaginitis met schuimende, groengele afscheiding veroorzaakt.","definition":"<p><strong>Trichomoniasis</strong> geeft bij vrouwen jeuk, branderigheid en riekende, schuimende afscheiding, soms met een ‘aardbeiencervix’; bij mannen meestal geen klachten. De beweeglijke flagellaten zijn soms te zien in een nat preparaat; PCR is gevoeliger. Behandeling met metronidazol, ook voor de partner.</p>","image_url":"","wiki_title":"Trichomoniasis","match":"trichomonas|trichomonas vaginalis|trichomoniasis","option_only":true},"ascariasis":{"title":"Ascariasis (spoelworm)","short":"Ascariasis is een infectie met de grote spoelworm Ascaris lumbricoides, opgelopen via eitjes in besmet voedsel of grond.","definition":"<p>Bij <strong>ascariasis</strong> komen larven uit de darm via bloed en longen (soms met hoest en eosinofilie: syndroom van Löffler) terug in de darm, waar ze uitgroeien tot wormen van 15–35 cm. Lichte infecties geven weinig klachten; zware infecties kunnen darmobstructie, galwegobstructie en ondervoeding geven. Behandeling met mebendazol of albendazol.</p>","image_url":"","wiki_title":"Ascariasis","match":"ascariasis|ascaris lumbricoides|spoelworm","option_only":true},"amoebiasis":{"title":"Amoebiasis","short":"Amoebiasis is een infectie met Entamoeba histolytica, die bloederige diarree en leverabcessen kan veroorzaken.","definition":"<p><strong><em>Entamoeba histolytica</em></strong> wordt via cysten in besmet water of voedsel opgelopen. Invasieve infectie van het colon geeft amoebendysenterie met kolfvormige ulcera. Via de v. portae kan een amoebenleverabces ontstaan, met koorts en pijn rechtsboven. Behandeling met metronidazol, gevolgd door een middel dat de cysten in de darm doodt.</p>","image_url":"","wiki_title":"Amoebiasis","match":"amoebiasis|amoebendysenterie|entamoeba histolytica","option_only":true},"miltruptuur":{"title":"Miltruptuur","short":"Bij een miltruptuur scheurt de milt, meestal na een trauma, met een levensbedreigende inwendige bloeding.","definition":"<p>Een <strong>miltruptuur</strong> ontstaat vooral na een stomp buiktrauma links (soms met ribfracturen). Een vergrote milt (bijv. bij de ziekte van Pfeiffer of malaria) kan al bij gering trauma scheuren. Klachten: pijn linksboven, soms uitstralend naar de linkerschouder (teken van Kehr), en tekenen van shock. Behandeling afhankelijk van stabiliteit: observatie, embolisatie of splenectomie.</p>","image_url":"","wiki_title":"Splenic injury","match":"miltruptuur|scheuring van de milt","option_only":true},"leucocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leucocytose","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"valvulaire aortastenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"valvulaire aortastenose","option_only":true},"mycobacterium tuberculosis (tuberculose)":{"title":"Mycobacterium tuberculosis","short":"M. tuberculosis is de zuurvaste, langzaam groeiende staafbacterie die tuberculose veroorzaakt.","definition":"<p><strong><em>Mycobacterium tuberculosis</em></strong> is een aerobe staafbacterie met een wasachtige, mycolzuurrijke celwand. Daardoor kleurt hij niet goed met de gramkleuring maar wel met de Ziehl-Neelsenkleuring (<em>zuurvast</em>).</p><p>Hij wordt aerogeen overgedragen, groeit zeer langzaam (weken in kweek) en overleeft in macrofagen. De afweer is vooral cellulair (T-cellen) en leidt tot granulomen met centrale verkazing. Hij veroorzaakt tuberculose.</p>","image_url":"","wiki_title":"Mycobacterium tuberculosis","match":"mycobacterium tuberculosis (tuberculose)","option_only":true},"bofvirus":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bofvirus","option_only":true},"herpes simplexvirus type 1":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirus type 1","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"t cel":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t cel","option_only":true},"b cel":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b cel","option_only":true},"streptococcus pneumoniae (pneumokok)":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae (pneumokok)","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"haemofilus influenzae type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemofilus influenzae type b","option_only":true},"haemophilus influenzae type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenzae type b","option_only":true},"salmonella spp":{"title":"Salmonella","short":"Salmonella zijn gramnegatieve staven die voedselinfecties (gastro-enteritis) en buiktyfus kunnen veroorzaken.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> komen via onvoldoende verhit voedsel (kip, eieren) binnen en geven koorts, buikkrampen en diarree. <em>S. typhi</em> en <em>S. paratyphi</em> veroorzaken (para)tyfus, een systemische ziekte met hoge koorts, relatieve bradycardie en roseola. Bij sikkelcelziekte kan Salmonella osteomyelitis veroorzaken.</p>","image_url":"","wiki_title":"Salmonella","match":"salmonella spp|salmonella|salmonellosis","option_only":true},"necrotiserende fasciitis":{"title":"Necrotiserende fasciitis","short":"Necrotiserende fasciitis is een snel voortschrijdende, levensbedreigende infectie van de fascie en het onderhuidse weefsel.","definition":"<p>Bij <strong>necrotiserende fasciitis</strong> (vaak groep A-streptokokken of een gemengde flora) is de pijn veel heviger dan de huid doet vermoeden; later ontstaan bullae, verkleuring, gevoelloosheid en crepitaties, met sepsis. Snelle chirurgische verwijdering van het dode weefsel en antibiotica zijn levensreddend.</p>","image_url":"","wiki_title":"Necrotizing fasciitis","match":"necrotiserende fasciitis|vleesetende bacterie","option_only":true},"neurofibromatosis":{"title":"Neurofibromatose","short":"Neurofibromatose type 1 is een autosomaal dominante aandoening met café-au-laitvlekken, neurofibromen en een verhoogd tumorrisico.","definition":"<p>Bij <strong>NF1</strong> (mutatie in het tumorsuppressorgen neurofibromine) zijn er o.a. café-au-laitvlekken, sproeten in oksels en liezen, neurofibromen, Lisch-noduli op de iris, opticusgliomen en botafwijkingen. NF2 geeft vooral dubbelzijdige vestibulaire schwannomen en meningeomen.</p>","image_url":"","wiki_title":"Neurofibromatosis type I","match":"neurofibromatosis|neurofibromatose|nf1|ziekte van von recklinghausen","option_only":true},"pneumokokkenmeningitis":{"title":"Pneumokokkenmeningitis","short":"Pneumokokkenmeningitis is een bacteriële hersenvliesontsteking door Streptococcus pneumoniae, de belangrijkste verwekker bij volwassenen.","definition":"<p>Bij <strong>pneumokokkenmeningitis</strong> ontstaan hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn. Risicofactoren zijn otitis, sinusitis, liquorlekkage, splenectomie, alcoholisme en immuunsuppressie. Behandeling met antibiotica en dexamethason; restschade (gehoorverlies, neurologische uitval) komt veel voor.</p>","image_url":"","wiki_title":"Pneumococcal infection","match":"pneumokokkenmeningitis|pneumokokkenziekte","option_only":true},"bacteriële pneumonie":{"title":"Bacteriële pneumonie","short":"Een bacteriële pneumonie is een longontsteking door bacteriën, met koorts, hoesten met sputum en een infiltraat op de foto.","definition":"<p>De belangrijkste verwekker van een buiten het ziekenhuis opgelopen <strong>bacteriële pneumonie</strong> is de pneumokok; daarnaast o.a. <em>H. influenzae</em>, <em>S. aureus</em> (na influenza) en atypische verwekkers (<em>Mycoplasma</em>, <em>Legionella</em>). De ernst wordt ingeschat met bijv. de CURB-65-score.</p>","image_url":"","wiki_title":"Bacterial pneumonia","match":"bacteriële pneumonie|bacteriele pneumonie","option_only":true},"coronavirus":{"title":"Coronavirussen","short":"Coronavirussen zijn omhulde RNA-virussen die meestal verkoudheden veroorzaken; sommige (SARS-CoV, SARS-CoV-2, MERS) geven ernstige luchtwegziekte.","definition":"<p><strong>Coronavirussen</strong> danken hun naam aan de kroon van spike-eiwitten. Seizoensgebonden typen geven verkoudheid. SARS-CoV-2 bindt aan ACE2 en veroorzaakt COVID-19. Omhulde virussen zijn gevoelig voor zeep en alcohol.</p>","image_url":"","wiki_title":"Coronavirus","match":"coronavirus|coronavirussen","option_only":true},"para-influenzavirus type 2":{"title":"Para-influenzavirus","short":"Para-influenzavirussen zijn RNA-virussen die luchtweginfecties geven; ze zijn de belangrijkste verwekker van pseudokroep bij jonge kinderen.","definition":"<p><strong>Para-influenzavirussen</strong> (paramyxovirussen, type 1–4) veroorzaken vooral bij kinderen van 6 maanden tot 3 jaar een laryngotracheitis (pseudokroep), met een blafhoest, heesheid en inspiratoire stridor, vaak ’s nachts. Behandeling bij ernstige vormen met dexamethason.</p>","image_url":"","wiki_title":"Human parainfluenza viruses","match":"para-influenzavirus type 2|parainfluenzavirus type 2|parainfluenzavirus|para-influenzavirus","option_only":true},"influenzavirus type a":{"title":"Influenza A-virus","short":"Influenza A is het type influenzavirus dat bij mens en dier voorkomt en door antigene shift pandemieën kan veroorzaken.","definition":"<p>Bij <strong>influenza A</strong> worden subtypes benoemd naar hemagglutinine en neuraminidase (bijv. H1N1, H3N2). Door uitwisseling van gensegmenten tussen virussen van mens, vogel en varken (shift) kunnen nieuwe subtypes ontstaan waartegen niemand immuun is. Neuraminidaseremmers zoals oseltamivir werken tegen influenza A en B.</p>","image_url":"","wiki_title":"Influenza A virus","match":"influenzavirus type a|influenza a-virus","option_only":true},"ziekte van pfeiffer":{"title":"Ziekte van Pfeiffer","short":"De ziekte van Pfeiffer (mononucleosis infectiosa) is een infectie met het Epstein-Barrvirus met keelpijn, koorts, lymfeklierzwelling en moeheid.","definition":"<p>De <strong>ziekte van Pfeiffer</strong> treft vooral adolescenten en jongvolwassenen. Het bloedbeeld toont atypische lymfocyten. Een complicatie is een miltruptuur, waardoor contactsport enkele weken wordt afgeraden. Bij gebruik van amoxicilline ontstaat vaak een huiduitslag. De moeheid kan weken tot maanden aanhouden.</p>","image_url":"","wiki_title":"Infectious mononucleosis","match":"ziekte van pfeiffer|pfeiffer|klierkoorts","option_only":true},"syndroom van noonan":{"title":"Syndroom van Noonan","short":"Het syndroom van Noonan is een erfelijke aandoening (RAS-pathway) met kleine lengte, kenmerkend gezicht, pulmonalisstenose en een brede nek.","definition":"<p>Het <strong>syndroom van Noonan</strong> erft autosomaal dominant over (vaak PTPN11-mutatie) en komt bij jongens en meisjes voor. Kenmerken: kleine lengte, een brede of gevleugelde nek, laagstaande oren, wijd uiteen staande ogen, hartafwijkingen (vooral pulmonalisstenose, hypertrofische cardiomyopathie), stollingsproblemen en soms niet-ingedaalde testes. Er is overlap met het uiterlijk bij Turner, maar het karyotype is normaal.</p>","image_url":"","wiki_title":"Noonan syndrome","match":"syndroom van noonan|noonansyndroom","option_only":true},"pulmonalisstenose":{"title":"Pulmonalisstenose","short":"Bij pulmonalisstenose is de uitstroom van de rechterventrikel naar de longslagader vernauwd, meestal ter hoogte van de klep.","definition":"<p>Een <strong>pulmonalisstenose</strong> geeft een systolisch ejectiegeruis links hoog parasternaal en rechterventrikelhypertrofie. Lichte vormen geven geen klachten; ernstige vormen bij pasgeborenen kunnen cyanose geven. Het komt voor bij het syndroom van Noonan en als onderdeel van de tetralogie van Fallot. Behandeling met ballondilatatie.</p>","image_url":"","wiki_title":"Pulmonary valve stenosis","match":"pulmonalisstenose|pulmonalisklepstenose","option_only":true},"lactose-intolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"lactose-intolerantie|lactoseintolerantie|lactasedeficiëntie|lactase deficiëntie","option_only":true},"guillain-barré syndroom":{"title":"Syndroom van Guillain-Barré","short":"Het syndroom van Guillain-Barré is een acute auto-immuunpolyneuropathie met snel oplopende, symmetrische slappe verlamming en areflexie.","definition":"<p>Het <strong>Guillain-Barré-syndroom</strong> volgt vaak 1–4 weken na een infectie (bijv. <em>Campylobacter</em>, CMV). Zwakte begint meestal in de benen en stijgt op; ademhalingsspieren en hersenzenuwen kunnen betrokken raken, en er kunnen autonome stoornissen optreden. Liquor toont eiwit-celdissociatie. Behandeling met immunoglobulinen of plasmaferese.</p>","image_url":"","wiki_title":"Guillain–Barré syndrome","match":"guillain-barré syndroom|guillain-barrésyndroom|guillain-barre","option_only":true},"koplikse vlekjes":{"title":"Koplikvlekjes","short":"Koplikvlekjes zijn kleine witte stipjes op een rode ondergrond op het wangslijmvlies, kenmerkend voor mazelen.","definition":"<p><strong>Koplikvlekjes</strong> verschijnen in de prodromale fase van mazelen, een of twee dagen vóór de huiduitslag, vaak tegenover de kiezen. Ze zijn pathognomonisch maar verdwijnen snel.</p>","image_url":"","wiki_title":"Koplik's spots","match":"koplikse vlekjes|koplikvlekjes|koplik","option_only":true},"subacute scleroserende panencefalitis":{"title":"Subacute scleroserende panencefalitis (SSPE)","short":"SSPE is een zeldzame, dodelijke late complicatie van mazelen, jaren na de infectie, door persisterend virus in het brein.","definition":"<p><strong>SSPE</strong> treedt gemiddeld 7–10 jaar na mazelen op, vooral bij infectie op zeer jonge leeftijd. Het geeft progressieve gedrags- en cognitieve achteruitgang, myoclonieën en uiteindelijk coma. Er zijn hoge antistoftiters tegen mazelen in liquor. Vaccinatie voorkomt het.</p>","image_url":"","wiki_title":"Subacute sclerosing panencephalitis","match":"subacute scleroserende panencefalitis|sspe","option_only":true},"polymerase kettingreactie (pcr)":{"title":"PCR (polymerasekettingreactie)","short":"PCR is een techniek om een stukje DNA (of RNA via reverse transcriptie) sterk te vermenigvuldigen en zo aan te tonen.","definition":"<p>Bij <strong>PCR</strong> worden in herhaalde cycli DNA gedenatureerd, primers gehecht en nieuw DNA gesynthetiseerd door een hittestabiel polymerase. Het wordt gebruikt om micro-organismen snel en gevoelig aan te tonen, mutaties op te sporen en virale ladingen te meten. Een positieve PCR bewijst de aanwezigheid van genetisch materiaal, niet altijd van levend, ziekmakend micro-organisme.</p>","image_url":"","wiki_title":"Polymerase chain reaction","match":"polymerase kettingreactie (pcr)|pcr|polymerasekettingreactie","option_only":true},"tricyclisch antidepressivum":{"title":"Tricyclische antidepressiva","short":"Tricyclische antidepressiva remmen de heropname van noradrenaline en serotonine en hebben veel anticholinerge bijwerkingen.","definition":"<p><strong>TCA's</strong> (zoals amitriptyline, nortriptyline, clomipramine) worden gebruikt bij depressie en in lage dosis bij neuropathische pijn. Bijwerkingen: droge mond, obstipatie, urineretentie, sufheid, orthostatische hypotensie en gewichtstoename. Bij overdosering zijn ze gevaarlijk door natriumkanaalblokkade (breed QRS, aritmieën) en insulten.</p>","image_url":"","wiki_title":"Tricyclic antidepressant","match":"tricyclisch antidepressivum|tricyclische antidepressiva|tca|amitriptyline|nortriptyline","option_only":true},"ecstasy (xtc)":{"title":"Ecstasy (MDMA)","short":"Ecstasy (MDMA) is een stimulerende drug die vooral serotonine (en dopamine, noradrenaline) laat vrijkomen.","definition":"<p><strong>MDMA</strong> geeft euforie, verbondenheid en energie. Risico's zijn hyperthermie, uitdroging of juist hyponatriëmie (door veel water drinken en ADH-afgifte), serotoninesyndroom, hartritmestoornissen en zelden leverfalen. Na gebruik kan een tijdelijke somberheid optreden.</p>","image_url":"","wiki_title":"MDMA","match":"ecstasy (xtc)|ecstasy|xtc|mdma","option_only":true},"longtuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"longtuberculose|primaire tuberculose|reactivatie van tuberculose|latente tuberculose","option_only":true},"decontaminatie":{"title":"Decontaminatie","short":"Decontaminatie is het verwijderen of onschadelijk maken van micro-organismen of schadelijke stoffen van een oppervlak of instrument.","definition":"<p>In de infectiepreventie volgt op <strong>reiniging</strong> (vuil en organisch materiaal verwijderen) desinfectie (de meeste micro-organismen doden) en zo nodig sterilisatie (alle micro-organismen, inclusief sporen). Zonder goede reiniging werken desinfectie en sterilisatie onvoldoende.</p>","image_url":"","wiki_title":"Decontamination","match":"decontaminatie","option_only":true},"sterilisatie":{"title":"Sterilisatie (infectiepreventie)","short":"Sterilisatie is het doden of verwijderen van alle micro-organismen, inclusief bacteriële sporen.","definition":"<p><strong>Sterilisatie</strong> gebeurt meestal met stoom onder druk (autoclaaf), of met gas, plasma of straling voor hittegevoelige materialen. Het is nodig voor instrumenten die steriel weefsel of de bloedbaan binnengaan. Prionen zijn extra resistent en vragen speciale procedures.</p>","image_url":"","wiki_title":"Sterilization (microbiology)","match":"sterilisatie","option_only":true},"antisepsis":{"title":"Antisepsis","short":"Antisepsis is het doden of remmen van micro-organismen op levend weefsel, zoals huid en slijmvliezen.","definition":"<p><strong>Antiseptica</strong> zijn bijvoorbeeld alcohol, chloorhexidine en jodium. Ze worden gebruikt voor handdesinfectie en het ontsmetten van de huid vóór een injectie of operatie. Desinfectie gaat over levenloze oppervlakken.</p>","image_url":"","wiki_title":"Antiseptic","match":"antisepsis|antiseptica|antisepticum","option_only":true},"entamoeba":{"title":"Entamoeba histolytica","short":"Entamoeba histolytica is een protozo die amoebendysenterie en leverabcessen kan veroorzaken.","definition":"<p><strong><em>Entamoeba histolytica</em></strong> wordt via cysten in besmet water of voedsel opgelopen. Invasieve infectie van het colon geeft bloederige diarree; via de v. portae kan een amoebenleverabces ontstaan. Behandeling met metronidazol, gevolgd door een middel tegen de cysten in de darm.</p>","image_url":"","wiki_title":"Entamoeba histolytica","match":"entamoeba|entamoeba histolytica","option_only":true},"enterobius":{"title":"Enterobius vermicularis (aarsmade)","short":"Enterobius vermicularis (aarsmade) is een kleine witte worm die vooral bij kinderen ’s nachts jeuk rond de anus geeft.","definition":"<p>Bij <strong>enterobiasis</strong> leggen de vrouwtjes ’s nachts eitjes rond de anus. Door krabben komen de eitjes onder de nagels en weer in de mond (auto-infectie), en worden ook gezinsleden besmet. Diagnose met een plakbandpreparaat ’s ochtends; behandeling met mebendazol voor het hele gezin, plus hygiënemaatregelen.</p>","image_url":"","wiki_title":"Pinworm infection","match":"enterobius|enterobiasis|enterobius vermicularis|aarsmade|aarsmaden","option_only":true},"fusobacterium nucleatum":{"title":"Fusobacterium","short":"Fusobacteriën zijn gramnegatieve anaerobe staven uit de mondflora, betrokken bij abcessen en het syndroom van Lemierre.","definition":"<p><strong>Fusobacteriën</strong> komen voor in de mond en het maag-darmkanaal. Ze spelen een rol bij parodontitis, peritonsillaire abcessen en, door <em>F. necrophorum</em>, het syndroom van Lemierre: een tromboflebitis van de v. jugularis interna na een keelinfectie, met septische longembolieën. <em>F. nucleatum</em> wordt ook in verband gebracht met coloncarcinoom.</p>","image_url":"","wiki_title":"Fusobacterium","match":"fusobacterium nucleatum|fusobacterium|fusobacterium necrophorum","option_only":true},"balanoposthitis":{"title":"Balanoposthitis","short":"Balanoposthitis is een ontsteking van de eikel en de voorhuid.","definition":"<p><strong>Balanoposthitis</strong> komt vooral voor bij onbesneden jongens en mannen, bij slechte hygiëne, fimose of diabetes (<em>Candida</em>). Er zijn roodheid, zwelling, pijn en afscheiding. Behandeling met hygiëne, eventueel een antimycotische of antibacteriële crème. Recidieven kunnen op diabetes of lichen sclerosus wijzen.</p>","image_url":"","wiki_title":"Balanitis","match":"balanoposthitis|balanitis","option_only":true},"peniscarcinoom":{"title":"Peniscarcinoom","short":"Het peniscarcinoom is een zeldzame, meestal plaveiselcellige kanker van de penis, geassocieerd met HPV en fimose.","definition":"<p>Risicofactoren voor <strong>peniscarcinoom</strong> zijn HPV-infectie, fimose, slechte hygiëne, lichen sclerosus en roken. Het begint vaak als een niet-genezende plek of zweer op de glans of voorhuid. Vroege besnijdenis vermindert het risico sterk.</p>","image_url":"","wiki_title":"Penile cancer","match":"peniscarcinoom|peniskanker","option_only":true},"tonsilhypertrofie":{"title":"Tonsilhypertrofie","short":"Bij tonsilhypertrofie zijn de keelamandelen (en vaak de neusamandel) vergroot, wat bij kinderen snurken en slaapapneu kan geven.","definition":"<p><strong>Vergrote tonsillen en adenoïd</strong> komen veel voor bij jonge kinderen. Ze kunnen leiden tot mondademhaling, snurken, obstructieve slaapapneu (met onrustig slapen, gedragsproblemen) en slikproblemen. Bij ernstige klachten wordt een (adeno)tonsillectomie overwogen.</p>","image_url":"","wiki_title":"Tonsil","match":"tonsilhypertrofie|vergrote amandelen|adenotonsillaire hypertrofie","option_only":true},"corpus alienum in de luchtweg":{"title":"Corpus alienum in de luchtweg","short":"Een corpus alienum in de luchtweg is een ingeademd vreemd voorwerp; bij jonge kinderen een belangrijke oorzaak van plotselinge benauwdheid.","definition":"<p>Bij <strong>aspiratie van een vreemd voorwerp</strong> (vaak pinda's, speelgoedonderdelen) ontstaan plotseling hoesten, verslikken en benauwdheid; later kan een eenzijdig piepen, verminderd ademgeruis of een recidiverende pneumonie optreden. Het voorwerp komt vaak in de rechter hoofdbronchus terecht. Verwijdering via een bronchoscopie.</p>","image_url":"","wiki_title":"Foreign body aspiration","match":"corpus alienum in de luchtweg|corpus alienum|vreemd voorwerp","option_only":true},"laryngitis subglottica":{"title":"Laryngitis subglottica (pseudokroep)","short":"Pseudokroep is een virale ontsteking onder de stembanden bij jonge kinderen, met blafhoest, heesheid en inspiratoire stridor.","definition":"<p><strong>Pseudokroep</strong> wordt meestal veroorzaakt door para-influenzavirussen en treedt vaak ’s nachts op bij kinderen van 6 maanden tot 3 jaar. Behandeling: geruststellen en bij matig tot ernstige klachten dexamethason; bij ernstige stridor in rust adrenalinevernevelingen. Het moet onderscheiden worden van epiglottitis.</p>","image_url":"","wiki_title":"Croup","match":"laryngitis subglottica|pseudokroep|kroep","option_only":true},"epiglottitis":{"title":"Epiglottitis","short":"Epiglottitis is een levensbedreigende bacteriële ontsteking van het strotklepje, met risico op acute luchtwegafsluiting.","definition":"<p>Bij <strong>epiglottitis</strong> (vroeger vooral door <em>H. influenzae</em> type b, nu zeldzaam dankzij vaccinatie) zijn kinderen ernstig ziek, met hoge koorts, kwijlen, slikpijn, een gedempte stem en een rechtop-voorovergebogen houding. Niet in de keel kijken en het kind niet laten liggen; direct een gecontroleerde luchtwegbeveiliging en antibiotica.</p>","image_url":"","wiki_title":"Epiglottitis","match":"epiglottitis","option_only":true},"late onset adrenogenitaal syndroom":{"title":"Adrenogenitaal syndroom (congenitale bijnierhyperplasie)","short":"Het adrenogenitaal syndroom is een erfelijk enzymdefect (meestal 21-hydroxylase) in de bijnierschors, met cortisoltekort en een overmaat aan androgenen.","definition":"<p>Bij <strong>congenitale bijnierhyperplasie</strong> stijgt ACTH door het cortisoltekort, waardoor de bijnier groeit en veel androgenen maakt. De klassieke vorm geeft bij meisjes een vermannelijkt genitaal en bij beide geslachten vaak zoutverlies (aldosterontekort) in de eerste weken. De niet-klassieke (late onset) vorm geeft pas later hirsutisme, acne en cyclusstoornissen, lijkend op PCOS. Het wordt opgespoord met de hielprik.</p>","image_url":"","wiki_title":"Congenital adrenal hyperplasia","match":"late onset adrenogenitaal syndroom|adrenogenitaal syndroom|congenitale bijnierhyperplasie|ags","option_only":true},"centrale pubertas praecox":{"title":"Centrale pubertas praecox","short":"Bij centrale pubertas praecox start de puberteit te vroeg (meisjes <8, jongens <9 jaar) door vroege activatie van de hypothalamus-hypofyse-gonade-as.","definition":"<p>Bij <strong>centrale pubertas praecox</strong> zijn LH en FSH verhoogd en verloopt de puberteit in de normale volgorde, maar te vroeg. Bij meisjes is het meestal idiopathisch; bij jongens vaker door een afwijking in het brein (bijv. hamartoom). Gevolg is een snelle groei en vroege sluiting van de groeischijven. Behandeling met GnRH-analogen.</p>","image_url":"","wiki_title":"Precocious puberty","match":"centrale pubertas praecox|pubertas praecox|vroegtijdige puberteit","option_only":true},"propionibacterium acnes":{"title":"Cutibacterium acnes","short":"Cutibacterium (Propionibacterium) acnes is een grampositieve staaf van de huidflora die bijdraagt aan de ontsteking bij acne.","definition":"<p><strong><em>C. acnes</em></strong> leeft in talgrijke haarfollikels en breekt talg af tot vetzuren die ontsteking bevorderen. Het speelt een rol bij acne vulgaris; behandeling met benzoylperoxide en eventueel antibiotica remt de bacterie. Het kan ook infecties van prothesen en shunts veroorzaken.</p>","image_url":"","wiki_title":"Cutibacterium acnes","match":"propionibacterium acnes|cutibacterium acnes|p. acnes","option_only":true},"trisomie 21":{"title":"Trisomie 21 (syndroom van Down)","short":"Het syndroom van Down ontstaat door een extra (deel van) chromosoom 21, met verstandelijke beperking en kenmerkende uiterlijke en medische kenmerken.","definition":"<p>Bij <strong>trisomie 21</strong> (meestal door non-disjunctie, risico stijgend met de leeftijd van de moeder) zijn er o.a. hypotonie, een kenmerkend gezicht, één handpalmplooi, hartafwijkingen (AVSD), duodenumatresie, ziekte van Hirschsprung, hypothyreoïdie, een verhoogd risico op leukemie en vroege Alzheimer. Prenatale screening gebeurt met de NIPT.</p>","image_url":"","wiki_title":"Down syndrome","match":"trisomie 21|syndroom van down|down syndroom","option_only":true},"cystische fibrose (taaislijmziekte)":{"title":"Cystische fibrose (taaislijmziekte)","short":"Cystische fibrose is een autosomaal recessieve ziekte door mutaties in het CFTR-gen, met taai slijm in longen, pancreas en andere organen.","definition":"<p>Bij <strong>cystische fibrose</strong> werkt het CFTR-chloridekanaal niet goed, waardoor secreties taai worden. Gevolgen: chronische luchtweginfecties (o.a. <em>S. aureus</em>, <em>Pseudomonas</em>) en bronchiëctasieën, exocriene pancreasinsufficiëntie (steatorroe, groeiachterstand), meconiumileus, CF-gerelateerde diabetes en onvruchtbaarheid bij mannen. Diagnose via hielprik en zweettest; CFTR-modulatoren hebben de prognose sterk verbeterd.</p>","image_url":"","wiki_title":"Cystic fibrosis","match":"cystische fibrose (taaislijmziekte)|cystische fibrose|taaislijmziekte|cf|mucoviscidose","option_only":true},"alfa thalassemie":{"title":"Alfa-thalassemie","short":"Bij alfa-thalassemie worden te weinig alfa-globineketens gemaakt, door deletie van een of meer van de vier alfa-genen.","definition":"<p>Het beeld van <strong>alfa-thalassemie</strong> hangt af van het aantal ontbrekende genen: van stil dragerschap (1) en een lichte microcytaire anemie (2) tot HbH-ziekte (3) en hydrops foetalis (4, Hb Bart's). Dragers hebben een microcytaire anemie met een normaal ferritine, wat onderscheid met ijzergebrek belangrijk maakt.</p>","image_url":"","wiki_title":"Alpha-thalassemia","match":"alfa thalassemie|alfa-thalassemie|thalassemie","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"claritromycine":{"title":"Claritromycine","short":"Claritromycine is een macrolide-antibioticum dat de eiwitsynthese remt (50S); het werkt ook tegen atypische verwekkers.","definition":"<p><strong>Macroliden</strong> (claritromycine, azitromycine, erytromycine) binden aan het 50S-ribosoom. Ze werken tegen o.a. streptokokken, <em>Mycoplasma</em>, <em>Chlamydia</em>, <em>Legionella</em> en kinkhoest, en zitten in H. pylori-eradicatie. Bijwerkingen: maag-darmklachten, QT-verlenging; claritromycine en erytromycine remmen CYP3A4 (interacties).</p>","image_url":"","wiki_title":"Clarithromycin","match":"claritromycine|macroliden|macrolide|azitromycine|erytromycine","option_only":true},"av-block":{"title":"AV-blok","short":"Een AV-blok is een vertraagde of geblokkeerde geleiding van de prikkel van de boezems naar de kamers.","definition":"<p>Bij een <strong>eerstegraads AV-blok</strong> is het PR-interval verlengd. Bij een <strong>tweedegraads</strong> blok vallen sommige QRS-complexen weg (Wenckebach: geleidelijke PR-verlenging; Mobitz II: plotseling, gevaarlijker). Bij een <strong>derdegraads</strong> (totaal) blok kloppen boezems en kamers onafhankelijk, met een traag escaperitme. Oorzaken: degeneratie, ischemie, medicatie, ziekte van Lyme, sarcoïdose, aangeboren (maternale anti-SSA).</p>","image_url":"","wiki_title":"Atrioventricular block","match":"av-block|av-blok|atrioventriculair blok|atrioventriculaire geleidingsstoornissen|atroventriculaire geleidingsstoornissen","option_only":true},"levocetirizine":{"title":"Levocetirizine","short":"Levocetirizine is een tweede generatie H1-antihistaminicum dat weinig sufheid geeft; gebruikt bij hooikoorts en urticaria.","definition":"<p>Tweede generatie <strong>antihistaminica</strong> (cetirizine, levocetirizine, loratadine) blokkeren H1-receptoren en passeren de bloed-hersenbarrière nauwelijks, waardoor ze minder sederend en anticholinerg zijn dan de eerste generatie (zoals clemastine). Ze verminderen jeuk, niezen, waterige neus en netelroos.</p>","image_url":"","wiki_title":"Levocetirizine","match":"levocetirizine|cetirizine|antihistaminicum|antihistaminica","option_only":true},"atopische constitutie":{"title":"Atopische constitutie","short":"Atopie is een erfelijke aanleg om IgE te maken tegen alledaagse allergenen, met een verhoogde kans op eczeem, astma en hooikoorts.","definition":"<p>Bij een <strong>atopische constitutie</strong> komen constitutioneel eczeem, voedselallergie, allergisch astma en allergische rhinitis vaak in een volgorde voor (de ‘atopische mars’). De aanleg kan worden aangetoond met specifiek IgE of huidpriktesten.</p>","image_url":"","wiki_title":"Atopy","match":"atopische constitutie|atopie|atopisch","option_only":true},"coagulopathie":{"title":"Coagulopathie","short":"Een coagulopathie is een stoornis in de bloedstolling, met een verhoogde bloedingsneiging.","definition":"<p>Oorzaken van een <strong>coagulopathie</strong> zijn erfelijke stollingsfactortekorten (hemofilie, von Willebrand), leverziekte (minder aanmaak), vitamine K-tekort of cumarines, diffuse intravasale stolling, verdunning bij massale transfusie en antistollingsmiddelen. PT, APTT, fibrinogeen en plaatjesgetal helpen de oorzaak te vinden.</p>","image_url":"","wiki_title":"Coagulopathy","match":"coagulopathie|stollingsstoornis","option_only":true},"glaucoom":{"title":"Glaucoom","short":"Glaucoom is een groep oogziekten met schade aan de oogzenuw en gezichtsvelduitval, meestal samenhangend met een verhoogde oogdruk.","definition":"<p>Bij het meest voorkomende <strong>openkamerhoekglaucoom</strong> verloopt de schade langzaam en ongemerkt, met eerst uitval in het perifere gezichtsveld en een toenemende excavatie van de papil. Risicofactoren: hogere leeftijd, verhoogde oogdruk, familie, myopie en een donkere huidskleur. Behandeling met oogdrukverlagende druppels, laser of operatie. Acuut glaucoom is een apart, acuut ziektebeeld.</p>","image_url":"","wiki_title":"Glaucoma","match":"glaucoom|groene staar|openkamerhoekglaucoom","option_only":true},"claviculafractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"claviculafractuur|sleutelbeenbreuk","option_only":true},"chronische veneuze insufficiëntie":{"title":"Chronische veneuze insufficiëntie","short":"Bij chronische veneuze insufficiëntie werkt de veneuze terugstroom uit de benen slecht, met oedeem, huidverkleuring en uiteindelijk ulcera.","definition":"<p>Door lekkende kleppen of een doorgemaakte trombose (posttrombotisch syndroom) stijgt de veneuze druk in de benen. Gevolgen: varices, oedeem, hyperpigmentatie (hemosiderine), eczeem, lipodermatosclerose, atrophie blanche en een ulcus cruris venosum, typisch rond de mediale enkel. Behandeling met compressietherapie.</p>","image_url":"","wiki_title":"Chronic venous insufficiency","match":"chronische veneuze insufficiëntie|veneuze insufficiëntie","option_only":true},"cerebral palsy":{"title":"Cerebrale parese","short":"Cerebrale parese is een blijvende houdings- en bewegingsstoornis door een niet-progressieve beschadiging van het zich ontwikkelende brein.","definition":"<p>Oorzaken van <strong>cerebrale parese</strong> liggen vóór, rond of kort na de geboorte: prematuriteit (periventriculaire leukomalacie), asfyxie, infecties, herseninfarcten en afwijkingen in de aanleg. Vormen zijn spastisch (meest voorkomend), dyskinetisch en ataxisch. Vaak zijn er bijkomende problemen zoals epilepsie, verstandelijke beperking en slikproblemen.</p>","image_url":"","wiki_title":"Cerebral palsy","match":"cerebral palsy|cerebrale parese|cp","option_only":true},"porine":{"title":"Porine","short":"Porines zijn kanaaleiwitten in de buitenmembraan van gramnegatieve bacteriën die kleine moleculen doorlaten.","definition":"<p>Via <strong>porines</strong> kunnen voedingsstoffen, maar ook antibiotica zoals bètalactams, de periplasmatische ruimte bereiken. Verlies of verandering van porines is een mechanisme van antibioticaresistentie, bijvoorbeeld tegen carbapenems bij <em>Pseudomonas</em>.</p>","image_url":"","wiki_title":"Porin (protein)","match":"porine|porinen","option_only":true},"de ziekte van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"de ziekte van kawasaki","option_only":true},"syndroom van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"syndroom van kawasaki","option_only":true},"tromboembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"tromboembolie","option_only":true},"trombo-embolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"trombo-embolie","option_only":true},"bacteriële endocarditis met s. aureus":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"bacteriële endocarditis met s. aureus","option_only":true},"endocarditis lenta":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis lenta","option_only":true},"longontsteking door sars-cov-2":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"longontsteking door sars-cov-2","option_only":true},"erythema infectiosum":{"title":"Erythema infectiosum (vijfde ziekte)","short":"Erythema infectiosum is een kinderziekte door parvovirus B19 met felrode ‘slapwangen’ en daarna een kantachtige uitslag.","definition":"<p>Parvovirus B19 infecteert erytroïde voorlopercellen. Bij mensen met chronische hemolyse kan het een aplastische crise geven, en in de zwangerschap foetale anemie en hydrops. Bij volwassenen geeft het vaak symmetrische gewrichtsklachten.</p>","image_url":"","wiki_title":"Erythema infectiosum","match":"erythema infectiosum|vijfde ziekte|parvovirus b19|parvo b19","option_only":true},"impetigo contagiosa":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"impetigo contagiosa|impetigo|krentenbaard","option_only":true},"syndroom van takayasu":{"title":"Ziekte van Takayasu","short":"De ziekte van Takayasu is een grote-vatenvasculitis bij jonge vrouwen, met vernauwingen van de aorta en haar takken (‘pulseless disease’).","definition":"<p>Bij <strong>Takayasu-arteriitis</strong> zijn de polsen aan de armen vaak zwak of afwezig, met een bloeddrukverschil tussen beide armen, claudicatio van de armen en vaatgeruisen. Diagnose met beeldvorming van de vaten; behandeling met corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Takayasu's arteritis","match":"syndroom van takayasu|ziekte van takayasu|takayasu","option_only":true},"kortademigheid":{"title":"Dyspneu (kortademigheid)","short":"Dyspneu is het subjectieve gevoel van moeilijk of onvoldoende kunnen ademen.","definition":"<p><strong>Kortademigheid</strong> kan een pulmonale oorzaak hebben (astma, COPD, pneumonie, longembolie, pneumothorax), een cardiale (hartfalen, ischemie, ritmestoornissen), of samenhangen met anemie, obesitas, conditieverlies, angst of metabole acidose. Het tijdsbeloop (acuut of chronisch) en bijkomende klachten sturen de diagnostiek.</p>","image_url":"","wiki_title":"Shortness of breath","match":"kortademigheid|dyspneu|dyspnoe|benauwdheid","option_only":true},"tachypneu":{"title":"Tachypneu","short":"Tachypneu is een te snelle ademhaling, bij volwassenen meer dan ongeveer 20 per minuut.","definition":"<p><strong>Tachypneu</strong> komt voor bij koorts, pijn, angst, longaandoeningen, hartfalen, sepsis en metabole acidose (compenserend). Een verhoogde ademfrequentie is een belangrijk alarmsignaal in vroege-waarschuwingsscores. Bij kinderen gelden leeftijdsafhankelijke grenzen.</p>","image_url":"","wiki_title":"Tachypnea","match":"tachypneu|tachypnoe|snelle ademhaling","option_only":true},"methadon":{"title":"Methadon","short":"Methadon is een langwerkend opioïd dat wordt gebruikt bij opioïdverslaving en bij pijn.","definition":"<p><strong>Methadon</strong> heeft een lange en per persoon wisselende halfwaardetijd, waardoor het onttrekkingsverschijnselen en craving voorkomt. Het wordt ook bij moeilijk behandelbare pijn gebruikt (NMDA-antagonisme). Risico's zijn accumulatie, ademhalingsdepressie en QT-verlenging.</p>","image_url":"","wiki_title":"Methadone","match":"methadon|methadone","option_only":true},"acuut leverfalen":{"title":"Acuut leverfalen","short":"Bij acuut leverfalen schiet de leverfunctie binnen enkele weken ernstig tekort, met stollingsstoornis en encefalopathie, zonder eerdere leverziekte.","definition":"<p>Oorzaken van <strong>acuut leverfalen</strong> zijn o.a. paracetamolintoxicatie, virale hepatitis (A, B, E), geneesmiddelen, auto-immuunhepatitis, de ziekte van Wilson en zwangerschapsgerelateerde ziekten. Kenmerken: icterus, een verlengde INR en hepatische encefalopathie. Snelle verwijzing naar een transplantatiecentrum is nodig.</p>","image_url":"","wiki_title":"Acute liver failure","match":"acuut leverfalen|fulminant leverfalen|leverfalen","option_only":true},"ventrikelfibrilleren (vf)":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren (vf)","option_only":true},"tachycardie (hoge hartfrequentie)":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie (hoge hartfrequentie)","option_only":true},"listeria monocyogenes":{"title":"Listeria monocytogenes","short":"Listeria is een grampositieve staaf die via voedsel wordt opgelopen en vooral bij zwangeren, pasgeborenen, ouderen en afweergestoorden infecties geeft.","definition":"<p><strong><em>Listeria monocytogenes</em></strong> kan groeien bij koelkasttemperatuur en komt voor in rauwmelkse kaas, paté en gerookte vis. Hij groeit intracellulair en verspreidt zich van cel tot cel via actinestaarten. Infecties: meningitis en sepsis, en bij zwangeren risico op miskraam of neonatale infectie. Cefalosporines werken niet; amoxicilline wel.</p>","image_url":"","wiki_title":"Listeria monocytogenes","match":"listeria monocyogenes","option_only":true},"cytomegalovirusinfectie":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirusinfectie","option_only":true},"plasmodium falciparum malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum malaria","option_only":true},"s. pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"s. pneumoniae","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"klebsiella spp":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella spp","option_only":true},"bacteri&euml;le conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteri&euml;le conjunctivitis","option_only":true},"bacteriële conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteriële conjunctivitis","option_only":true},"virale/banale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale/banale conjunctivitis","option_only":true},"bacteriële meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"bacteriële meningitis","option_only":true},"een antihistaminicum":{"title":"Levocetirizine","short":"Levocetirizine is een tweede generatie H1-antihistaminicum dat weinig sufheid geeft; gebruikt bij hooikoorts en urticaria.","definition":"<p>Tweede generatie <strong>antihistaminica</strong> (cetirizine, levocetirizine, loratadine) blokkeren H1-receptoren en passeren de bloed-hersenbarrière nauwelijks, waardoor ze minder sederend en anticholinerg zijn dan de eerste generatie (zoals clemastine). Ze verminderen jeuk, niezen, waterige neus en netelroos.</p>","image_url":"","wiki_title":"Levocetirizine","match":"een antihistaminicum","option_only":true},"herpes simplex type 2":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes simplex type 2","option_only":true},"humaan papillomavirus 16/18":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus 16/18","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"iga deficiëntie":{"title":"Selectieve IgA-deficiëntie","short":"Selectieve IgA-deficiëntie is de meest voorkomende primaire immuundeficiëntie; veel mensen hebben geen klachten.","definition":"<p>Bij <strong>IgA-deficiëntie</strong> kunnen recidiverende luchtweg- en darminfecties, giardiasis, coeliakie en auto-immuunziekten voorkomen. Bij coeliakie-serologie moet het totaal-IgA worden bepaald, omdat IgA-antistoffen vals-negatief kunnen zijn. Bij transfusies kan een anafylactische reactie op IgA in donorbloed optreden.</p>","image_url":"","wiki_title":"Selective immunoglobulin A deficiency","match":"iga deficiëntie|iga-deficiëntie|selectieve iga-deficiëntie","option_only":true},"pulmonalisklepinsufficiëntie":{"title":"Pulmonalisklepinsufficiëntie","short":"Bij pulmonalisklepinsufficiëntie lekt bloed in de diastole terug van de longslagader naar de rechterventrikel.","definition":"<p>Een lichte lekkage is vaak fysiologisch. Ernstige <strong>pulmonalisinsufficiëntie</strong> komt vooral voor na chirurgische correctie van een tetralogie van Fallot en bij pulmonale hypertensie; het kan leiden tot verwijding en falen van de rechterventrikel.</p>","image_url":"","wiki_title":"Pulmonary valve insufficiency","match":"pulmonalisklepinsufficiëntie|pulmonalisinsufficiëntie","option_only":true},"ventriculaire extrasystolen":{"title":"Ventriculaire extrasystolen (VES)","short":"Ventriculaire extrasystolen zijn vroegtijdige hartslagen die uit de kamers ontstaan, met een breed QRS-complex.","definition":"<p>Losse <strong>VES</strong> komen bij veel gezonde mensen voor en worden gevoeld als een overgeslagen of harde slag. Uitlokkers zijn cafeïne, alcohol, stress en slaaptekort. Bij veel VES, klachten of onderliggende hartziekte is verder onderzoek nodig; zeer frequente VES kunnen de pompfunctie verminderen.</p>","image_url":"","wiki_title":"Premature ventricular contraction","match":"ventriculaire extrasystolen|ves|ventriculaire extrasystole","option_only":true},"capside":{"title":"Capside","short":"Het capside is de eiwitmantel die het genetisch materiaal van een virus omsluit.","definition":"<p>Het <strong>capside</strong> bestaat uit herhaalde eiwiteenheden (capsomeren) en is meestal icosaëdrisch of helixvormig. Samen met het nucleïnezuur vormt het het nucleocapside; omhulde virussen hebben daaromheen nog een lipide-envelop afkomstig van de gastheercel. Niet-omhulde virussen zijn stabieler in de omgeving.</p>","image_url":"","wiki_title":"Capsid","match":"capside|capsid","option_only":true},"hyperthermie":{"title":"Hyperthermie","short":"Bij hyperthermie stijgt de lichaamstemperatuur doordat warmteproductie of -opname groter is dan de warmteafgifte, zonder verhoogd setpoint.","definition":"<p>Anders dan bij koorts is het setpoint bij <strong>hyperthermie</strong> niet verhoogd, zodat koortsremmers niet helpen. Oorzaken: hitteberoerte, inspanning in de hitte, maligne hyperthermie (na bepaalde anesthetica), het maligne neurolepticasyndroom, serotoninesyndroom en drugs (MDMA, cocaïne). Behandeling: actief koelen.</p>","image_url":"","wiki_title":"Hyperthermia","match":"hyperthermie|oververhitting|hitteberoerte","option_only":true},"inspanningsastma":{"title":"Inspanningsastma","short":"Bij inspanningsastma ontstaat tijdens of kort na inspanning een vernauwing van de luchtwegen, met kortademigheid en piepen.","definition":"<p>Bij <strong>inspanningsgebonden bronchoconstrictie</strong> koelen en drogen de luchtwegen uit door de snelle ademhaling, wat mestcellen activeert. Koude, droge lucht verergert het. Een kortwerkende β2-agonist vóór inspanning en een goede onderhoudsbehandeling van astma voorkomen klachten.</p>","image_url":"","wiki_title":"Exercise-induced bronchoconstriction","match":"inspanningsastma|inspanningsgebonden bronchoconstrictie","option_only":true},"virus induced wheezing":{"title":"Viraal geïnduceerd piepen","short":"Bij jonge kinderen kan een virale luchtweginfectie een piepende ademhaling geven, zonder dat het kind later astma heeft.","definition":"<p>Veel peuters piepen bij een verkoudheid; dit <strong>episodisch viraal piepen</strong> verdwijnt bij de meesten rond de schoolleeftijd. Kinderen die ook tussen infecties door piepen, eczeem hebben of ouders met astma hebben een grotere kans op astma later.</p>","image_url":"","wiki_title":"Wheeze","match":"virus induced wheezing|viraal geïnduceerd piepen|wheezing","option_only":true},"talipes calcaneovalgus":{"title":"Pes calcaneovalgus","short":"Pes calcaneovalgus is een standsafwijking van de voet bij pasgeborenen, waarbij de voetrug tegen het scheenbeen ligt; meestal door de ligging in de baarmoeder.","definition":"<p>De <strong>pes calcaneovalgus</strong> is meestal soepel en verdwijnt vanzelf of met eenvoudige rekoefeningen. Het moet worden onderscheiden van een stugge afwijking (talus verticalis) en een klompvoet (pes equinovarus), die behandeling nodig hebben.</p>","image_url":"","wiki_title":"Calcaneovalgus","match":"talipes calcaneovalgus|pes calcaneovalgus","option_only":true},"talipes equinovarus":{"title":"Klompvoet (pes equinovarus)","short":"Een klompvoet is een aangeboren standsafwijking met de voet in spitsvoetstand, naar binnen gekanteld en gedraaid.","definition":"<p>Bij een <strong>klompvoet</strong> staat de voet in equinus, varus, adductus en cavus. Behandeling volgens Ponseti: wekelijks gipsen, vaak een kleine doorsnijding van de achillespees en daarna jarenlang een spreidbeugel ’s nachts om terugval te voorkomen.</p>","image_url":"","wiki_title":"Clubfoot","match":"talipes equinovarus|pes equinovarus|klompvoet|talipes calcaneovarus|talipes equinovalgus","option_only":true},"talus verticalis":{"title":"Talus verticalis","short":"Bij een talus verticalis staat de talus verticaal en is de voetboog omgekeerd (‘schommelvoet’), een stugge aangeboren afwijking.","definition":"<p>De <strong>congenitale verticale talus</strong> geeft een bolle voetzool. Ze gaat vaak samen met neurologische aandoeningen of syndromen en vraagt meestal om gips en chirurgie.</p>","image_url":"","wiki_title":"Congenital vertical talus","match":"talus verticalis|congenitale verticale talus|tafelpoot","option_only":true},"voedselvergiftiging":{"title":"Voedselvergiftiging (-infectie)","short":"Bij een voedselvergiftiging ontstaan maag-darmklachten door toxines of micro-organismen in voedsel.","definition":"<p>Bij een <strong>voedselintoxicatie</strong> zit het toxine al in het voedsel, met snel (1–6 uur) braken, bijv. door <em>S. aureus</em> of <em>Bacillus cereus</em>. Bij een <strong>voedselinfectie</strong> vermenigvuldigt het micro-organisme zich in de darm, met later (12–72 uur) diarree en koorts, bijv. <em>Salmonella</em> of <em>Campylobacter</em>.</p>","image_url":"","wiki_title":"Foodborne illness","match":"voedselvergiftiging|voedselintoxicatie|voedselinfectie","option_only":true},"purpura fulminans (vasculitis)":{"title":"Purpura fulminans","short":"Purpura fulminans is een snel uitbreidende huidnecrose en bloeding door trombose in kleine vaatjes, meestal bij een meningokokkensepsis en DIS.","definition":"<p><strong>Purpura fulminans</strong> geeft grote, donkere purpura die necrotisch worden. Oorzaken zijn ernstige sepsis (vooral meningokokken) met verbruik van proteïne C, en zeldzamer een aangeboren proteïne C- of S-tekort bij pasgeborenen.</p>","image_url":"","wiki_title":"Purpura fulminans","match":"purpura fulminans (vasculitis)|purpura fulminans","option_only":true},"multicysteuze nierdysplasie beiderzijds":{"title":"Multicysteuze nierdysplasie","short":"Bij multicysteuze nierdysplasie is een nier aangelegd als een tros niet-functionerende cysten, door een stoornis in de ontwikkeling.","definition":"<p>Een <strong>eenzijdige</strong> multicysteuze nierdysplasie is vaak een toevalsbevinding op de prenatale echo; de andere nier neemt de functie over en de cysten verdwijnen vaak spontaan. Een <strong>dubbelzijdige</strong> vorm geeft geen urineproductie, oligohydramnion en longhypoplasie (Potter-sequentie).</p>","image_url":"","wiki_title":"Multicystic dysplastic kidney","match":"multicysteuze nierdysplasie beiderzijds|multicysteuze nierdysplasie","option_only":true},"hemoglobine":{"title":"Hemoglobine","short":"Hemoglobine is het eiwit in rode bloedcellen dat zuurstof bindt en vervoert.","definition":"<p>Volwassen <strong>hemoglobine</strong> (HbA) bestaat uit twee alfa- en twee bètaketens, elk met een heemgroep met ijzer. De zuurstofbinding is coöperatief (S-vormige dissociatiecurve); een lagere pH, hogere CO₂, temperatuur en 2,3-BPG verschuiven de curve naar rechts (makkelijker afgifte). Foetaal Hb (HbF) heeft een hogere affiniteit voor zuurstof.</p>","image_url":"","wiki_title":"Hemoglobin","match":"hemoglobine|hb","option_only":true},"parenchymateuze bloeding":{"title":"Intracerebrale bloeding","short":"Een intracerebrale bloeding is een bloeding in het hersenweefsel zelf, meestal door hypertensie of amyloïdangiopathie.","definition":"<p><strong>Hypertensieve bloedingen</strong> liggen vaak diep (basale kernen, thalamus, pons, cerebellum); <strong>lobaire bloedingen</strong> bij ouderen passen bij amyloïdangiopathie. Andere oorzaken: antistolling, vaatmalformaties en tumoren. Klachten ontstaan plotseling, vaak met hoofdpijn en braken. Diagnose met CT.</p>","image_url":"","wiki_title":"Intracerebral hemorrhage","match":"parenchymateuze bloeding|intracerebrale bloeding|hersenbloeding","option_only":true},"serologie":{"title":"Serologie","short":"Bij serologie wordt in het bloed gezocht naar antistoffen (of antigenen) om een infectie of auto-immuunziekte aan te tonen.","definition":"<p>Bij infecties wijst specifiek <strong>IgM</strong> of een viervoudige stijging van IgG tussen twee monsters op een recente infectie; IgG alleen op een doorgemaakte infectie of vaccinatie. In het begin van een infectie kunnen antistoffen nog ontbreken (vensterperiode).</p>","image_url":"","wiki_title":"Serology","match":"serologie|serologisch onderzoek","option_only":true},"acute nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"acute nierinsufficiëntie","option_only":true},"katalase":{"title":"Catalase","short":"Catalase is een enzym dat waterstofperoxide omzet in water en zuurstof; bacteriën met catalase (zoals stafylokokken) zijn catalasepositief.","definition":"<p><strong>Catalase</strong> breekt <em>waterstofperoxide</em> af: 2 H<sub>2</sub>O<sub>2</sub> → 2 H<sub>2</sub>O + O<sub>2</sub>. In menselijke cellen zit het vooral in de peroxisomen en beschermt het tegen oxidatieve schade.</p><p>In de microbiologie is de catalasetest een snelle manier om grampositieve kokken te onderscheiden: <em>stafylokokken</em> zijn catalasepositief (bruisen met H<sub>2</sub>O<sub>2</sub>), <em>streptokokken</em> catalasenegatief. Catalasepositieve micro-organismen zijn ook beter bestand tegen de oxidatieve burst van fagocyten.</p>","image_url":"","wiki_title":"Catalase","match":"katalase","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"linkerbundeltakblok":{"title":"Linkerbundeltakblok (LBTB)","short":"Bij een linkerbundeltakblok wordt de linkerventrikel vertraagd geactiveerd, met een breed QRS-complex.","definition":"<p>Een nieuw <strong>LBTB</strong> kan wijzen op ischemie of structurele hartziekte (hypertensie, cardiomyopathie, aortastenose). Het bemoeilijkt de beoordeling van ST-veranderingen. Bij hartfalen met een LBTB kan een biventriculaire pacemaker (CRT) helpen.</p>","image_url":"","wiki_title":"Left bundle branch block","match":"linkerbundeltakblok|lbtb|lbbb","option_only":true},"hydrocephalus":{"title":"Hydrocefalus","short":"Bij hydrocefalus hoopt liquor zich op in de ventrikels door een stoornis in productie, doorstroming of resorptie.","definition":"<p>Bij een <strong>obstructieve</strong> hydrocefalus is de doorstroming geblokkeerd (bijv. aquaductstenose, tumor); bij een <strong>communicerende</strong> de resorptie (na bloeding of meningitis). Bij zuigelingen groeit de schedelomtrek snel en is de fontanel bol; bij volwassenen ontstaan hoofdpijn, braken en sufheid. Normaledrukhydrocefalus geeft loopstoornis, incontinentie en dementie.</p>","image_url":"","wiki_title":"Hydrocephalus","match":"hydrocephalus|hydrocefalus|waterhoofd","option_only":true},"respiratoir syncytieelvirus":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"respiratoir syncytieelvirus|rsv|respiratoir syncytieel virus","option_only":true},"influenzavirus type b":{"title":"Influenza B-virus","short":"Influenza B veroorzaakt seizoensgriep, vooral bij kinderen, en kent geen dierlijk reservoir en geen pandemieën.","definition":"<p><strong>Influenza B</strong> verandert alleen via antigene drift en zit in het jaarlijkse griepvaccin. Bij kinderen kan het myositis van de kuiten en (bij aspirinegebruik) het syndroom van Reye geven.</p>","image_url":"","wiki_title":"Influenza B virus","match":"influenzavirus type b|influenza b","option_only":true},"gele koortsvirus":{"title":"Gelekoortsvirus","short":"Het gelekoortsvirus is een flavivirus dat door Aedes-muggen wordt overgebracht; tegen gele koorts bestaat een levend verzwakt vaccin.","definition":"<p>Gele koorts komt voor in tropisch Afrika en Zuid-Amerika. Een deel van de patiënten ontwikkelt na de griepachtige fase leverfalen met icterus, bloedingen en nierfalen. Bij inreis in sommige landen is vaccinatie verplicht.</p>","image_url":"","wiki_title":"Yellow fever virus","match":"gele koortsvirus|gelekoortsvirus|gele koorts","option_only":true},"proteus mirabilis":{"title":"Proteus mirabilis","short":"Proteus mirabilis is een gramnegatieve staaf die urineweginfecties en, via urease, struvietstenen veroorzaakt.","definition":"<p>Het enzym <strong>urease</strong> zet ureum om in ammoniak, waardoor de urine alkalisch wordt en magnesium-ammoniumfosfaatstenen (koraalstenen) ontstaan. Op een kweekplaat ‘zwermt’ de bacterie. Het komt vooral voor bij gecompliceerde urineweginfecties en katheters.</p>","image_url":"","wiki_title":"Proteus mirabilis","match":"proteus mirabilis|proteus","option_only":true},"mycobacterium abscessus":{"title":"Mycobacterium abscessus","short":"Mycobacterium abscessus is een snelgroeiende niet-tuberculeuze mycobacterie die longinfecties (vooral bij CF) en huidinfecties geeft.","definition":"<p><strong>Niet-tuberculeuze mycobacteriën</strong> komen voor in water en bodem en zijn niet van mens op mens besmettelijk (behalve mogelijk bij CF). <em>M. abscessus</em> is van nature resistent tegen veel antibiotica en daardoor moeilijk te behandelen.</p>","image_url":"","wiki_title":"Mycobacterium abscessus","match":"mycobacterium abscessus|niet-tuberculeuze mycobacteriën|atypische mycobacteriën","option_only":true},"bacteriële vaginose":{"title":"Bacteriële vaginose","short":"Bij bacteriële vaginose zijn de lactobacillen in de vagina vervangen door anaerobe bacteriën, met dunne grijze afscheiding en een visgeur.","definition":"<p>De diagnose wordt gesteld met de criteria van Amsel: dunne homogene afscheiding, pH &gt;4,5, positieve amine- (vis)test met KOH en ‘clue cells’. Het is geen klassieke soa. Behandeling met metronidazol; in de zwangerschap is er een verhoogd risico op vroeggeboorte.</p>","image_url":"","wiki_title":"Bacterial vaginosis","match":"bacteriële vaginose|bacteriele vaginose","option_only":true},"streptococcus viridans":{"title":"Viridansstreptokokken","short":"Viridansstreptokokken zijn alfa-hemolytische streptokokken uit de mondflora; ze zijn een belangrijke oorzaak van subacute endocarditis.","definition":"<p>Na tandheelkundige ingrepen kunnen <strong>viridansstreptokokken</strong> in het bloed komen en zich hechten aan beschadigde hartkleppen (endocarditis lenta). <em>S. mutans</em> speelt een rol bij cariës. Ze zijn optochine-resistent, wat ze onderscheidt van pneumokokken.</p>","image_url":"","wiki_title":"Viridans streptococci","match":"streptococcus viridans|viridansstreptokokken|viridans streptokokken","option_only":true},"neuraminidase":{"title":"Neuraminidase","short":"Neuraminidase is een enzym op het oppervlak van het influenzavirus dat nieuwe virusdeeltjes loslaat uit de geïnfecteerde cel.","definition":"<p><strong>Neuraminidase</strong> knipt siaalzuur van het celoppervlak, zodat nieuwe virussen vrijkomen. Oseltamivir en zanamivir remmen het. Samen met hemagglutinine bepaalt het het subtype (bijv. H1N1).</p>","image_url":"","wiki_title":"Viral neuraminidase","match":"neuraminidase","option_only":true},"enveloppe":{"title":"Virale envelop","short":"Een envelop is de lipide-buitenmantel van sommige virussen, afkomstig van de membraan van de gastheercel.","definition":"<p><strong>Omhulde virussen</strong> (bijv. influenza, hiv, herpes, corona) zijn gevoelig voor uitdroging, zeep, alcohol en detergentia en worden meestal via druppels, bloed of direct contact overgedragen. Niet-omhulde virussen (bijv. norovirus, adenovirus) zijn veel stabieler in de omgeving.</p>","image_url":"","wiki_title":"Viral envelope","match":"enveloppe|lipide envelop|envelop","option_only":true},"primaire ciliaire dyskinesie":{"title":"Primaire ciliaire dyskinesie","short":"Bij primaire ciliaire dyskinesie werken de trilharen niet goed, met chronische luchtweginfecties, bronchiëctasieën en onvruchtbaarheid.","definition":"<p><strong>PCD</strong> erft meestal autosomaal recessief over. Klachten beginnen vaak al bij de geboorte (benauwdheid, chronisch loopneus) en omvatten recidiverende otitis en sinusitis. Bij ongeveer de helft is er een situs inversus (syndroom van Kartagener). Mannen zijn vaak onvruchtbaar door onbeweeglijke zaadcellen.</p>","image_url":"","wiki_title":"Primary ciliary dyskinesia","match":"primaire ciliaire dyskinesie|pcd|syndroom van kartagener","option_only":true},"pubertas tarda":{"title":"Pubertas tarda (late puberteit)","short":"Van pubertas tarda spreekt men als de puberteit bij meisjes na 13 jaar en bij jongens na 14 jaar nog niet is begonnen.","definition":"<p>De meest voorkomende oorzaak is een <strong>constitutionele vertraging</strong> van groei en puberteit, vaak familiair, met een achterstand in botleeftijd. Andere oorzaken zijn chronische ziekte, ondervoeding of sport, hypogonadotroop hypogonadisme (bijv. Kallmann) en primair gonadefalen (Turner, Klinefelter).</p>","image_url":"","wiki_title":"Delayed puberty","match":"pubertas tarda|familiar late puberteit|constitutionele vertraging van groei en puberteit","option_only":true},"vacter-l":{"title":"VACTERL-associatie","short":"VACTERL is een combinatie van aangeboren afwijkingen: wervels, anus, hart, trachea-oesofagus, nieren en ledematen.","definition":"<p>Bij de <strong>VACTERL-associatie</strong> zijn minstens drie van de volgende aanwezig: vertebrale afwijkingen, anusatresie, cardiale afwijkingen, tracheo-oesofageale fistel met oesofagusatresie, renale afwijkingen en ledemaatafwijkingen (vooral van de radius). Bij één afwijking wordt naar de andere gezocht.</p>","image_url":"","wiki_title":"VACTERL association","match":"vacter-l|vacterl|vacterl-associatie","option_only":true},"syndroom van crouzon":{"title":"Syndroom van Crouzon","short":"Het syndroom van Crouzon is een erfelijke craniosynostose met vroegtijdige sluiting van schedelnaden, uitpuilende ogen en een onderontwikkeld middengezicht.","definition":"<p><strong>Crouzon</strong> wordt veroorzaakt door een mutatie in FGFR2. Door de craniosynostose kan de intracraniële druk stijgen; de ondiepe oogkassen geven exorbitisme. Behandeling is chirurgisch.</p>","image_url":"","wiki_title":"Crouzon syndrome","match":"syndroom van crouzon|crouzon","option_only":true},"coxsackievirus":{"title":"Coxsackievirussen","short":"Coxsackievirussen zijn enterovirussen; type A geeft vooral hand-voet-mondziekte en herpangina, type B o.a. myocarditis en pleurodynie.","definition":"<p><strong>Coxsackievirussen</strong> worden fecaal-oraal en via druppels overgedragen, met een piek in zomer en najaar. Meestal verlopen infecties mild, maar ze kunnen ook virale meningitis en bij pasgeborenen ernstige systemische infecties veroorzaken.</p>","image_url":"","wiki_title":"Coxsackievirus","match":"coxsackievirus|coxsackie","option_only":true},"tricuspidalisinsufficiëntie":{"title":"Tricuspidalisinsufficiëntie","short":"Bij tricuspidalisinsufficiëntie lekt bloed in de systole terug van de rechterventrikel naar het rechteratrium.","definition":"<p><strong>Tricuspidalisinsufficiëntie</strong> is meestal secundair aan verwijding van de rechterventrikel (pulmonale hypertensie, linkszijdig hartfalen); primaire oorzaken zijn endocarditis (drugsgebruik) en het carcinoïdsyndroom. Er ontstaan gestuwde halsvenen met grote v-golven, een pulserende lever, oedeem en ascites.</p>","image_url":"","wiki_title":"Tricuspid insufficiency","match":"tricuspidalisinsufficiëntie","option_only":true},"pancreasinsufficiëntie":{"title":"Exocriene pancreasinsufficiëntie","short":"Bij exocriene pancreasinsufficiëntie maakt de pancreas te weinig verteringsenzymen, met vetdiarree en gewichtsverlies.","definition":"<p>Oorzaken zijn chronische pancreatitis, cystische fibrose, pancreascarcinoom en pancreasresectie. Kenmerken: steatorroe (vette, stinkende, drijvende ontlasting), gewichtsverlies en tekorten aan vetoplosbare vitamines. Diagnose o.a. met fecaal elastase; behandeling met pancreasenzymen bij de maaltijd.</p>","image_url":"","wiki_title":"Exocrine pancreatic insufficiency","match":"pancreasinsufficiëntie|exocriene pancreasinsufficiëntie","option_only":true},"vitamine b2":{"title":"Vitamine B2 (riboflavine)","short":"Riboflavine is de bouwsteen van FAD en FMN, co-enzymen in redoxreacties zoals in de citroenzuurcyclus en ademhalingsketen.","definition":"<p>Een tekort aan <strong>riboflavine</strong> is zeldzaam en geeft ontsteking van mondhoeken (cheilitis angularis), lippen en tong en seborroïsch eczeem. Hoge doses worden soms als profylaxe bij migraine gebruikt.</p>","image_url":"","wiki_title":"Riboflavin","match":"vitamine b2|riboflavine","option_only":true},"glandula parotis (oorspeekselklier)":{"title":"Glandula parotidea (oorspeekselklier)","short":"De glandula parotidea is de grootste speekselklier, vóór het oor; door de klier loopt de n. facialis.","definition":"<p>De <strong>parotis</strong> maakt sereus speeksel dat via de ductus van Stenon tegenover de tweede bovenmolaar in de mond komt. Ze wordt parasympathisch geïnnerveerd via de n. glossopharyngeus. Zwelling komt voor bij bof, speekselstenen, Sjögren en tumoren (meestal het goedaardige pleomorf adenoom); bij een parotidectomie moet de n. facialis gespaard worden.</p>","image_url":"","wiki_title":"Parotid gland","match":"glandula parotis (oorspeekselklier)|glandula parotidea|oorspeekselklier|parotis","option_only":true},"overactieve blaas":{"title":"Overactieve blaas","short":"Bij een overactieve blaas is er een plotselinge, sterke aandrang tot plassen, vaak met frequent plassen en soms urine-incontinentie.","definition":"<p>De <strong>overactieve blaas</strong> komt veel voor bij ouderen. Behandeling bestaat uit blaastraining en bekkenbodemoefeningen, eventueel anticholinergica of een β3-agonist (mirabegron). Infectie, stenen en een blaastumor moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Overactive bladder","match":"overactieve blaas|urge-incontinentie|aandrangincontinentie","option_only":true},"blaasruptuur":{"title":"Blaasruptuur","short":"Een blaasruptuur is een scheur in de blaas, meestal door een bekkenfractuur of een stomp trauma bij een volle blaas.","definition":"<p>Een <strong>extraperitoneale</strong> blaasruptuur (vaak bij bekkenfracturen) wordt meestal met een katheter behandeld; een <strong>intraperitoneale</strong> ruptuur (klap op een volle blaas, bijv. na alcohol) vraagt operatief herstel. Klachten: hematurie, buikpijn en niet kunnen plassen.</p>","image_url":"","wiki_title":"Bladder rupture","match":"blaasruptuur","option_only":true},"leverruptuur":{"title":"Leverletsel","short":"Een leverruptuur is een scheur in de lever, meestal na een stomp buiktrauma rechts, met risico op een groot inwendig bloedverlies.","definition":"<p>De lever is een van de meest aangedane organen bij een stomp buiktrauma. Hemodynamisch stabiele patiënten worden vaak conservatief behandeld of met embolisatie; instabiele patiënten worden geopereerd.</p>","image_url":"","wiki_title":"Liver injury","match":"leverruptuur|leverletsel|leverlaceratie","option_only":true},"retractiele testis":{"title":"Retractiele testis","short":"Een retractiele testis wordt door de cremasterreflex omhoog getrokken, maar kan zonder spanning in het scrotum worden gebracht.","definition":"<p>Een <strong>retractiele testis</strong> (pendeltestis) is meestal onschuldig, maar moet worden gevolgd, omdat hij later toch kan ‘opstijgen’. Een echt niet-ingedaalde testis (cryptorchisme) wordt rond het eerste levensjaar operatief ingedaald (orchidopexie), vanwege vruchtbaarheid en een verhoogd risico op testiskanker.</p>","image_url":"","wiki_title":"Retractile testis","match":"retractiele testis|pendeltestis","option_only":true},"varicocele":{"title":"Varicocele","short":"Een varicocele is een spataderachtige verwijding van de plexus pampiniformis in het scrotum, vooral links.","definition":"<p>Een <strong>varicocele</strong> voelt als ‘een zak met wormen’, wordt groter bij staan en persen en kleiner bij liggen. Ze komt vooral links voor door de haakse uitmonding van de v. testicularis in de v. renalis. Een plots ontstane of rechtszijdige varicocele kan wijzen op een tumor die de venen drukt.</p>","image_url":"","wiki_title":"Varicocele","match":"varicocele","option_only":true},"koemelkeiwit":{"title":"Koemelkeiwitallergie","short":"Koemelkeiwitallergie is een allergische reactie op eiwitten uit koemelk, vooral bij zuigelingen.","definition":"<p>Koemelkallergie kan IgE-gemedieerd zijn (snelle reacties: urticaria, braken, zelden anafylaxie) of niet-IgE-gemedieerd (eczeem, darmklachten, bloed bij de ontlasting). Behandeling met een volledig gehydrolyseerde of aminozuurvoeding; de meeste kinderen groeien er vóór de schoolleeftijd overheen.</p>","image_url":"","wiki_title":"Milk allergy","match":"koemelkeiwit|koemelkallergie|koemelkeiwitallergie|allergie voor kunstvoeding","option_only":true},"graspollen":{"title":"Graspollen","short":"Graspollen zijn de belangrijkste oorzaak van hooikoorts in mei tot en met juli.","definition":"<p>Bij een allergie voor <strong>graspollen</strong> ontstaan niezen, loopneus, jeukende en tranende ogen en soms astma in het graspollenseizoen. Behandeling met antihistaminica, neusspray met corticosteroïden en eventueel immunotherapie.</p>","image_url":"","wiki_title":"Pollen","match":"graspollen","option_only":true},"claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"claudicatio intermittens|etalagebenen|perifeer arterieel vaatlijden","option_only":true},"allergische conjunctivitis":{"title":"Allergische conjunctivitis","short":"Allergische conjunctivitis is een allergische ontsteking van het bindvlies, met jeukende, tranende en rode ogen aan beide kanten.","definition":"<p>De <strong>allergische conjunctivitis</strong> is vaak seizoensgebonden (pollen) of het hele jaar door (huisstofmijt, huisdieren), meestal samen met allergische rhinitis. Jeuk is het belangrijkste onderscheid met infectieuze conjunctivitis. Behandeling met antihistaminica of mestcelstabiliserende oogdruppels.</p>","image_url":"","wiki_title":"Allergic conjunctivitis","match":"allergische conjunctivitis|jeukende en tranende ogen|jeuk in de ogen","option_only":true},"neuspoliep":{"title":"Neuspoliepen","short":"Neuspoliepen zijn goedaardige, druppelvormige zwellingen van het slijmvlies van neus en bijholten, met een verstopte neus en reukverlies.","definition":"<p><strong>Neuspoliepen</strong> horen bij chronische rhinosinusitis, vaak met astma en soms met overgevoeligheid voor aspirine (triade van Samter/Widal). Bij kinderen moet aan cystische fibrose worden gedacht. Behandeling met corticosteroïdneusspray, kortdurend orale steroïden of chirurgie.</p>","image_url":"","wiki_title":"Nasal polyp","match":"neuspoliep|neuspoliepen","option_only":true},"rachitis (= rickets)":{"title":"Rachitis (Engelse ziekte)","short":"Rachitis is een stoornis in de mineralisatie van groeiend bot bij kinderen, meestal door vitamine D-tekort.","definition":"<p>Kenmerken van <strong>rachitis</strong> zijn O-benen, verbrede polsen, een ‘rozenkrans’ aan de ribben, een uitgesteld sluiten van de fontanel en groeiachterstand. Het alkalisch fosfatase is verhoogd. Risico bij een donkere huid, weinig zonlicht en volledige borstvoeding zonder vitamine D-suppletie. Bij volwassenen heet het osteomalacie.</p>","image_url":"","wiki_title":"Rickets","match":"rachitis (= rickets)|rachitis|rickets|engelse ziekte","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"turner":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"turner","option_only":true},"aortastenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortastenose","option_only":true},"aorta insufficiëntie":{"title":"Aortaklepinsufficiëntie","short":"Bij aortaklepinsufficiëntie sluit de aortaklep niet goed, waardoor bloed in de diastole terugstroomt naar de linkerventrikel.","definition":"<p>Bij <strong>aortaklepinsufficiëntie</strong> ontstaat volumebelasting van de linkerventrikel, die verwijdt. Oorzaken zijn o.a. een bicuspide klep, endocarditis, verwijding van de aortawortel (hypertensie, Marfan, dissectie). Kenmerkend zijn een diastolisch decrescendo-geruis langs de linker sternumrand en een grote polsdruk (snel stijgende en dalende pols).</p>","image_url":"","wiki_title":"Aortic insufficiency","match":"aorta insufficiëntie","option_only":true},"mitralis insufficiëntie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralis insufficiëntie","option_only":true},"mitralisklepinsufficientie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralisklepinsufficientie","option_only":true},"lekkende mitralisklep":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"lekkende mitralisklep","option_only":true},"hemophilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"hemophilus influenzae","option_only":true},"haemophilus influenza":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza","option_only":true},"bordetella pertussis (kinkhoest)":{"title":"Kinkhoest (pertussis)","short":"Kinkhoest is een luchtweginfectie door Bordetella pertussis met langdurige hoestbuien en een gierende inademing; gevaarlijk voor zuigelingen.","definition":"<p><strong>Kinkhoest</strong> (pertussis) wordt veroorzaakt door de gramnegatieve bacterie <em>Bordetella pertussis</em>, die zich hecht aan het trilhaarepitheel en toxines produceert.</p><p>Na een verkoudheidsfase volgen weken met heftige hoestbuien, vaak eindigend in een gierende inademing (‘kink’) of braken. Bij jonge zuigelingen kan kinkhoest apneus en overlijden veroorzaken; daarom wordt gevaccineerd (ook zwangeren, om de baby te beschermen).</p>","image_url":"","wiki_title":"Whooping cough","match":"bordetella pertussis (kinkhoest)","option_only":true},"corynebacterium diphtheriae (difterie)":{"title":"Difterie","short":"Difterie is een infectie door Corynebacterium diphtheriae waarbij een toxine een grijs pseudomembraan in de keel en schade aan hart en zenuwen veroorzaakt.","definition":"<p><strong>Difterie</strong> wordt veroorzaakt door toxineproducerende stammen van <em>Corynebacterium diphtheriae</em>, een grampositieve staaf. Het difterietoxine remt de eiwitsynthese van gastheercellen.</p><p>Lokaal ontstaat een grijswit, vastzittend <em>pseudomembraan</em> in keel en neus, met risico op luchtwegobstructie. Het toxine kan systemisch myocarditis en neuropathie geven. Door vaccinatie (DKTP) is het in Nederland zeldzaam.</p>","image_url":"","wiki_title":"Diphtheria","match":"corynebacterium diphtheriae (difterie)","option_only":true},"hernia inguinalis (liesbreuk)":{"title":"Liesbreuk (hernia inguinalis)","short":"Een liesbreuk is een uitstulping van buikvlies (met eventueel darm) via het lieskanaal of de achterwand ervan.","definition":"<p>Een <strong>indirecte</strong> liesbreuk volgt het lieskanaal vanaf de inwendige liesring, lateraal van de vasa epigastrica inferiora (vaak door een open processus vaginalis). Een <strong>directe</strong> liesbreuk puilt mediaal van deze vaten uit door een zwakke achterwand. Liesbreuken komen vooral bij mannen voor; beklemming is een spoedgeval.</p>","image_url":"","wiki_title":"Inguinal hernia","match":"hernia inguinalis (liesbreuk)","option_only":true},"mononucleosis infectiosa (m. pfeiffer)":{"title":"Ziekte van Pfeiffer","short":"De ziekte van Pfeiffer (mononucleosis infectiosa) is een infectie met het Epstein-Barrvirus met keelpijn, koorts, lymfeklierzwelling en moeheid.","definition":"<p>De <strong>ziekte van Pfeiffer</strong> treft vooral adolescenten en jongvolwassenen. Het bloedbeeld toont atypische lymfocyten. Een complicatie is een miltruptuur, waardoor contactsport enkele weken wordt afgeraden. Bij gebruik van amoxicilline ontstaat vaak een huiduitslag. De moeheid kan weken tot maanden aanhouden.</p>","image_url":"","wiki_title":"Infectious mononucleosis","match":"mononucleosis infectiosa (m. pfeiffer)","option_only":true},"humaan parvovirus type b19":{"title":"Erythema infectiosum (vijfde ziekte)","short":"Erythema infectiosum is een kinderziekte door parvovirus B19 met felrode ‘slapwangen’ en daarna een kantachtige uitslag.","definition":"<p>Parvovirus B19 infecteert erytroïde voorlopercellen. Bij mensen met chronische hemolyse kan het een aplastische crise geven, en in de zwangerschap foetale anemie en hydrops. Bij volwassenen geeft het vaak symmetrische gewrichtsklachten.</p>","image_url":"","wiki_title":"Erythema infectiosum","match":"humaan parvovirus type b19","option_only":true},"humaan herpesvirus type 6":{"title":"Zesde ziekte (exanthema subitum)","short":"De zesde ziekte is een infectie met humaan herpesvirus 6 bij jonge kinderen: eerst enkele dagen hoge koorts, daarna, als de koorts zakt, een vlekjesuitslag.","definition":"<p><strong>Exanthema subitum</strong> treft vooral kinderen van 6 maanden tot 2 jaar. Kenmerkend is dat de huiduitslag pas verschijnt nadat de koorts is verdwenen. Koortsconvulsies kunnen optreden. Het verloopt meestal onschuldig.</p>","image_url":"","wiki_title":"Roseola","match":"humaan herpesvirus type 6","option_only":true},"syndroom van digeorge":{"title":"22q11-deletiesyndroom","short":"Het 22q11-deletiesyndroom ontstaat door een microdeletie op chromosoom 22 en geeft o.a. hartafwijkingen, een gehemeltespleet, hypocalciëmie en immuunstoornissen.","definition":"<p>Bij het <strong>22q11-deletiesyndroom</strong> (DiGeorge) is de ontwikkeling van de derde en vierde kieuwzakjes verstoord. Kenmerken (‘CATCH-22’): hartafwijkingen (vooral conotruncaal, zoals Fallot en truncus arteriosus), afwijkend gezicht, hypoplasie van de thymus (T-celtekort), gehemeltespleet en hypocalciëmie door hypoplastische bijschildklieren. Op latere leeftijd is er een verhoogd risico op psychose.</p>","image_url":"","wiki_title":"DiGeorge syndrome","match":"syndroom van digeorge","option_only":true},"pes equinovalgus":{"title":"Klompvoet (pes equinovarus)","short":"Een klompvoet is een aangeboren standsafwijking met de voet in spitsvoetstand, naar binnen gekanteld en gedraaid.","definition":"<p>Bij een <strong>klompvoet</strong> staat de voet in equinus, varus, adductus en cavus. Behandeling volgens Ponseti: wekelijks gipsen, vaak een kleine doorsnijding van de achillespees en daarna jarenlang een spreidbeugel ’s nachts om terugval te voorkomen.</p>","image_url":"","wiki_title":"Clubfoot","match":"pes equinovalgus","option_only":true},"pes calcaneovarus":{"title":"Klompvoet (pes equinovarus)","short":"Een klompvoet is een aangeboren standsafwijking met de voet in spitsvoetstand, naar binnen gekanteld en gedraaid.","definition":"<p>Bij een <strong>klompvoet</strong> staat de voet in equinus, varus, adductus en cavus. Behandeling volgens Ponseti: wekelijks gipsen, vaak een kleine doorsnijding van de achillespees en daarna jarenlang een spreidbeugel ’s nachts om terugval te voorkomen.</p>","image_url":"","wiki_title":"Clubfoot","match":"pes calcaneovarus","option_only":true},"pes calcaneovalgus":{"title":"Pes calcaneovalgus","short":"Pes calcaneovalgus is een standsafwijking van de voet bij pasgeborenen, waarbij de voetrug tegen het scheenbeen ligt; meestal door de ligging in de baarmoeder.","definition":"<p>De <strong>pes calcaneovalgus</strong> is meestal soepel en verdwijnt vanzelf of met eenvoudige rekoefeningen. Het moet worden onderscheiden van een stugge afwijking (talus verticalis) en een klompvoet (pes equinovarus), die behandeling nodig hebben.</p>","image_url":"","wiki_title":"Calcaneovalgus","match":"pes calcaneovalgus","option_only":true},"spierdystrofie":{"title":"Spierdystrofie van Duchenne","short":"De spierdystrofie van Duchenne is een X-gebonden ziekte bij jongens door afwezigheid van dystrofine, met progressieve spierzwakte vanaf de vroege kindertijd.","definition":"<p>Jongens met <strong>Duchenne</strong> beginnen laat met lopen, vallen vaak en staan op via het teken van Gowers. Er is pseudohypertrofie van de kuiten en een sterk verhoogd CK. Ze verliezen meestal rond de twaalf jaar het loopvermogen; cardiomyopathie en ademhalingsproblemen bepalen de prognose.</p>","image_url":"","wiki_title":"Duchenne muscular dystrophy","match":"spierdystrofie","option_only":true},"chronische sinusitis":{"title":"Sinusitis (bijholteontsteking)","short":"Sinusitis is een ontsteking van het slijmvlies van neus en bijholten, met verstopte neus, pijn in het gezicht en afscheiding.","definition":"<p>Acute <strong>rhinosinusitis</strong> ontstaat meestal na een virale verkoudheid; soms volgt een bacteriële infectie (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Klachten zijn een verstopte neus, (purulente) afscheiding, pijn of drukgevoel boven de bijholten en verminderde reuk. Meestal herstelt het binnen enkele weken zonder antibiotica. Chronische sinusitis duurt langer dan 12 weken.</p>","image_url":"","wiki_title":"Sinusitis","match":"chronische sinusitis","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"bronchoconstrictie door inspanning":{"title":"Inspanningsastma","short":"Bij inspanningsastma ontstaat tijdens of kort na inspanning een vernauwing van de luchtwegen, met kortademigheid en piepen.","definition":"<p>Bij <strong>inspanningsgebonden bronchoconstrictie</strong> koelen en drogen de luchtwegen uit door de snelle ademhaling, wat mestcellen activeert. Koude, droge lucht verergert het. Een kortwerkende β2-agonist vóór inspanning en een goede onderhoudsbehandeling van astma voorkomen klachten.</p>","image_url":"","wiki_title":"Exercise-induced bronchoconstriction","match":"bronchoconstrictie door inspanning","option_only":true},"rotavirus infectie":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirus infectie","option_only":true},"rhinovirusinfectie":{"title":"Rhinovirus","short":"Rhinovirussen zijn de belangrijkste verwekkers van de gewone verkoudheid.","definition":"<p><strong>Rhinovirussen</strong> zijn kleine, niet-omhulde RNA-virussen (picornavirussen) met meer dan 100 serotypes, waardoor je er steeds opnieuw verkouden van kunt worden. Ze vermenigvuldigen zich het best bij de iets lagere temperatuur in de neus. Ze kunnen ook astma- en COPD-exacerbaties uitlokken.</p>","image_url":"","wiki_title":"Rhinovirus","match":"rhinovirusinfectie","option_only":true},"rs-virus":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"rs-virus","option_only":true},"psychogene polidipsie":{"title":"Polydipsie","short":"Polydipsie is overmatige dorst en vochtinname.","definition":"<p><strong>Polydipsie</strong> gaat vaak samen met polyurie. Oorzaken zijn o.a. diabetes mellitus (osmotische diurese), diabetes insipidus (centraal of nefrogeen), hypercalciëmie, diuretica en primaire (psychogene) polydipsie. Een dorstproef kan helpen deze oorzaken te onderscheiden.</p>","image_url":"","wiki_title":"Polydipsia","match":"psychogene polidipsie","option_only":true},"q-koorts (coxiella burnetii)":{"title":"Q-koorts (Coxiella burnetii)","short":"Q-koorts is een zoönose door Coxiella burnetii, verspreid via stof van besmette geiten en schapen.","definition":"<p><strong>Q-koorts</strong> geeft vaak een griepachtig beeld, pneumonie of hepatitis; chronische Q-koorts kan endocarditis en vaatinfecties geven, vooral bij klepafwijkingen of vaatprothesen. In 2007–2010 was er in Nederland een grote epidemie rond geitenhouderijen. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Q fever","match":"q-koorts (coxiella burnetii)|q-koorts|coxiella burnetii","option_only":true},"psittacose":{"title":"Psittacose","short":"Psittacose is een longontsteking door Chlamydia psittaci, opgelopen via (stof van) besmette vogels.","definition":"<p>Bij <strong>psittacose</strong> zijn er hoge koorts, hoofdpijn, droge hoest en spierpijn, soms met een relatief trage pols. Contact met vogels (papegaaien, duiven) is de belangrijkste aanwijzing. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Psittacosis","match":"psittacose|papegaaienziekte|ornithose","option_only":true},"fysiotherapeut":{"title":"Fysiotherapeut","short":"Een fysiotherapeut behandelt klachten van het bewegingsapparaat en helpt mensen beter te bewegen, met oefentherapie, advies en manuele technieken.","definition":"<p><strong>Fysiotherapie</strong> wordt o.a. ingezet bij rug- en nekklachten, na operaties en blessures, bij artrose, COPD en na een beroerte. Het is direct toegankelijk, zonder verwijzing van de huisarts.</p>","image_url":"","wiki_title":"Physical therapy","match":"fysiotherapeut|fysiotherapie","option_only":true},"bloedgas":{"title":"Bloedgas","short":"Een arterieel bloedgas meet pH, pCO₂, pO₂, bicarbonaat en vaak lactaat en elektrolyten, om ademhaling en zuur-base-evenwicht te beoordelen.","definition":"<p>Bij het interpreteren van een <strong>bloedgas</strong> bepaal je eerst of er een acidose of alkalose is, daarna of de oorzaak respiratoir (pCO₂) of metabool (bicarbonaat, base excess) is, en of er compensatie is. De pO₂ (in relatie tot de toegediende zuurstof) en de A-a-gradiënt zeggen iets over de gaswisseling.</p>","image_url":"","wiki_title":"Arterial blood gas test","match":"bloedgas|arterieel bloedgas|astrup","option_only":true},"nucleïnezuur":{"title":"Nucleïnezuren","short":"Nucleïnezuren (DNA en RNA) zijn ketens van nucleotiden die erfelijke informatie opslaan en overbrengen.","definition":"<p>Een nucleotide bestaat uit een suiker (deoxyribose of ribose), een fosfaatgroep en een base (A, G, C en T of U). DNA is dubbelstrengs met basenparing A-T en G-C; RNA is meestal enkelstrengs en gebruikt uracil in plaats van thymine.</p>","image_url":"","wiki_title":"Nucleic acid","match":"nucleïnezuur|nucleïnezuren","option_only":true},"transductie":{"title":"Transductie","short":"Transductie is de overdracht van bacterieel DNA van de ene bacterie naar de andere via een bacteriofaag.","definition":"<p>Bij <strong>transductie</strong> neemt een virus van bacteriën bij het verpakken per ongeluk een stukje bacterieel DNA mee. Andere manieren van horizontale genoverdracht zijn transformatie (opname van vrij DNA) en conjugatie (via een pilus). Zo verspreiden zich o.a. resistentie- en toxinegenen.</p>","image_url":"","wiki_title":"Transduction (genetics)","match":"transductie","option_only":true},"thromboflebitis":{"title":"Tromboflebitis","short":"Bij tromboflebitis is een oppervlakkige ader ontstoken met een stolsel, met een pijnlijke, rode, harde streng onder de huid.","definition":"<p>Een <strong>oppervlakkige tromboflebitis</strong> komt voor bij varices, na een infuus en bij hypercoagulabiliteit. Bij uitbreiding tot vlak bij de liesovergang of bij een recidiverend migrerend beeld (soms bij kanker) is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Thrombophlebitis","match":"thromboflebitis|tromboflebitis|oppervlakkige tromboflebitis","option_only":true},"compartimentsyndroom":{"title":"Compartimentsyndroom","short":"Bij een compartimentsyndroom stijgt de druk in een spierloge zo hoog dat de doorbloeding van spieren en zenuwen in gevaar komt.","definition":"<p>Een acuut <strong>compartimentsyndroom</strong> ontstaat vooral na fracturen van het onderbeen of de onderarm, crushletsel of een te strak gips. Het belangrijkste teken is pijn die buiten proportie is, verergerend bij passief rekken van de spieren. Het is een spoedgeval: fasciotomie.</p>","image_url":"","wiki_title":"Compartment syndrome","match":"compartimentsyndroom","option_only":true},"hypospadie":{"title":"Hypospadie","short":"Bij hypospadie mondt de urethra aan de onderkant van de penis uit in plaats van op de top.","definition":"<p><strong>Hypospadie</strong> gaat vaak samen met een kromstand van de penis en een onvolledige voorhuid aan de onderzijde. Besnijdenis wordt uitgesteld, omdat de voorhuid nodig kan zijn voor de correctie, die meestal in het eerste levensjaar wordt gedaan.</p>","image_url":"","wiki_title":"Hypospadias","match":"hypospadie","option_only":true},"bacteriële laryngotracheitis":{"title":"Bacteriële tracheïtis","short":"Bacteriële tracheïtis is een ernstige infectie van de trachea, vaak na een virale pseudokroep, met hoge koorts en dik pus in de luchtweg.","definition":"<p>Kinderen met <strong>bacteriële tracheïtis</strong> zijn ernstig ziek en reageren niet op de behandeling voor pseudokroep. Verwekkers zijn vaak <em>S. aureus</em> en streptokokken. Er kan een luchtwegobstructie ontstaan die intubatie vereist.</p>","image_url":"","wiki_title":"Bacterial tracheitis","match":"bacteriële laryngotracheitis|bacteriële tracheïtis","option_only":true},"inhalatiesteroïd":{"title":"Inhalatiecorticosteroïd (ICS)","short":"Inhalatiecorticosteroïden remmen de ontsteking in de luchtwegen; ze zijn de basis van de onderhoudsbehandeling van astma.","definition":"<p><strong>ICS</strong> verminderen ontsteking, hyperreactiviteit en aanvallen. Lokale bijwerkingen zijn heesheid en spruw (mond spoelen na gebruik). Bij COPD worden ze vooral gegeven bij frequente exacerbaties en eosinofilie, omdat ze het pneumonierisico verhogen.</p>","image_url":"","wiki_title":"Inhaled corticosteroid","match":"inhalatiesteroïd|inhalatiecorticosteroïd|ics|budesonide|fluticason|beclometason","option_only":true},"leukotrieenreceptorantagonist":{"title":"Leukotrieenreceptorantagonist (montelukast)","short":"Montelukast blokkeert de receptor voor cysteinyl-leukotriënen en wordt als aanvullend middel bij astma gebruikt.","definition":"<p><strong>Montelukast</strong> is een tablet, wat handig is bij jonge kinderen en inspanningsastma. Het is minder effectief dan inhalatiecorticosteroïden. Een bekende bijwerking zijn stemmings- en gedragsveranderingen en nachtmerries.</p>","image_url":"","wiki_title":"Montelukast","match":"leukotrieenreceptorantagonist|montelukast","option_only":true},"anticholinergicum":{"title":"Anticholinergicum (luchtwegen)","short":"Inhalatie-anticholinergica (ipratropium, tiotropium) blokkeren muscarinereceptoren in de luchtwegen en geven bronchodilatatie.","definition":"<p>Langwerkende <strong>anticholinergica</strong> (LAMA, bijv. tiotropium) zijn een basismiddel bij COPD; kortwerkend ipratropium wordt bij exacerbaties gebruikt. Bijwerkingen: droge mond en zelden urineretentie of glaucoom.</p>","image_url":"","wiki_title":"Anticholinergic","match":"anticholinergicum|ipratropium|tiotropium|lama|parasympathicolyticum","option_only":true},"coagulase-negatieve stafylokokken":{"title":"Coagulase-negatieve stafylokokken","short":"Coagulase-negatieve stafylokokken (o.a. S. epidermidis) horen bij de huidflora en veroorzaken vooral infecties van lijnen en prothesen.","definition":"<p><strong>CNS</strong> zijn weinig virulent maar kunnen biofilms vormen op kunststof. In een bloedkweek zijn ze vaak een verontreiniging; meerdere positieve kweken bij een patiënt met een lijn of kunstklep wijzen op een echte infectie. <em>S. saprophyticus</em> geeft urineweginfecties bij jonge vrouwen.</p>","image_url":"","wiki_title":"Coagulase-negative staphylococci","match":"coagulase-negatieve stafylokokken|cns","option_only":true},"schaamluis":{"title":"Schaamluis","short":"De schaamluis is een luis die vooral in het schaamhaar leeft en via seksueel contact wordt overgedragen.","definition":"<p>Bij <strong>schaamluis</strong> is er jeuk in het schaamgebied en zijn luizen en neten op de haren te zien, soms ook in wimpers of okselhaar. Behandeling met permetrine of malathion, inclusief partners; onderzoek naar andere soa's is aan te raden.</p>","image_url":"","wiki_title":"Pubic lice","match":"schaamluis|phthirus pubis|platjes","option_only":true},"immuunglobulinepreparaat":{"title":"Immunoglobulinepreparaat","short":"Een immunoglobulinepreparaat bevat antistoffen uit donorplasma en geeft directe, maar tijdelijke bescherming (passieve immunisatie).","definition":"<p>Specifieke <strong>immunoglobulinen</strong> worden gegeven na blootstelling aan bijv. hepatitis B (aan pasgeborenen van draagsters), rabiës, tetanus en varicella (bij risicogroepen). Breed IgG wordt gebruikt bij antistofdeficiënties en als immuunmodulatie.</p>","image_url":"","wiki_title":"Immunoglobulin therapy","match":"immuunglobulinepreparaat|immunoglobuline|passieve immunisatie","option_only":true},"ribavirine":{"title":"Ribavirine","short":"Ribavirine is een breed antiviraal middel (nucleosideanaloog), vroeger veel gebruikt bij hepatitis C en soms bij ernstige RSV en Lassakoorts.","definition":"<p><strong>Ribavirine</strong> remt de vermenigvuldiging van RNA-virussen. Belangrijke bijwerkingen zijn hemolytische anemie en teratogeniteit. Bij hepatitis C is het grotendeels vervangen door direct werkende antivirale middelen.</p>","image_url":"","wiki_title":"Ribavirin","match":"ribavirine|ribavirin","option_only":true},"siaalzuurreceptor":{"title":"Siaalzuur (influenzareceptor)","short":"Siaalzuur op het oppervlak van luchtwegcellen is de receptor waaraan het hemagglutinine van influenzavirussen bindt.","definition":"<p>Menselijke influenzavirussen binden vooral aan α-2,6-gebonden <strong>siaalzuur</strong> in de bovenste luchtwegen, vogelgriepvirussen aan α-2,3-siaalzuur, dat dieper in de long voorkomt. Neuraminidase knipt siaalzuur weg om nieuwe virussen vrij te laten.</p>","image_url":"","wiki_title":"Sialic acid","match":"siaalzuurreceptor|siaalzuur","option_only":true},"permissief":{"title":"Opvoedingsstijlen","short":"Opvoedingsstijlen worden ingedeeld op twee assen: warmte/betrokkenheid en controle/structuur.","definition":"<p>Volgens Baumrind en Maccoby combineert een <strong>autoritatieve</strong> stijl warmte met duidelijke regels (gunstigste uitkomst); een <strong>autoritaire</strong> stijl veel controle met weinig warmte; een <strong>permissieve</strong> stijl veel warmte met weinig regels; en een <strong>verwaarlozende</strong> stijl weinig van beide.</p>","image_url":"","wiki_title":"Parenting styles","match":"permissief|autoritatief|autoritair|verwaarlozend","option_only":true},"asystolie":{"title":"Asystolie","short":"Asystolie is het ontbreken van elektrische activiteit van het hart: een ‘vlakke lijn’ en een circulatiestilstand.","definition":"<p><strong>Asystolie</strong> is een niet-schokbaar ritme. Behandeling: reanimatie, adrenaline en het zoeken naar behandelbare oorzaken (de 4 H's en 4 T's, zoals hypoxie, hypovolemie, hyperkaliëmie, tamponnade, trombose). De prognose is slecht.</p>","image_url":"","wiki_title":"Asystole","match":"asystolie","option_only":true},"polsloze elektrische activiteit":{"title":"Polsloze elektrische activiteit (PEA)","short":"Bij PEA is er elektrische activiteit op de monitor, maar geen voelbare pols: een circulatiestilstand.","definition":"<p><strong>PEA</strong> is een niet-schokbaar ritme. Het ontstaat vaak door een behandelbare oorzaak: hypovolemie, hypoxie, spanningspneumothorax, harttamponnade, longembolie, elektrolytstoornissen of intoxicaties. Behandeling: reanimatie, adrenaline en het opheffen van de oorzaak.</p>","image_url":"","wiki_title":"Pulseless electrical activity","match":"polsloze elektrische activiteit|pea","option_only":true},"ventrikeltachycardie":{"title":"Ventrikeltachycardie (VT)","short":"Een ventrikeltachycardie is een snel ritme uit de kamers, met brede QRS-complexen; ze kan overgaan in ventrikelfibrilleren.","definition":"<p><strong>VT</strong> ontstaat vaak in een litteken na een infarct of bij cardiomyopathie. Een polsloze VT wordt behandeld als circulatiestilstand (defibrilleren). Bij een stabiele patiënt: medicatie (amiodaron) of elektrische cardioversie. Bij een breedcomplextachycardie moet altijd aan VT worden gedacht.</p>","image_url":"","wiki_title":"Ventricular tachycardia","match":"ventrikeltachycardie|vt","option_only":true},"mictiecystogram":{"title":"Mictiecysto-urethrogram (MCUG)","short":"Bij een MCUG wordt contrast in de blaas gebracht en tijdens het plassen gefotografeerd, om vesico-ureterale reflux en urethraafwijkingen aan te tonen.","definition":"<p>Het <strong>MCUG</strong> wordt vooral bij kinderen gebruikt na recidiverende of gecompliceerde urineweginfecties of bij afwijkingen op de echo, bijv. om reflux of urethrakleppen bij jongens aan te tonen.</p>","image_url":"","wiki_title":"Voiding cystourethrography","match":"mictiecystogram|standaard mictiecysto-urethrogram (mcug)|mcug","option_only":true},"dmsa-scan":{"title":"DMSA-scan","short":"Een DMSA-scan is een nucleair onderzoek dat littekens en de verdeling van de functie tussen beide nieren laat zien.","definition":"<p>Met een <strong>DMSA-scan</strong> worden nierlittekens na pyelonefritis opgespoord en de relatieve functie van elke nier gemeten. Een MAG3-renogram laat daarnaast de afvoer zien (bij verdenking op obstructie).</p>","image_url":"","wiki_title":"DMSA scan","match":"dmsa-scan|dmsa","option_only":true},"renografie":{"title":"Renografie (MAG3-scan)","short":"Bij renografie wordt met een radioactieve stof gemeten hoe de nieren de stof opnemen en uitscheiden, om obstructie en de verdeling van de nierfunctie te beoordelen.","definition":"<p>Een <strong>MAG3-renogram</strong> wordt o.a. gebruikt bij hydronefrose, om te onderscheiden of er een echte afvoerbelemmering is, en om de bijdrage van elke nier te bepalen.</p>","image_url":"","wiki_title":"Renal scintigraphy","match":"renografie|renogram|mag3","option_only":true},"hydrocele":{"title":"Hydrokèle","short":"Een hydrokèle is vocht rond de testis in de tunica vaginalis; de zwelling licht op bij doorschijnen met een lampje.","definition":"<p>Bij baby's is een <strong>hydrokèle</strong> vaak het gevolg van een open processus vaginalis en verdwijnt ze meestal vanzelf; als de zwelling in grootte wisselt, is er een verbinding met de buikholte (risico op liesbreuk). Bij volwassenen kan een hydrokèle reactief zijn bij een infectie of tumor.</p>","image_url":"","wiki_title":"Hydrocele","match":"hydrocele|hydrokèle","option_only":true},"torsio testis":{"title":"Torsio testis","short":"Bij een torsio testis draait de zaadbal om de zaadstreng, waardoor de bloedtoevoer afknelt; een urologisch spoedgeval.","definition":"<p>Een <strong>torsio testis</strong> komt vooral voor bij pasgeborenen en adolescenten. Er is plotseling hevige pijn in het scrotum, vaak met misselijkheid; de testis staat hoog en dwars en de cremasterreflex is afwezig. Binnen zes uur opereren geeft de beste kans om de testis te redden.</p>","image_url":"","wiki_title":"Testicular torsion","match":"torsio testis|testistorsie","option_only":true},"gallig braken":{"title":"Gallig braken","short":"Gallig (groen) braken bij een pasgeborene wijst op een obstructie voorbij de papil van Vater en is een spoedgeval.","definition":"<p>Bij een baby met <strong>gallig braken</strong> moet direct een malrotatie met volvulus worden uitgesloten; ook duodenum- of dunnedarmatresie en de ziekte van Hirschsprung zijn mogelijke oorzaken.</p>","image_url":"","wiki_title":"Bilious vomiting","match":"gallig braken|galbraken","option_only":true},"oesofagusatresie":{"title":"Oesofagusatresie","short":"Bij oesofagusatresie is de slokdarm bij de geboorte onderbroken, meestal met een fistel naar de trachea.","definition":"<p>Een baby met <strong>oesofagusatresie</strong> kwijlt veel en verslikt en hoest bij de eerste voeding; een maagsonde kan niet worden opgevoerd. Prenataal kan een polyhydramnion zijn opgevallen. Het maakt soms deel uit van de VACTERL-associatie. Behandeling is chirurgisch.</p>","image_url":"","wiki_title":"Esophageal atresia","match":"oesofagusatresie|slokdarmatresie","option_only":true},"duodenumatresie":{"title":"Duodenumatresie","short":"Bij duodenumatresie is het duodenum bij de geboorte afgesloten, met (gallig) braken en een ‘double bubble’ op de röntgenfoto.","definition":"<p><strong>Duodenumatresie</strong> komt vaak voor bij kinderen met het syndroom van Down. Prenataal kan er een polyhydramnion zijn. Behandeling is chirurgisch.</p>","image_url":"","wiki_title":"Duodenal atresia","match":"duodenumatresie","option_only":true},"idiopathische kleine lengte":{"title":"Idiopathische kleine lengte","short":"Bij idiopathische kleine lengte is een kind duidelijk kleiner dan leeftijdsgenoten zonder aanwijsbare oorzaak.","definition":"<p>Bij de beoordeling van <strong>kleine lengte</strong> wordt gekeken naar de groeicurve (groeisnelheid), de ouderlengte (target height) en de botleeftijd. Familiaire kleine lengte en een constitutionele groeivertraging zijn het meest voorkomend; afwijkend zijn o.a. een afbuigende groeicurve, disproportie en dysmorfe kenmerken (bijv. Turner, groeihormoontekort, coeliakie).</p>","image_url":"","wiki_title":"Idiopathic short stature","match":"idiopathische kleine lengte|kleine lengte","option_only":true},"eosinofilie":{"title":"Eosinofilie","short":"Eosinofilie is een verhoogd aantal eosinofiele granulocyten in het bloed, vaak door allergie, parasieten of geneesmiddelen.","definition":"<p>Oorzaken van <strong>eosinofilie</strong> zijn o.a. allergische aandoeningen (astma, eczeem), wormen (vooral bij weefselinvasie), geneesmiddelreacties (DRESS), EGPA, bijnierinsufficiëntie en hematologische ziekten. Langdurige sterke eosinofilie kan orgaanschade geven (o.a. hart).</p>","image_url":"","wiki_title":"Eosinophilia","match":"eosinofilie","option_only":true},"monocytose":{"title":"Monocytose","short":"Monocytose is een verhoogd aantal monocyten in het bloed, bijv. bij chronische infecties of herstel van een infectie.","definition":"<p>Oorzaken van <strong>monocytose</strong> zijn o.a. tuberculose, endocarditis, herstel na een acute infectie, IBD, sarcoïdose en hematologische ziekten (chronische myelomonocytaire leukemie).</p>","image_url":"","wiki_title":"Monocytosis","match":"monocytose","option_only":true},"toxocara spp":{"title":"Toxocara (hondenspoelworm)","short":"Toxocara is een spoelworm van honden en katten; bij mensen kunnen de larven door organen of het oog zwerven.","definition":"<p>Kinderen raken besmet door eitjes uit grond of zandbakken. <strong>Toxocariasis</strong> verloopt vaak zonder klachten, maar kan eosinofilie, koorts en hepatomegalie geven (visceral larva migrans) of een ontsteking in het oog (ocular larva migrans).</p>","image_url":"","wiki_title":"Toxocariasis","match":"toxocara spp|toxocara|toxocariasis","option_only":true},"trichuris trichiura":{"title":"Trichuris trichiura (zweepworm)","short":"Trichuris trichiura is een zweepworm die via eitjes in besmette grond wordt opgelopen en in het colon leeft.","definition":"<p>Zware infecties met <strong>Trichuris</strong> geven diarree, bloedverlies, anemie en bij kinderen soms een rectumprolaps en groeiachterstand. Behandeling met mebendazol of albendazol.</p>","image_url":"","wiki_title":"Trichuriasis","match":"trichuris trichiura|zweepworm","option_only":true},"elefantiasis":{"title":"Elefantiasis (lymfatische filariasis)","short":"Elefantiasis is een ernstige zwelling van ledematen of genitaliën door blokkade van lymfevaten, vaak door filariawormen.","definition":"<p>Bij <strong>lymfatische filariasis</strong> brengen muggen de larven van <em>Wuchereria bancrofti</em> over; de volwassen wormen beschadigen lymfevaten, met lymfoedeem en hydrokèle. Wereldwijd wordt de ziekte bestreden met massabehandeling.</p>","image_url":"","wiki_title":"Lymphatic filariasis","match":"elefantiasis|filariasis|lymfatische filariasis","option_only":true},"lassa-koorts":{"title":"Lassakoorts","short":"Lassakoorts is een virale hemorragische koorts in West-Afrika, overgedragen via urine en uitwerpselen van ratten.","definition":"<p><strong>Lassakoorts</strong> verloopt vaak mild, maar kan ernstige bloedingen, shock en doofheid geven. Overdracht van mens op mens via lichaamsvloeistoffen is mogelijk, vooral in ziekenhuizen. Vroeg gegeven ribavirine kan helpen.</p>","image_url":"","wiki_title":"Lassa fever","match":"lassa-koorts|lassakoorts","option_only":true},"syndroom van cushing":{"title":"Syndroom van Cushing","short":"Het syndroom van Cushing is het geheel van klachten door langdurig te veel cortisol.","definition":"<p>Kenmerken van <strong>Cushing</strong>: centrale obesitas, vollemaansgezicht, buffalo hump, paarse striae, dunne huid, spierzwakte, hypertensie, diabetes, osteoporose en stemmingsklachten. De meest voorkomende oorzaak is gebruik van corticosteroïden. Endogene oorzaken: een ACTH-producerend hypofyseadenoom (ziekte van Cushing), ectopische ACTH-productie of een bijniertumor.</p>","image_url":"","wiki_title":"Cushing's syndrome","match":"syndroom van cushing|cushing|hypercortisolisme|morbus cushing|overmatig gebruik van corticosteroïden","option_only":true},"allergische bronchopulmonale alveolitis":{"title":"Allergische bronchopulmonale aspergillose (ABPA)","short":"ABPA is een overgevoeligheidsreactie op Aspergillus in de luchtwegen, vooral bij astma en cystische fibrose.","definition":"<p>Bij <strong>ABPA</strong> zijn er moeilijk te behandelen astma, bruine slijmproppen, eosinofilie, een zeer hoog totaal IgE en specifiek IgE tegen <em>Aspergillus</em>, met centrale bronchiëctasieën. Behandeling met prednison en eventueel itraconazol.</p>","image_url":"","wiki_title":"Allergic bronchopulmonary aspergillosis","match":"allergische bronchopulmonale alveolitis|abpa|allergische bronchopulmonale aspergillose","option_only":true},"afstervingsfase":{"title":"Bacteriële groeicurve","short":"De groeicurve van bacteriën in een kweek bestaat uit een lagfase, exponentiële (log)fase, stationaire fase en afstervingsfase.","definition":"<p>In de <strong>lagfase</strong> passen bacteriën zich aan, in de <strong>logfase</strong> delen ze maximaal (gevoeligst voor celwandantibiotica), in de <strong>stationaire fase</strong> zijn voedingsstoffen op en ontstaan vaak sporen en toxines, en daarna volgt de <strong>afstervingsfase</strong>.</p>","image_url":"","wiki_title":"Bacterial growth","match":"afstervingsfase|lagfase|logfase|stationaire fase|groeicurve","option_only":true},"geconjugeerde hyperbilirubinemie":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerde hyperbilirubinemie","option_only":true},"ongeconjugeerde hyperbiliribinumie":{"title":"Ongeconjugeerd bilirubine","short":"Ongeconjugeerd bilirubine is het in vet oplosbare bilirubine dat bij de afbraak van heem ontstaat, voordat de lever het koppelt aan glucuronzuur.","definition":"<p>Bij afbraak van hemoglobine ontstaat <strong>ongeconjugeerd bilirubine</strong>, dat aan albumine gebonden naar de lever gaat. Daar koppelt UGT1A1 het aan glucuronzuur (geconjugeerd, wateroplosbaar). Een verhoogd ongeconjugeerd bilirubine past bij hemolyse, het syndroom van Gilbert of neonatale icterus; bij pasgeborenen kan het de bloed-hersenbarrière passeren (kernicterus).</p>","image_url":"","wiki_title":"Bilirubin","match":"ongeconjugeerde hyperbiliribinumie","option_only":true},"voedselintolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"voedselintolerantie","option_only":true},"clavicula fractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"clavicula fractuur","option_only":true},"haemophilus influenza type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza type b","option_only":true},"haemofilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemofilus influenzae","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"pulmonale tuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"pulmonale tuberculose","option_only":true},"primaire longtuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"primaire longtuberculose","option_only":true},"pulmonale tb met cavernes":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"pulmonale tb met cavernes","option_only":true},"open tuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"open tuberculose","option_only":true},"candida-infectie":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida-infectie","option_only":true},"respiratoir syncytieelvirus (rsv)":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"respiratoir syncytieelvirus (rsv)","option_only":true},"rs-bronchiolitis":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"rs-bronchiolitis","option_only":true},"rsv bronchiolitis":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"rsv bronchiolitis","option_only":true},"een parasympaticolyticum":{"title":"Anticholinergicum (luchtwegen)","short":"Inhalatie-anticholinergica (ipratropium, tiotropium) blokkeren muscarinereceptoren in de luchtwegen en geven bronchodilatatie.","definition":"<p>Langwerkende <strong>anticholinergica</strong> (LAMA, bijv. tiotropium) zijn een basismiddel bij COPD; kortwerkend ipratropium wordt bij exacerbaties gebruikt. Bijwerkingen: droge mond en zelden urineretentie of glaucoom.</p>","image_url":"","wiki_title":"Anticholinergic","match":"een parasympaticolyticum","option_only":true},"een beta-2-sympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-2-sympaticomimeticum","option_only":true},"kortwerkend beta-2-ympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"kortwerkend beta-2-ympaticomimeticum","option_only":true},"een inhalatiesteroïd":{"title":"Inhalatiecorticosteroïd (ICS)","short":"Inhalatiecorticosteroïden remmen de ontsteking in de luchtwegen; ze zijn de basis van de onderhoudsbehandeling van astma.","definition":"<p><strong>ICS</strong> verminderen ontsteking, hyperreactiviteit en aanvallen. Lokale bijwerkingen zijn heesheid en spruw (mond spoelen na gebruik). Bij COPD worden ze vooral gegeven bij frequente exacerbaties en eosinofilie, omdat ze het pneumonierisico verhogen.</p>","image_url":"","wiki_title":"Inhaled corticosteroid","match":"een inhalatiesteroïd","option_only":true},"een leukotrieenreceptorantagonist":{"title":"Leukotrieenreceptorantagonist (montelukast)","short":"Montelukast blokkeert de receptor voor cysteinyl-leukotriënen en wordt als aanvullend middel bij astma gebruikt.","definition":"<p><strong>Montelukast</strong> is een tablet, wat handig is bij jonge kinderen en inspanningsastma. Het is minder effectief dan inhalatiecorticosteroïden. Een bekende bijwerking zijn stemmings- en gedragsveranderingen en nachtmerries.</p>","image_url":"","wiki_title":"Montelukast","match":"een leukotrieenreceptorantagonist","option_only":true},"trichomoniasi":{"title":"Trichomonas vaginalis","short":"Trichomonas vaginalis is een seksueel overdraagbare protozo die vaginitis met schuimende, groengele afscheiding veroorzaakt.","definition":"<p><strong>Trichomoniasis</strong> geeft bij vrouwen jeuk, branderigheid en riekende, schuimende afscheiding, soms met een ‘aardbeiencervix’; bij mannen meestal geen klachten. De beweeglijke flagellaten zijn soms te zien in een nat preparaat; PCR is gevoeliger. Behandeling met metronidazol, ook voor de partner.</p>","image_url":"","wiki_title":"Trichomoniasis","match":"trichomoniasi","option_only":true},"intercellulair adhesie molecuul 1":{"title":"ICAM-1","short":"ICAM-1 is een adhesiemolecuul op geactiveerd endotheel dat via integrines (LFA-1) leukocyten stevig laat binden.","definition":"<p><strong>ICAM-1</strong> behoort tot de immunoglobuline-superfamilie en wordt door IL-1 en TNF op endotheel tot expressie gebracht. Het bindt aan integrines zoals LFA-1 en Mac-1 op leukocyten, wat vaste adhesie en transmigratie mogelijk maakt. ICAM-1 is ook de receptor voor de meeste rhinovirussen.</p>","image_url":"","wiki_title":"ICAM-1","match":"intercellulair adhesie molecuul 1","option_only":true},"icam (intercellulair adhesiemolecuul)":{"title":"ICAM-1","short":"ICAM-1 is een adhesiemolecuul op geactiveerd endotheel dat via integrines (LFA-1) leukocyten stevig laat binden.","definition":"<p><strong>ICAM-1</strong> behoort tot de immunoglobuline-superfamilie en wordt door IL-1 en TNF op endotheel tot expressie gebracht. Het bindt aan integrines zoals LFA-1 en Mac-1 op leukocyten, wat vaste adhesie en transmigratie mogelijk maakt. ICAM-1 is ook de receptor voor de meeste rhinovirussen.</p>","image_url":"","wiki_title":"ICAM-1","match":"icam (intercellulair adhesiemolecuul)","option_only":true},"rotavirusinfectie":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirusinfectie","option_only":true},"pneumonie door pneumokokken":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"pneumonie door pneumokokken","option_only":true},"mycoplasmapneumonie":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasmapneumonie","option_only":true},"aspiratie corpus alienum":{"title":"Corpus alienum in de luchtweg","short":"Een corpus alienum in de luchtweg is een ingeademd vreemd voorwerp; bij jonge kinderen een belangrijke oorzaak van plotselinge benauwdheid.","definition":"<p>Bij <strong>aspiratie van een vreemd voorwerp</strong> (vaak pinda's, speelgoedonderdelen) ontstaan plotseling hoesten, verslikken en benauwdheid; later kan een eenzijdig piepen, verminderd ademgeruis of een recidiverende pneumonie optreden. Het voorwerp komt vaak in de rechter hoofdbronchus terecht. Verwijdering via een bronchoscopie.</p>","image_url":"","wiki_title":"Foreign body aspiration","match":"aspiratie corpus alienum","option_only":true},"malaria tropica":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria tropica","option_only":true},"plasmodium falciparum-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum-malaria","option_only":true},"plasmodium vivax-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium vivax-malaria","option_only":true},"plasmodium spp":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium spp","option_only":true},"malariaparasiet":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malariaparasiet","option_only":true},"ziekte van lyme":{"title":"Borrelia burgdorferi","short":"Borrelia burgdorferi is de spirocheet die door teken wordt overgebracht en de ziekte van Lyme veroorzaakt.","definition":"<p><strong><em>Borrelia burgdorferi</em></strong> wordt overgebracht door de schapenteek (<em>Ixodes ricinus</em>), meestal pas na een aanhechting van meer dan 24 uur. Vroege lokale infectie geeft erythema migrans; verspreiding kan leiden tot neuroborreliose, lyme-artritis, carditis (AV-blok) en huidafwijkingen (acrodermatitis). Behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Borrelia burgdorferi","match":"ziekte van lyme","option_only":true},"kinderverlamming (polio)":{"title":"Poliomyelitis","short":"Polio is een virale infectie (poliovirus, enterovirus) die bij een klein deel van de patiënten motorische voorhoorncellen beschadigt en slappe verlamming geeft.","definition":"<p><strong>Poliomyelitis</strong> wordt veroorzaakt door het poliovirus, een niet-omhuld RNA-enterovirus dat fecaal-oraal wordt overgedragen.</p><p>De meeste infecties verlopen zonder of met milde klachten. Bij een klein deel infecteert het virus de motorische <em>voorhoorncellen</em> van het ruggenmerg, met asymmetrische slappe verlamming zonder gevoelsverlies. Door vaccinatie (DKTP) is polio in Nederland vrijwel verdwenen.</p>","image_url":"","wiki_title":"Polio","match":"kinderverlamming (polio)","option_only":true},"hepatitis-b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis-b","option_only":true},"tachypnoe":{"title":"Tachypneu","short":"Tachypneu is een te snelle ademhaling, bij volwassenen meer dan ongeveer 20 per minuut.","definition":"<p><strong>Tachypneu</strong> komt voor bij koorts, pijn, angst, longaandoeningen, hartfalen, sepsis en metabole acidose (compenserend). Een verhoogde ademfrequentie is een belangrijk alarmsignaal in vroege-waarschuwingsscores. Bij kinderen gelden leeftijdsafhankelijke grenzen.</p>","image_url":"","wiki_title":"Tachypnea","match":"tachypnoe","option_only":true},"chronisch veneuze insufficiëntie":{"title":"Chronische veneuze insufficiëntie","short":"Bij chronische veneuze insufficiëntie werkt de veneuze terugstroom uit de benen slecht, met oedeem, huidverkleuring en uiteindelijk ulcera.","definition":"<p>Door lekkende kleppen of een doorgemaakte trombose (posttrombotisch syndroom) stijgt de veneuze druk in de benen. Gevolgen: varices, oedeem, hyperpigmentatie (hemosiderine), eczeem, lipodermatosclerose, atrophie blanche en een ulcus cruris venosum, typisch rond de mediale enkel. Behandeling met compressietherapie.</p>","image_url":"","wiki_title":"Chronic venous insufficiency","match":"chronisch veneuze insufficiëntie","option_only":true},"astma-aanval":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-aanval","option_only":true},"astma-exacerbatie":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-exacerbatie","option_only":true},"psittacose (chlamydia psittaci)":{"title":"Psittacose","short":"Psittacose is een longontsteking door Chlamydia psittaci, opgelopen via (stof van) besmette vogels.","definition":"<p>Bij <strong>psittacose</strong> zijn er hoge koorts, hoofdpijn, droge hoest en spierpijn, soms met een relatief trage pols. Contact met vogels (papegaaien, duiven) is de belangrijkste aanwijzing. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Psittacosis","match":"psittacose (chlamydia psittaci)","option_only":true},"chlamydia psittaci":{"title":"Psittacose","short":"Psittacose is een longontsteking door Chlamydia psittaci, opgelopen via (stof van) besmette vogels.","definition":"<p>Bij <strong>psittacose</strong> zijn er hoge koorts, hoofdpijn, droge hoest en spierpijn, soms met een relatief trage pols. Contact met vogels (papegaaien, duiven) is de belangrijkste aanwijzing. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Psittacosis","match":"chlamydia psittaci","option_only":true},"pyloryshypertrofie":{"title":"Hypertrofische pylorusstenose","short":"Bij hypertrofische pylorusstenose verdikt de sluitspier van de maag bij zuigelingen, met projectielbraken.","definition":"<p><strong>Pylorusstenose</strong> komt vooral voor bij jongens van 2–8 weken. Er is niet-gallig projectielbraken na de voeding, een hongerige baby, soms een voelbaar ‘olijfje’ en een hypochloremische, hypokaliëmische metabole alkalose. Diagnose met echo; behandeling met een pyloromyotomie na correctie van de elektrolyten.</p>","image_url":"","wiki_title":"Pyloric stenosis","match":"pyloryshypertrofie","option_only":true},"matrixeiwit":{"title":"Capside","short":"Het capside is de eiwitmantel die het genetisch materiaal van een virus omsluit.","definition":"<p>Het <strong>capside</strong> bestaat uit herhaalde eiwiteenheden (capsomeren) en is meestal icosaëdrisch of helixvormig. Samen met het nucleïnezuur vormt het het nucleocapside; omhulde virussen hebben daaromheen nog een lipide-envelop afkomstig van de gastheercel. Niet-omhulde virussen zijn stabieler in de omgeving.</p>","image_url":"","wiki_title":"Capsid","match":"matrixeiwit","option_only":true},"lipide-envelop":{"title":"Virale envelop","short":"Een envelop is de lipide-buitenmantel van sommige virussen, afkomstig van de membraan van de gastheercel.","definition":"<p><strong>Omhulde virussen</strong> (bijv. influenza, hiv, herpes, corona) zijn gevoelig voor uitdroging, zeep, alcohol en detergentia en worden meestal via druppels, bloed of direct contact overgedragen. Niet-omhulde virussen (bijv. norovirus, adenovirus) zijn veel stabieler in de omgeving.</p>","image_url":"","wiki_title":"Viral envelope","match":"lipide-envelop","option_only":true},"nucleocapside eiwit":{"title":"Capside","short":"Het capside is de eiwitmantel die het genetisch materiaal van een virus omsluit.","definition":"<p>Het <strong>capside</strong> bestaat uit herhaalde eiwiteenheden (capsomeren) en is meestal icosaëdrisch of helixvormig. Samen met het nucleïnezuur vormt het het nucleocapside; omhulde virussen hebben daaromheen nog een lipide-envelop afkomstig van de gastheercel. Niet-omhulde virussen zijn stabieler in de omgeving.</p>","image_url":"","wiki_title":"Capsid","match":"nucleocapside eiwit","option_only":true},"dubbelzijdige nieragenesie":{"title":"Bilaterale nieragenesie","short":"Bij bilaterale nieragenesie zijn beide nieren niet aangelegd, met ernstig tekort aan vruchtwater en longhypoplasie als gevolg.","definition":"<p>Bij <strong>bilaterale nieragenesie</strong> ontstaan de nieren niet, doordat de ureterknop niet of verkeerd met het metanefrogene mesoderm in contact komt. Er wordt geen foetale urine gemaakt, met oligo- of anhydramnion. Dat leidt tot de Potter-sequentie: longhypoplasie, een afgeplat gezicht en standsafwijkingen van de ledematen; het is niet met het leven verenigbaar.</p>","image_url":"","wiki_title":"Renal agenesis","match":"dubbelzijdige nieragenesie","option_only":true},"eenzijdige multicysteuze nierdysplasie":{"title":"Multicysteuze nierdysplasie","short":"Bij multicysteuze nierdysplasie is een nier aangelegd als een tros niet-functionerende cysten, door een stoornis in de ontwikkeling.","definition":"<p>Een <strong>eenzijdige</strong> multicysteuze nierdysplasie is vaak een toevalsbevinding op de prenatale echo; de andere nier neemt de functie over en de cysten verdwijnen vaak spontaan. Een <strong>dubbelzijdige</strong> vorm geeft geen urineproductie, oligohydramnion en longhypoplasie (Potter-sequentie).</p>","image_url":"","wiki_title":"Multicystic dysplastic kidney","match":"eenzijdige multicysteuze nierdysplasie","option_only":true},"sikkelcel ziekte":{"title":"Sikkelcelziekte","short":"Sikkelcelziekte is een erfelijke hemoglobinopathie waarbij afwijkend hemoglobine (HbS) bij zuurstoftekort polymeriseert en rode bloedcellen sikkelvormig maakt.","definition":"<p>Bij <strong>sikkelcelziekte</strong> (homozygoot HbS, autosomaal recessief) verstoppen sikkelcellen kleine vaatjes en worden ze snel afgebroken. Gevolgen: pijncrises, hemolytische anemie, acute chest syndrome, herseninfarcten, miltinfarcten (functionele asplenie, infecties met gekapselde bacteriën) en priapisme. Dragerschap beschermt deels tegen malaria. Behandeling o.a. met hydroxycarbamide en transfusies.</p>","image_url":"","wiki_title":"Sickle cell disease","match":"sikkelcel ziekte","option_only":true},"campylobacter spp":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter spp","option_only":true},"aspergillus fumigatis":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus fumigatis","option_only":true},"krentenbaard (impetigo)":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"krentenbaard (impetigo)","option_only":true},"impetigo (krentenbaard)":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"impetigo (krentenbaard)","option_only":true},"rodehondvirus":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rodehondvirus","option_only":true},"neiseria meningitidis":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"neiseria meningitidis","option_only":true},"meningococcen b":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"meningococcen b","option_only":true},"herpes simplex type 1":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplex type 1","option_only":true},"herpes simplexvirusinfectie":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirusinfectie","option_only":true},"bètahemolytische streptokokken groep a":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"bètahemolytische streptokokken groep a","option_only":true},"adenovirusinfectie":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirusinfectie","option_only":true},"een artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"een artritis","option_only":true},"post-operatieve wondinfectie":{"title":"Wondinfectie","short":"Een wondinfectie is een infectie van een (operatie)wond, met roodheid, warmte, pijn, zwelling en eventueel pus.","definition":"<p>Postoperatieve <strong>wondinfecties</strong> worden vaak veroorzaakt door <em>S. aureus</em> of, bij darmchirurgie, door darmbacteriën. Risicofactoren zijn diabetes, obesitas, roken, lange operaties en contaminatie. Behandeling: openen en draineren, eventueel antibiotica.</p>","image_url":"","wiki_title":"Surgical site infection","match":"post-operatieve wondinfectie","option_only":true},"coxsackievirus a":{"title":"Coxsackievirus A (hand-voet-mondziekte)","short":"Coxsackievirus A is een enterovirus dat bij jonge kinderen hand-voet-mondziekte en herpangina veroorzaakt.","definition":"<p>Bij <strong>hand-voet-mondziekte</strong> ontstaan blaasjes en zweertjes in de mond en blaasjes op handpalmen, voetzolen en billen. Het verloopt meestal mild. Overdracht via feces, speeksel en blaasjesvocht.</p>","image_url":"","wiki_title":"Hand, foot, and mouth disease","match":"coxsackievirus a|hand-voet-mondziekte|hand-mond-voetziekte|herpangina","option_only":true},"hand-mond-voetziekte":{"title":"Coxsackievirus A (hand-voet-mondziekte)","short":"Coxsackievirus A is een enterovirus dat bij jonge kinderen hand-voet-mondziekte en herpangina veroorzaakt.","definition":"<p>Bij <strong>hand-voet-mondziekte</strong> ontstaan blaasjes en zweertjes in de mond en blaasjes op handpalmen, voetzolen en billen. Het verloopt meestal mild. Overdracht via feces, speeksel en blaasjesvocht.</p>","image_url":"","wiki_title":"Hand, foot, and mouth disease","match":"hand-mond-voetziekte","option_only":true},"matrix-eiwit":{"title":"Capside","short":"Het capside is de eiwitmantel die het genetisch materiaal van een virus omsluit.","definition":"<p>Het <strong>capside</strong> bestaat uit herhaalde eiwiteenheden (capsomeren) en is meestal icosaëdrisch of helixvormig. Samen met het nucleïnezuur vormt het het nucleocapside; omhulde virussen hebben daaromheen nog een lipide-envelop afkomstig van de gastheercel. Niet-omhulde virussen zijn stabieler in de omgeving.</p>","image_url":"","wiki_title":"Capsid","match":"matrix-eiwit","option_only":true},"cd4":{"title":"CD4","short":"Celoppervlaktemolecuul op onder andere T-helpercellen; dient als receptor waaraan het hiv-virus zich hecht.","definition":"<p><b>CD4</b> is een glycoproteïne op het oppervlak van T-helperlymfocyten (en enkele andere cellen). Het humaan immunodeficiëntievirus (hiv) gebruikt CD4 (samen met een co-receptor) om aan de cel te binden en die binnen te dringen.</p>","image_url":"","wiki_title":"","match":"cd4","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"encefalitis":{"title":"Encefalitis","short":"Ontsteking van het hersenweefsel zelf, meestal door een virus.","definition":"<p>Bij <b>encefalitis</b> is het hersenparenchym ontstoken. De meest bekende oorzaak in Nederland is het herpes simplexvirus (vaak temporaal); daarnaast o.a. andere virussen, auto-immuunencefalitis (zoals anti-NMDA-receptorencefalitis) en postinfectieuze vormen. Klachten: koorts, hoofdpijn, verwardheid, gedragsverandering, epileptische aanvallen en focale uitval. Behandeling bij verdenking: direct aciclovir.</p>","image_url":"","wiki_title":"Encephalitis","match":"encefalitis","option_only":true},"pitting oedeem":{"title":"Pitting oedeem","short":"Vochtophoping in het weefsel waarbij een ingedrukte put langzaam terugveert; o.a. bij hartfalen.","definition":"<p>Pitting oedeem is perifere vochtophoping waarbij druk met de vinger een blijvende indeuking geeft. Bij dikke enkels past het bij rechtszijdig hartfalen of overvulling.</p>","image_url":"","wiki_title":"","match":"pitting oedeem","option_only":true},"acetylcholinereceptor":{"title":"Acetylcholinereceptor-antistoffen","short":"Antistoffen tegen de acetylcholinereceptor van de neuromusculaire overgang, kenmerkend voor myasthenia gravis. Geven wisselende, ergonome spierzwakte.","definition":"<p>Bij <b>myasthenia gravis</b> blokkeren <b>acetylcholinereceptor</b>-antistoffen de prikkeloverdracht, met belastingsafhankelijke zwakte (o.a. dubbelzien, zwakte 's avonds).</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"acetylcholinereceptor","option_only":true},"lipoteichoïne zuur":{"title":"Teichoïnezuur","short":"Teichoïnezuren zijn polymeren in de dikke peptidoglycaanlaag van grampositieve bacteriën; ze dragen bij aan hechting en ontstekingsactivatie.","definition":"<p><strong>Teichoïnezuren</strong> zijn polymeren van glycerol- of ribitolfosfaat die verankerd zijn in de peptidoglycaanlaag (wandteichoïnezuur) of in de celmembraan (lipoteichoïnezuur) van <em>grampositieve</em> bacteriën.</p><p>Ze geven de celwand een negatieve lading, helpen bij hechting aan gastheercellen en worden door Toll-like receptoren (TLR2) herkend, waardoor ze een ontstekingsreactie uitlokken. Gramnegatieve bacteriën hebben ze niet.</p>","image_url":"","wiki_title":"Teichoic acid","match":"lipoteichoïne zuur","option_only":true},"laryngitis subglottica (croup, pseudokroep)":{"title":"Laryngitis subglottica (pseudokroep)","short":"Pseudokroep is een virale ontsteking onder de stembanden bij jonge kinderen, met blafhoest, heesheid en inspiratoire stridor.","definition":"<p><strong>Pseudokroep</strong> wordt meestal veroorzaakt door para-influenzavirussen en treedt vaak ’s nachts op bij kinderen van 6 maanden tot 3 jaar. Behandeling: geruststellen en bij matig tot ernstige klachten dexamethason; bij ernstige stridor in rust adrenalinevernevelingen. Het moet onderscheiden worden van epiglottitis.</p>","image_url":"","wiki_title":"Croup","match":"laryngitis subglottica (croup, pseudokroep)","option_only":true},"myelinisatie":{"title":"Myelinisatie","short":"Vorming van een vetrijke isolerende schede rond axonen, door oligodendrocyten (CZS) en Schwann-cellen (PZS).","definition":"<p>Bij <b>myelinisatie</b> wikkelen oligodendrocyten in het centrale en Schwann-cellen in het perifere zenuwstelsel hun membraan in lagen om axonen. Daardoor kan de actiepotentiaal van insnoering naar insnoering springen (saltatoire geleiding). Myelinisatie begint prenataal en gaat door tot ver na de geboorte, waarbij de prefrontale cortex als een van de laatste gebieden volgt.</p>","image_url":"","wiki_title":"Myelination","match":"myelinisatie","option_only":true},"regressie":{"title":"Lineaire regressie","short":"Statistische techniek om een continue uitkomst te voorspellen uit één of meer predictoren via een rechte lijn (Y = b0 + b1·X).","definition":"<p><b>Lineaire regressie</b> modelleert het verband tussen een <i>continue uitkomstvariabele</i> en één of meer onafhankelijke variabelen. Het intercept <b>b0</b> is de voorspelde waarde als alle predictoren 0 zijn; de coëfficiënt <b>b1</b> is de verandering in de uitkomst per eenheid toename van de predictor. Bij een dichotome predictor is b1 het verschil tussen de twee groepen.</p>","image_url":"","wiki_title":"Linear regression","match":"regressie","option_only":true},"eczeem":{"title":"Eczeem","short":"Eczeem is een oppervlakkige, jeukende ontsteking van de huid; acuut gekenmerkt door roodheid en vesikels, chronisch door lichenificatie en schilfering.","definition":"<p><strong>Eczeem</strong> (dermatitis) is een spongiotische huidontsteking. <em>Acuut</em>: erytheem, vesikels, nattend, jeuk — histologisch <em>spongiose</em> (intercellulair oedeem). <em>Chronisch</em>: lichenificatie, schilfering, hyperkeratose.</p><p>Vormen: constitutioneel (atopisch) eczeem, allergisch contacteczeem (type IV, plakproeven positief) en orthoergisch/irritatief contacteczeem (niet-immunologisch).</p>","image_url":"","wiki_title":"Dermatitis","match":"eczeem","option_only":true},"x-gebonden agammaglobulinemie (ziekte van bruton)":{"title":"X-gebonden agammaglobulinemie (Bruton)","short":"Erfelijk B-celdefect (BTK-mutatie) waardoor B-cellen niet uitrijpen en er nagenoeg geen antilichamen worden gemaakt.","definition":"<p>Bij <b>X-gebonden agammaglobulinemie (ziekte van Bruton)</b> ontbreekt het functionele enzym BTK, waardoor B-cellen stoppen in hun ontwikkeling (pro-/pre-B-cel stadium). Er ontstaan vrijwel geen rijpe B-cellen en immunoglobulinen, met recidiverende bacteriële infecties.</p>","image_url":"","wiki_title":"X-linked agammaglobulinemia","match":"x-gebonden agammaglobulinemie (ziekte van bruton)","option_only":true},"common variable immune deficiency (cvid)":{"title":"CVID","short":"Common variable immune deficiency is een afweerstoornis met lage immunoglobulines en recidiverende infecties. Er is ook een verhoogd risico op auto-immuunziekten en maligniteiten.","definition":"<p>Common Variable Immune Deficiency: primaire immuundeficiëntie met verlaagde antistofproductie, recidiverende (lucht)weginfecties en een verhoogde kans op <strong>auto-immuunziekten</strong> en <strong>maligniteiten</strong>.</p>","image_url":"","wiki_title":"Common variable immunodeficiency","match":"common variable immune deficiency (cvid)","option_only":true},"irritatie door aarsmaden (enterobius vermicularis)":{"title":"Enterobius vermicularis (aarsmade)","short":"Wormpje dat de dikke darm en het coecum bewoont en anale jeuk veroorzaakt, vooral bij kinderen.","definition":"<p><b>Enterobius vermicularis</b> (aarsmade) is een darmworm die leeft in het coecum en de dikke darm. De vrouwtjes leggen 's nachts eieren rond de anus, wat de typische anale jeuk veroorzaakt.</p>","image_url":"","wiki_title":"Enterobius vermicularis","match":"irritatie door aarsmaden (enterobius vermicularis)","option_only":true},"streptococcus agalactiae (streptokok groep b)":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt voor in darm en vagina en is een belangrijke verwekker van sepsis en meningitis bij pasgeborenen.","definition":"<p><strong>Groep B-streptokokken</strong> (<em>Streptococcus agalactiae</em>) zijn grampositieve, bètahemolytische ketenkokken. Ze komen bij een deel van de vrouwen voor in darm en vagina zonder klachten.</p><p>Tijdens de bevalling kan de baby besmet raken, met risico op neonatale sepsis, pneumonie en meningitis (vooral in de eerste levensdagen). Bij risicofactoren krijgt de moeder antibiotica tijdens de bevalling.</p>","image_url":"","wiki_title":"Group B streptococcal infection","match":"streptococcus agalactiae (streptokok groep b)","option_only":true},"heesheid":{"title":"Heesheid","short":"Verandering van de stemkwaliteit (hese, schorre stem) door aandoening van de stembanden of larynx.","definition":"<p>Heesheid (dysfonie) ontstaat bij afwijkingen van de stemplooien of hun innervatie. Aanhoudende heesheid (>3 weken) bij een roker is een alarmsymptoom voor larynxcarcinoom.</p>","image_url":"","wiki_title":"Hoarse voice","match":"heesheid","option_only":true},"onychomycose":{"title":"Onychomycose","short":"Onychomycose is een schimmelinfectie van de nagel, met verdikking, verkleuring en brokkeligheid van de nagelplaat.","definition":"<p><strong>Onychomycose</strong> is een infectie van de nagel door dermatofyten (meestal Trichophyton). De nagel wordt geel-bruin, verdikt en brokkelig, vaak beginnend distaal. Bevestiging met KOH-preparaat of kweek.</p>","image_url":"","wiki_title":"Onychomycosis","match":"onychomycose","option_only":true},"plakbandpreparaat":{"title":"Plakbandpreparaat","short":"Diagnostische test voor enterobiasis (aarsmade): eieren rond de anus worden met plakband opgenomen en microscopisch bekeken.","definition":"<p>Diagnostische methode voor <b>enterobiasis</b> (aarsmadeinfectie): 's ochtends wordt met doorzichtig plakband perianaal materiaal afgenomen om de eieren van <i>Enterobius vermicularis</i> microscopisch aan te tonen.</p>","image_url":"","wiki_title":"","match":"plakbandpreparaat","option_only":true},"talipes equinovalgus":{"title":"Klompvoet (pes equinovarus)","short":"Een klompvoet is een aangeboren standsafwijking met de voet in spitsvoetstand, naar binnen gekanteld en gedraaid.","definition":"<p>Bij een <strong>klompvoet</strong> staat de voet in equinus, varus, adductus en cavus. Behandeling volgens Ponseti: wekelijks gipsen, vaak een kleine doorsnijding van de achillespees en daarna jarenlang een spreidbeugel ’s nachts om terugval te voorkomen.</p>","image_url":"","wiki_title":"Clubfoot","match":"talipes equinovalgus","option_only":true},"talipes calcaneovarus":{"title":"Klompvoet (pes equinovarus)","short":"Een klompvoet is een aangeboren standsafwijking met de voet in spitsvoetstand, naar binnen gekanteld en gedraaid.","definition":"<p>Bij een <strong>klompvoet</strong> staat de voet in equinus, varus, adductus en cavus. Behandeling volgens Ponseti: wekelijks gipsen, vaak een kleine doorsnijding van de achillespees en daarna jarenlang een spreidbeugel ’s nachts om terugval te voorkomen.</p>","image_url":"","wiki_title":"Clubfoot","match":"talipes calcaneovarus","option_only":true},"ademhalingsdepressie":{"title":"Ademhalingsdepressie","short":"Verminderde ademhaling door onderdrukking van het ademcentrum, een gevreesde bijwerking van opioïden.","definition":"<p>Ademhalingsdepressie is een afgenomen ademfrequentie en -diepte door remming van het ademcentrum in de hersenstam. Bij opioïdgebruik is dit een ernstige bijwerking, zeker bij een voorgeschiedenis van ernstig astma.</p>","image_url":"","wiki_title":"Hypoventilation","match":"ademhalingsdepressie","option_only":true},"na⁺":{"title":"Natrium","short":"Natrium is het belangrijkste kation buiten de cel; het bepaalt grotendeels het extracellulaire volume en de osmolaliteit.","definition":"<p><strong>Natrium</strong> wordt door de Na⁺/K⁺-ATPase buiten de cel gehouden, waardoor een gradiënt ontstaat die nodig is voor actiepotentialen en secundair actief transport. De hoeveelheid natrium in het lichaam bepaalt het extracellulaire volume (via RAAS en natriuretische peptiden); de natriumconcentratie weerspiegelt vooral de waterbalans (via ADH en dorst).</p>","image_url":"","wiki_title":"Sodium in biology","match":"na⁺","option_only":true},"turner syndroom":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"turner syndroom","option_only":true},"verhoogde oogboldruk (glaucoom)":{"title":"Glaucoom","short":"Beschadiging van de oogzenuw, vaak door verhoogde oogdruk, met blijvend gezichtsvelduitval.","definition":"<p>Glaucoom is een progressieve beschadiging van de nervus opticus, vaak samenhangend met een verhoogde oogboldruk. Het veroorzaakt onomkeerbare gezichtsvelduitval en kan onbehandeld tot blindheid leiden.</p>","image_url":"","wiki_title":"Glaucoma","match":"verhoogde oogboldruk (glaucoom)","option_only":true},"humaan metapneumovirus":{"title":"Humaan Metapneumovirus (HMPV)","short":"RSV-verwant virus dat bij jonge kinderen bronchiolitis en pneumonie kan geven, met een vergelijkbaar klinisch beeld als RSV.","definition":"<p><b>Humaan Metapneumovirus (HMPV)</b> is nauw verwant aan RSV en veroorzaakt luchtweginfecties bij jonge kinderen, variërend van verkoudheid tot bronchiolitis en pneumonie. Het beeld lijkt sterk op dat van RSV.</p>","image_url":"","wiki_title":"Human metapneumovirus","match":"humaan metapneumovirus","option_only":true},"lactose intolerantie":{"title":"Lactose-intolerantie","short":"Bij lactose-intolerantie is er te weinig lactase in de dunne darm, waardoor melksuiker in de dikke darm wordt gefermenteerd.","definition":"<p>Bij <strong>lactose-intolerantie</strong> geeft melk een opgeblazen gevoel, winderigheid, buikkrampen en osmotische diarree. De primaire vorm (afnemende lactase na de kindertijd) komt wereldwijd bij de meerderheid van de volwassenen voor; secundaire vormen ontstaan bij darmschade (bijv. coeliakie, gastro-enteritis). Diagnose met een waterstofademtest of eliminatie.</p>","image_url":"","wiki_title":"Lactose intolerance","match":"lactose intolerantie","option_only":true},"saturatie":{"title":"Zuurstofsaturatie","short":"Percentage hemoglobine dat met zuurstof is verzadigd; maat voor de oxygenatie.","definition":"<p>De (perifere) zuurstofsaturatie (SpO2) geeft aan welk deel van het hemoglobine met O2 is verzadigd. Bij CO-vergiftiging kan de SpO2 vals-normaal zijn.</p>","image_url":"","wiki_title":"Oxygen saturation (medicine)","match":"saturatie","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"kniepeesreflex":{"title":"Kniepeesreflex","short":"Monosynaptische rekkingsreflex van de m. quadriceps femoris (wortel L3-L4), opgewekt door slaan op de patellapees.","definition":"De <b>kniepeesreflex</b> is een monosynaptische reflex: rek van spierspoeltjes in de m. quadriceps femoris leidt direct tot contractie.","image_url":"","wiki_title":"Patellar reflex","match":"kniepeesreflex","option_only":true},"aortaklep stenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortaklep stenose","option_only":true},"aortaklep insufficiëntie":{"title":"Aortaklepinsufficiëntie","short":"Bij aortaklepinsufficiëntie sluit de aortaklep niet goed, waardoor bloed in de diastole terugstroomt naar de linkerventrikel.","definition":"<p>Bij <strong>aortaklepinsufficiëntie</strong> ontstaat volumebelasting van de linkerventrikel, die verwijdt. Oorzaken zijn o.a. een bicuspide klep, endocarditis, verwijding van de aortawortel (hypertensie, Marfan, dissectie). Kenmerkend zijn een diastolisch decrescendo-geruis langs de linker sternumrand en een grote polsdruk (snel stijgende en dalende pols).</p>","image_url":"","wiki_title":"Aortic insufficiency","match":"aortaklep insufficiëntie","option_only":true},"mitralisklep insufficiëntie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralisklep insufficiëntie","option_only":true},"pulmonalisklep insufficiëntie":{"title":"Pulmonalisklepinsufficiëntie","short":"Bij pulmonalisklepinsufficiëntie lekt bloed in de diastole terug van de longslagader naar de rechterventrikel.","definition":"<p>Een lichte lekkage is vaak fysiologisch. Ernstige <strong>pulmonalisinsufficiëntie</strong> komt vooral voor na chirurgische correctie van een tetralogie van Fallot en bij pulmonale hypertensie; het kan leiden tot verwijding en falen van de rechterventrikel.</p>","image_url":"","wiki_title":"Pulmonary valve insufficiency","match":"pulmonalisklep insufficiëntie","option_only":true},"primaire ciliaire dyskinesie (pcd)":{"title":"Primaire ciliaire dyskinesie","short":"Bij primaire ciliaire dyskinesie werken de trilharen niet goed, met chronische luchtweginfecties, bronchiëctasieën en onvruchtbaarheid.","definition":"<p><strong>PCD</strong> erft meestal autosomaal recessief over. Klachten beginnen vaak al bij de geboorte (benauwdheid, chronisch loopneus) en omvatten recidiverende otitis en sinusitis. Bij ongeveer de helft is er een situs inversus (syndroom van Kartagener). Mannen zijn vaak onvruchtbaar door onbeweeglijke zaadcellen.</p>","image_url":"","wiki_title":"Primary ciliary dyskinesia","match":"primaire ciliaire dyskinesie (pcd)","option_only":true},"s. epidermidis":{"title":"Staphylococcus epidermidis","short":"S. epidermidis is een coagulasenegatieve stafylokok van de normale huidflora; berucht om infecties van lijnen en prothesen.","definition":"<p><strong><em>Staphylococcus epidermidis</em></strong> is een grampositieve, <em>coagulase-negatieve</em> stafylokok die normaal op de huid leeft.</p><p>Hij is weinig virulent, maar kan een <em>biofilm</em> vormen op kunstmateriaal. Daardoor is hij een belangrijke verwekker van infecties van intravasculaire katheters, kunstkleppen en gewrichtsprothesen. In een bloedkweek is hij ook vaak een verontreiniging vanuit de huid.</p>","image_url":"","wiki_title":"Staphylococcus epidermidis","match":"s. epidermidis","option_only":true},"apathie":{"title":"Apathie","short":"Verlies van motivatie, initiatief en interesse, zonder dat de patiënt dit zelf als lijden ervaart; veel voorkomend bij dementie en depressie.","definition":"<p><strong>Apathie</strong> is een toestand van verminderde motivatie, initiatiefverlies en emotionele vervlakking. Bij dementie is apathie vaak de grootste belasting voor mantelzorgers.</p>","image_url":"","wiki_title":"Apathy","match":"apathie","option_only":true},"b lymfocyten":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b lymfocyten","option_only":true},"t lymfocyten":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t lymfocyten","option_only":true},"giardia":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardia","option_only":true},"virale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies met een rood oog, waterig, slijmerig of etterig vocht, en een normale visus.","definition":"<p>Een <strong>virale conjunctivitis</strong> (vaak adenovirus) is zeer besmettelijk, met waterig vocht en een gezwollen klier voor het oor. Een bacteriële vorm geeft meer pus en dichtgeplakte ogen; een allergische vorm jeuk. Pijn, lichtschuwheid en verminderde visus wijzen op een ernstigere oorzaak.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale conjunctivitis|bacteriële conjunctivitis|allergische conjunctivitis","option_only":true},"allergisch astma":{"title":"Astmafenotypen","short":"Astma wordt ingedeeld in fenotypen, zoals allergisch astma (met sensibilisatie, vaak beginnend in de jeugd), eosinofiel astma en niet-allergisch astma.","definition":"<p>Bij <strong>allergisch astma</strong> zijn er IgE-antistoffen tegen bijv. huisstofmijt, pollen of dierhaar, en een type 2-ontsteking. Bronchiale hyperreactiviteit (overgevoeligheid van de luchtwegen) is kenmerkend voor alle vormen van astma.</p>","image_url":"","wiki_title":"Asthma","match":"allergisch astma|hyperreactief astma|eosinofiel astma|niet-allergisch astma","option_only":true},"retinal":{"title":"Retinal (vitamine A)","short":"Retinal is de vorm van vitamine A die in het oog aan opsine bindt en zo het lichtgevoelige rodopsine vormt.","definition":"<p>Een tekort aan <strong>vitamine A</strong> geeft nachtblindheid, droge ogen (xeroftalmie) en een verhoogde kans op infecties. Vitamine A en zijn derivaten (isotretinoïne) zijn in hoge doses teratogeen.</p>","image_url":"","wiki_title":"Retinal","match":"retinal|retinol|vitamine a","option_only":true},"parotitis":{"title":"Parotitis","short":"Parotitis is een ontsteking van de oorspeekselklier, viraal (bof) of bacterieel.","definition":"<p><strong>Bof</strong> (mumps) geeft een pijnlijke zwelling van de parotis aan een of beide kanten; complicaties zijn orchitis, meningitis en pancreatitis. Een bacteriële parotitis (vaak <em>S. aureus</em>) komt vooral voor bij uitgedroogde ouderen, met pus uit de afvoergang.</p>","image_url":"","wiki_title":"Parotitis","match":"parotitis|bof","option_only":true},"erythromycine":{"title":"Erytromycine (macroliden)","short":"Erytromycine is een macrolide-antibioticum dat de eiwitsynthese remt via het 50S-ribosoom.","definition":"<p><strong>Macroliden</strong> werken tegen streptokokken, atypische verwekkers (Mycoplasma, Chlamydia, Legionella) en kinkhoest. Erytromycine stimuleert ook de maaglediging (motilinereceptor). Bijwerkingen: maag-darmklachten, QT-verlenging en interacties via CYP3A4 (vooral erytromycine en claritromycine).</p>","image_url":"","wiki_title":"Erythromycin","match":"erythromycine|erytromycine|macroliden|azitromycine|claritromycine","option_only":true},"gentamicine":{"title":"Gentamicine (aminoglycosiden)","short":"Gentamicine is een aminoglycoside dat werkt tegen gramnegatieve bacteriën door de eiwitsynthese via het 30S-ribosoom te verstoren.","definition":"<p><strong>Aminoglycosiden</strong> werken concentratieafhankelijk en worden vaak eenmaal daags gegeven, met spiegelbepalingen. Bijwerkingen zijn nefrotoxiciteit en (blijvende) ototoxiciteit. Ze werken niet tegen anaeroben.</p>","image_url":"","wiki_title":"Gentamicin","match":"gentamicine|aminoglycosiden|tobramycine|amikacine","option_only":true},"levofloxacine":{"title":"Fluorochinolonen","short":"Levofloxacine en ciprofloxacine zijn fluorochinolonen, die bacterieel DNA-gyrase en topo-isomerase IV remmen.","definition":"<p><strong>Fluorochinolonen</strong> werken breed, ook bij gramnegatieve bacteriën en (levofloxacine, moxifloxacine) bij luchtwegpathogenen. Ze hebben ernstige bijwerkingen: peesrupturen, QT-verlenging, aneurysma's en neuropathie, en worden daarom terughoudend gebruikt.</p>","image_url":"","wiki_title":"Fluoroquinolone","match":"levofloxacine|ciprofloxacine|moxifloxacine|fluorochinolonen","option_only":true},"groep- b- streptokok":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt bij veel vrouwen in vagina en darm voor en kan bij pasgeborenen sepsis en meningitis veroorzaken.","definition":"<p>Bij risicofactoren (vroeggeboorte, langdurig gebroken vliezen, koorts tijdens de bevalling, een eerder kind met GBS-ziekte) krijgt de moeder antibiotica tijdens de bevalling. Bij volwassenen geeft <strong>GBS</strong> soms urineweginfecties en huidinfecties.</p>","image_url":"","wiki_title":"Streptococcus agalactiae","match":"groep- b- streptokok|groep b-streptokok|streptococcus agalactiae","option_only":true},"meningocele":{"title":"Meningokèle en spina bifida","short":"Bij een meningokèle puilen alleen de hersenvliezen uit door een defect in de wervelboog; bij een myelomeningokèle ook het ruggenmerg en de zenuwwortels.","definition":"<p>Een <strong>myelomeningokèle</strong> geeft verlamming en gevoelsverlies van de benen, blaas- en darmstoornissen en vaak hydrocefalus (Arnold-Chiari II). Foliumzuur rond de conceptie verlaagt het risico op neuraalbuisdefecten. Een spina bifida occulta geeft meestal geen klachten.</p>","image_url":"","wiki_title":"Spina bifida","match":"meningocele|meningokèle|myelomeningokèle|spina bifida","option_only":true},"aspergillus spp":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus spp","option_only":true},"herpes simplex virus-2":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplex virus-2","option_only":true},"bacteriele tonsillitis":{"title":"Tonsillitis","short":"Tonsillitis is een ontsteking van de keelamandelen, meestal viraal, soms door groep A-streptokokken.","definition":"<p>Bij <strong>tonsillitis</strong> zijn de amandelen rood en gezwollen, soms met beslag, en zijn er keelpijn, slikklachten en koorts. Meestal gaat het om een virus (ook EBV). Bij een bacteriële oorzaak gaat het vaak om groep A-streptokokken. Complicaties zijn een peritonsillair abces (met trismus en uitpuilen van het gehemelte) en zelden acuut reuma.</p>","image_url":"","wiki_title":"Tonsillitis","match":"bacteriele tonsillitis","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"gastro-enteritis, mogelijk het norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"gastro-enteritis, mogelijk het norovirus","option_only":true}};
